-- Astral v4.62 | Isolated single strokes, parked gaps and identical compact burst strokes; scheduled cadence, not server kick prediction.
-- Original authorship/license notices remain in the embedded sources.
local sources = {}
sources.PalletReaction = [========[
-- Read-only target selection and reaction observation. Local contact and
-- observed Ragdolled state are not per-hit acknowledgments. This module only
-- reports fresh state edges, without establishing camera blur or a disconnect.
local Reaction={};Reaction.__index=Reaction
local roots={'HumanoidRootPart','realHrp','realHRP','saviHRP'}
local function living(character)
 return character and character.Parent and character.FindFirstChild and character.FindFirstChildOfClass
end
function Reaction.Resolve(character)
 if not living(character)then return nil,'Unavailable','Character unavailable'end
 local fallbackReason
 for _,name in ipairs(roots)do
  local root=character:FindFirstChild(name)
  local receiver=root and root:FindFirstChild('RagdollTouchedHitbox')
  if receiver then
   local reason
   if not root:IsA('BasePart')or root.Parent~=character then reason='Ragdoll receiver root is invalid'
   elseif not receiver:IsA('BasePart')then reason='RagdollTouchedHitbox is not a BasePart'
   elseif receiver.Parent~=root then reason='Ragdoll receiver was detached'
   elseif receiver.CanTouch~=true then reason='RagdollTouchedHitbox has CanTouch disabled'
   else return receiver,'RagdollTouchedHitbox'end
   fallbackReason=fallbackReason or reason
  end
 end
 if not fallbackReason and character:FindFirstChild('RagdollTouchedHitbox',true)then
  fallbackReason='RagdollTouchedHitbox is outside a supported character root'
 end
 -- The source used Torso. An unusable named hitbox does not establish that
 -- the game's original torso contact path is disabled; preserve that path.
 local reason='Torso receiver unavailable'
 for _,name in ipairs({'Torso','UpperTorso'})do
  local torso=character:FindFirstChild(name)
  if torso and torso:IsA('BasePart')and torso.Parent==character then
   if torso.CanTouch==true then return torso,'TorsoFallback',nil,fallbackReason end
   reason='Torso fallback has CanTouch disabled'
  end
 end
 return nil,'Unavailable',reason,fallbackReason
end
local function inspect(character)
 local receiver,kind,reason,fallbackReason=Reaction.Resolve(character)
 if not living(character)then return nil,nil,receiver,kind,reason,fallbackReason end
 local humanoid=character:FindFirstChildOfClass('Humanoid')
 if not humanoid or humanoid.Parent~=character then return nil,nil,receiver,kind,'Humanoid unavailable',fallbackReason end
 local flag=humanoid:FindFirstChild('Ragdolled')
 if not flag or not flag:IsA('BoolValue')or flag.Parent~=humanoid then
  return humanoid,nil,receiver,kind,'Game Ragdolled flag unavailable',fallbackReason
 end
 if humanoid.Health<=0 then return humanoid,flag,receiver,kind,'Humanoid is not alive',fallbackReason end
 return humanoid,flag,receiver,kind,reason,fallbackReason
end
function Reaction.new(character,clock)
 local self=setmetatable({Character=character,Clock=clock or os.clock,Rises=0,Generation=0,Closed=false},Reaction)
 self:Refresh();return self
end
function Reaction:Disconnect()
 if self.Connection then self.Connection:Disconnect();self.Connection=nil end
end
function Reaction:Sample(payload)
 if not self.Ready or not self.Flag then return end
 local value=payload
 if type(value)~='boolean'then value=self.Flag.Value==true end
 if value and self.LastValue==false then
  self.Rises+=1;self.LastRiseAt=self.Clock()
 end
 self.LastValue=value
end
function Reaction:Refresh(skipSample)
 if self.Closed then return false,'Observer disposed'end
 local humanoid,flag,receiver,kind,reason,fallbackReason=inspect(self.Character)
 local ready=humanoid~=nil and flag~=nil and receiver~=nil and reason==nil
 if humanoid~=self.Humanoid or flag~=self.Flag or receiver~=self.Receiver or ready~=self.Ready then
  self:Disconnect();self.Generation+=1
  self.Humanoid=humanoid;self.Flag=flag;self.Receiver=receiver;self.ReceiverKind=kind
  self.Ready=ready;self.LastValue=flag and flag.Value==true or false;self.Observation=nil
  if ready then
   local generation=self.Generation
   local changed=flag.Changed
   if changed and changed.Connect then
    self.Observation='BoolValueChanged'
    self.Connection=changed:Connect(function(value)
     if self.Closed or self.Flag~=flag or self.Generation~=generation then return end
     -- Changed carries BoolValue's event-time boolean. Under deferred
     -- signals, reading current Value could lose a complete true/false pulse.
     self:Refresh(true)
     if self.Ready and self.Flag==flag and self.Generation==generation and type(value)=='boolean'then self:Sample(value)end
    end)
   else
    local propertyChanged=flag.GetPropertyChangedSignal and flag:GetPropertyChangedSignal('Value')
    if propertyChanged and propertyChanged.Connect then
     self.Observation='ChangedSignal'
     self.Connection=propertyChanged:Connect(function()
      if not self.Closed and self.Flag==flag and self.Generation==generation then self:Refresh()end
     end)
    end
   end
  end
 end
 self.Reason=reason;self.ReceiverKind=kind;self.FallbackReason=fallbackReason
 -- Polling a payload-bound flag could count current true before its deferred
 -- false/true callbacks arrive and then count that same rise a second time.
 if not skipSample and self.Observation~='BoolValueChanged'then self:Sample()end
 return self.Ready,self.Reason
end
function Reaction:StartAttempt()
 local ready,reason=self:Refresh()
 if not ready then return nil,reason end
 return {Observer=self,Generation=self.Generation,Counter=self.Rises,Baseline=self.LastValue,
  Receiver=self.Receiver,Flag=self.Flag,StartedAt=self.Clock()}
end
function Reaction:ObservedSince(attempt)
 local ready,reason=self:Refresh()
 if not ready then return false,reason end
 if not attempt or attempt.Observer~=self or attempt.Generation~=self.Generation or attempt.Receiver~=self.Receiver or attempt.Flag~=self.Flag then
  return false,'Reaction attempt belongs to an old target binding'
 end
 if self.Rises>(attempt.Counter or self.Rises)then return true,'New game ragdoll reaction observed'end
 return false,attempt.Baseline and 'Ragdolled was already true; no new reaction observed'or 'No new game ragdoll reaction observed'
end
function Reaction:Describe()
 self:Refresh()
 return {Ready=self.Ready==true,Reason=self.Closed and 'Observer disposed'or self.Reason,
  Ragdolled=self.Flag and self.Flag.Value==true or false,Rises=self.Rises,LastRiseAt=self.LastRiseAt,
  ReceiverName=self.Receiver and self.Receiver.Name or nil,ReceiverKind=self.ReceiverKind,FallbackReason=self.FallbackReason,
  Generation=self.Generation,Disposed=self.Closed,Observation=self.Connection and self.Observation or 'SampledState'}
end
function Reaction:Dispose()
 if self.Closed then return end
 self.Closed=true;self:Disconnect();self.Ready=false;self.Generation+=1;self.Reason='Observer disposed'
end
return Reaction

]========]
sources.PalletCadence = [========[
-- Per-target physical plans: two isolated strokes, then four compact strokes.
-- Only successful completed traversals advance this local schedule. It does
-- not infer accepted game hits, camera blur or an imminent server disconnect.
local Cadence={}
local function finite(value)
 return type(value)=='number'and value==value and math.abs(value)<math.huge
end
local function pingSeconds(value)
 if not finite(value)or value<0 then return .1 end
 return value
end
local function state(entry)
 local current=entry.PalletCadence
 if not current then current={Step=0};entry.PalletCadence=current end
 return current
end
function Cadence.Plan(entry,ping)
 local current=state(entry)
 if current.Plan then return current.Plan end
 local single=current.Step<2
 local index=single and current.Step+1 or current.Step-1
 local gap=single and math.clamp(.6+pingSeconds(ping)*.5,.65,1)or(index==4 and 1 or 0)
 current.Plan=table.freeze({Speed=48,ClearSeconds=.06,Phase=single and'Single'or'Burst',Index=index,GapSeconds=gap})
 return current.Plan
end
function Cadence.Ready(entry,now)
 local current=entry.PalletCadence
 if not current then return true end
 if not finite(now)or(current.CompletedAt and now<current.CompletedAt)then return false end
 return not current.Deadline or now+1e-7>=current.Deadline
end
function Cadence.WaitSeconds(entry,now)
 local current=entry.PalletCadence
 if not current then return 0 end
 if not finite(now)or(current.CompletedAt and now<current.CompletedAt)then return 1 end
 return current.Deadline and math.clamp(current.Deadline-now,0,1)or 0
end
function Cadence.Completed(entry,now)
 local current=entry.PalletCadence
 -- An unplanned, duplicate or stale callback must not advance the sequence.
 if not current or not current.Plan or not finite(now)or not Cadence.Ready(entry,now)then return false end
 local gap=current.Plan.GapSeconds
 local deadline=now+gap
 if not finite(deadline)or(gap>0 and deadline<=now)then return false end
 current.Step=(current.Step+1)%6;current.CompletedAt=now;current.Deadline=deadline;current.Plan=nil
 return true
end
function Cadence.Reset(entry)entry.PalletCadence=nil end
return Cadence

]========]
sources.KickHandoff = [========[
-- Request phases are observations of the local ownership state, never proof of
-- a server kick. Hold movers and the independent pallet are outside this gate.
local Handoff={}
local function pingSeconds(value)
 if type(value)~='number'or value~=value or math.abs(value)==math.huge then return .1 end
 return math.clamp(value,0,1.2)
end
local function observe(phase,owned,wanted)
 if owned==wanted then phase.Observed=true end
end
function Handoff.Grabbed(session,frame,now,ping)
 session.Handoff={Phase='grab',Frame=frame,Earliest=now+.05,
  Deadline=now+math.clamp(.1+pingSeconds(ping),.15,.7),Observed=false}
end
function Handoff.CanRelease(session,frame,now,owned)
 local phase=session.Handoff
 if not phase or phase.Phase~='grab'then return false end
 observe(phase,owned,true)
 if frame<=phase.Frame or now+1e-7<phase.Earliest then return false end
 if phase.Observed or now+1e-7>=phase.Deadline then
  session.LastHandoff={Phase='grab',Observed=phase.Observed,At=now}
  return true
 end
 return false
end
function Handoff.Released(session,frame,now,ping)
 session.Handoff={Phase='released',Frame=frame,Earliest=now+.05,
  Deadline=now+math.clamp(.05+pingSeconds(ping)*.5,.05,.3),Observed=false}
end
function Handoff.CanGrab(session,frame,now,owned)
 local phase=session.Handoff
 if not phase then return true end
 if phase.Phase~='released'then return false end
 observe(phase,owned,false)
 if frame<=phase.Frame or now+1e-7<phase.Earliest then return false end
 if phase.Observed or now+1e-7>=phase.Deadline then
  session.LastHandoff={Phase='released',Observed=phase.Observed,At=now}
  session.Handoff=nil
  return true
 end
 return false
end
return Handoff

]========]
sources.PalletStroke = [========[
-- A contact attempt moves the owned pallet through a real separated -> overlap
-- -> separated path. It does not equate a solver touch with a server hit.
local Stroke={}
local function alive(part)return part and part.Parent and part:IsA('BasePart')end
local function halfHeight(part)
 local cf,size=part.CFrame,part.Size*.5
 return math.abs(cf.RightVector.Y)*size.X+math.abs(cf.UpVector.Y)*size.Y+math.abs(cf.LookVector.Y)*size.Z
end
local function validDt(dt)
 return type(dt)=='number'and dt==dt and dt>0 and math.clamp(dt,1/1000,.1)or 1/60
end
-- Required ctx: Clock(), WaitPhase()->dt, Ready()->bool. Ready must include
-- the target session token and pallet network ownership. Optional callbacks
-- RecordClear(sound,character), BeginStrike(character), Record(sound,character).
-- Run executes ONE stroke and returns (complete, reason). Caller handles
-- repeat/fairness and parks after false. No writes to the target character.
function Stroke.Run(ctx,sound,main,torso,character)
 local function ready()
  local root=alive(sound)and(sound.AssemblyRootPart or sound)
  return alive(sound)and alive(main)and alive(torso)and alive(root)
   and not sound.Anchored and not main.Anchored and not root.Anchored and ctx.Ready()
 end
 if not ready()then return false,'unavailable'end
 local mover=main:FindFirstChild('RagdollBP')
 if mover then mover.MaxForce=Vector3.zero end
 local half=math.max(.05,halfHeight(sound)+halfHeight(torso))
 local gap=.75;local dt=validDt(ctx.StepSeconds or 1/60)
 local function velocity(speed,clear)
  local difference=torso.Position-sound.Position
  local lateral=Vector3.new(difference.X,0,difference.Z)*22
  if lateral.Magnitude>64 then lateral=lateral.Unit*64 end
  local vertical=clear and math.clamp((half+gap-(sound.Position.Y-torso.Position.Y))*18,-16,16)or -speed
  -- Optional gravity compensation is limited to the PALLET. It preserves
  -- the commanded crossing velocity through a physical solver step.
  local gravity=ctx.Gravity and ctx.Gravity()or 0
  local value=torso.AssemblyLinearVelocity+lateral+Vector3.new(0,vertical+gravity*dt*.5,0)
  local assembly=sound.AssemblyRootPart or sound
  assembly.AssemblyAngularVelocity=Vector3.zero;assembly.AssemblyLinearVelocity=value
  sound.AssemblyAngularVelocity=Vector3.zero;sound.AssemblyLinearVelocity=value;sound.Velocity=value
 end
 local assembly=sound.AssemblyRootPart or sound
 local launch=torso.Position+Vector3.new(0,half+gap,0)
 assembly.CFrame=assembly.CFrame+(launch-sound.Position)
 velocity(0,true)
 if ctx.RecordClear then ctx.RecordClear(sound,character)end
 local clearUntil=ctx.Clock()+math.clamp(ctx.ClearSeconds or .06,.06,.35)
 repeat
  dt=validDt(ctx.WaitPhase())
  if not ready()then return false,'cancelled'end
  velocity(0,true)
 until ctx.Clock()+1e-7>=clearUntil
 if sound.Position.Y-torso.Position.Y<=half+.1 then return false,'clearance lost'end
 local maxSpeed=math.clamp(ctx.Speed or 28,1,48)
 local function speed()return math.min(maxSpeed,half*.75/dt)end
 local initialSpeed=speed()
 local untilAt=ctx.Clock()+math.clamp((2*half+2*gap)/math.max(initialSpeed,.1)+.25,.3,1.5)
 if ctx.BeginStrike then ctx.BeginStrike(character)end
 velocity(initialSpeed,false)
 if ctx.Record then ctx.Record(sound,character)end
 repeat
  dt=validDt(ctx.WaitPhase())
  if not ready()then return false,'cancelled'end
  if sound.Position.Y<torso.Position.Y-half-gap then return true,'crossed'end
  velocity(speed(),false)
 until ctx.Clock()>=untilAt
 return false,'blocked'
end
return Stroke

]========]
sources.PalletOwnership = [========[
-- A PartOwner marker and local simulation ownership are independent facts.
-- Repair a stale marker with fresh bounded requests; never move an unowned toy.
local Ownership={};Ownership.__index=Ownership
local function finite(n)return type(n)=='number'and n==n and math.abs(n)<math.huge end
function Ownership.new(context)
 return setmetatable({Context=context,NextGrab=setmetatable({},{__mode='k'})},Ownership)
end
function Ownership:Acquire(part,valid)
 if self.Closed then return false,'Pallet ownership controller is closed'end
 if self.InFlight then return false,'Pallet ownership request already running'end
 local ctx=self.Context
 local ping=ctx.PingSeconds and ctx.PingSeconds()or .1
 if not finite(ping)then ping=.1 end
 local deadline=ctx.Clock()+math.clamp(.75+math.max(0,ping)*2,.75,1.5)
 local function alive()
  return part and part.Parent and part:IsA('BasePart')and not part.Anchored
 end
 local function allowed()
  return not self.Closed and alive()and(not valid or valid())and ctx.Clock()<deadline
 end
 self.InFlight=true
 local ok,success,reason=pcall(function()
  if not allowed()then return false,'Pallet ownership request cancelled'end
  local marker,physics=ctx.MarkerOwned(part)==true,ctx.PhysicsOwned(part)==true
  if marker and physics then return true,'Pallet ownership confirmed'end
  while allowed()and ctx.Busy and ctx.Busy()do ctx.Signal:Wait()end
  if not allowed()then return false,'Pallet ownership request cancelled or timed out'end
  marker=ctx.MarkerOwned(part)==true;physics=ctx.PhysicsOwned(part)==true
  if marker and physics then return true,'Pallet ownership confirmed'end
  -- The old SNO helper may perform a distant approach. It must not be used as
  -- proof of a handoff: SNO returns immediately if only the marker is local.
  if ctx.Approach and(not marker or(ctx.NeedsApproach and ctx.NeedsApproach(part)))then
   local approached,why=pcall(ctx.Approach,part,allowed)
   if not approached then self.LastApproachError=tostring(why)end
   self.NextGrab[part]=math.max(self.NextGrab[part]or 0,ctx.Clock()+.1)
  end
  while allowed()do
   marker=ctx.MarkerOwned(part)==true;physics=ctx.PhysicsOwned(part)==true
   if marker and physics then return true,'Pallet ownership confirmed'end
   if not(ctx.Busy and ctx.Busy())and ctx.Clock()>=(self.NextGrab[part]or 0)then
    self.NextGrab[part]=ctx.Clock()+.1
    local requested,why=pcall(ctx.Grab,part)
    if not requested then self.LastGrabError=tostring(why)end
   end
   ctx.Signal:Wait()
  end
  if self.Closed or not alive()or(valid and not valid())then return false,'Pallet ownership request cancelled'end
  return false,marker and'Waiting for pallet physics ownership'or'Waiting for pallet owner acknowledgement'
 end)
 self.InFlight=false
 if not ok then self.LastError=tostring(success);return false,'Pallet ownership error: '..self.LastError end
 return success==true,reason
end
function Ownership:Dispose()self.Closed=true end
return Ownership

]========]
sources.AquaEditable = [========[
-- Construct the original mesh through Roblox's EditableMesh API. This path
-- never asks the executor to open a .mesh URI. Poses still use the source rig.
local requireModule=...
local Mesh=requireModule('AquaMesh')
local Editable={};Editable.__index=Editable
local function skin(v,matrices)
 local p,n=Vector3.zero,Vector3.zero
 for k,id in ipairs(v.Bones)do local m,w=matrices[id],v.Weights[k]/255;p+=(m*v.Position)*w;n+=m:VectorToWorldSpace(v.Normal)*w end
 return p,n.Magnitude>1e-8 and n.Unit or v.Normal
end
function Editable.Build(ctx,data,pose,assets,textures,valid,status)
 assert(type(ctx.CreateEditableMesh)=='function'and type(ctx.CreateEditablePart)=='function','EditableMesh loader unavailable')
 local self=setmetatable({Context=ctx,Records={},Parts={},Scale=1},Editable)
 local function check()assert(valid()and not self.Closed,'Aqua loading cancelled')end
 local ok,why=pcall(function()
  local matrices=pose:Skin(pose:Resolve({}))
  for _,spec in ipairs(data.Parts)do
   check();status('Constructing Aqua geometry: '..spec.Key)
   local parsed=Mesh.Parse(assets.Bytes(spec.Key,valid,ctx.Files.Wait),spec)
   local mesh=assert(ctx.CreateEditableMesh(),'EditableMesh memory budget unavailable')
   local record={Editable=mesh,Parsed=parsed,Spec=spec,Vertices={},Normals={}};self.Records[#self.Records+1]=record
   local positions,normals={},{};local low=Vector3.new(math.huge,math.huge,math.huge);local high=-low
   for i,v in ipairs(parsed.Vertices)do
    local p,n=skin(v,matrices);positions[i]=p;normals[i]=n
    low=Vector3.new(math.min(low.X,p.X),math.min(low.Y,p.Y),math.min(low.Z,p.Z));high=Vector3.new(math.max(high.X,p.X),math.max(high.Y,p.Y),math.max(high.Z,p.Z))
   end
   record.Center=(low+high)*.5;record.Size=high-low
   local uvs={}
   for i,v in ipairs(parsed.Vertices)do
    record.Vertices[i]=mesh:AddVertex(positions[i]-record.Center)
    record.Normals[i]=mesh:AddNormal(normals[i]);uvs[i]=mesh:AddUV(Vector2.new(v.UV[1],v.UV[2]))
    if i%512==0 then check();if ctx.Files.Wait then ctx.Files.Wait()end;check()end
   end
   for i,face in ipairs(parsed.Faces)do
    local a,b,c=face[1],face[2],face[3];local id=mesh:AddTriangle(record.Vertices[a],record.Vertices[b],record.Vertices[c])
    mesh:SetFaceNormals(id,{record.Normals[a],record.Normals[b],record.Normals[c]})
    mesh:SetFaceUVs(id,{uvs[a],uvs[b],uvs[c]})
    if i%512==0 then check();if ctx.Files.Wait then ctx.Files.Wait()end;check()end
   end
   check();local part=ctx.CreateEditablePart(mesh);record.Part=part
   if not valid()then if typeof(part)=='Instance'and part.Parent==nil then part:Destroy()end;record.Part=nil;check()end
   assert(typeof(part)=='Instance'and part:IsA('MeshPart')and part.Parent==nil,'EditableMesh loader returned an invalid part')
   part.Name=spec.Key;part.TextureID=textures[spec.Texture];self.Parts[spec.Key]=part
  end
 end)
 if not ok then self:Dispose();error(why,0)end
 return self
end
function Editable:Render(frame,ground,pose,scale)
 local now=(self.Context.Clock or os.clock)()
 if now>=(self.NextUpdate or 0)then
  self.NextUpdate=now+1/30
  local matrices=pose:Skin(frame)
  for _,r in ipairs(self.Records)do
   for i,v in ipairs(r.Parsed.Vertices)do
    local p,n=skin(v,matrices);r.Editable:SetPosition(r.Vertices[i],p-r.Center);r.Editable:SetNormal(r.Normals[i],n)
   end
  end
 end
 for _,r in ipairs(self.Records)do
  r.Part.CFrame=ground*CFrame.new(r.Center*scale)
  local size=r.Part.MeshSize or r.Size
  r.Part.Size=Vector3.new(math.max(size.X,.001),math.max(size.Y,.001),math.max(size.Z,.001))*scale
 end
end
function Editable:Dispose()
 if self.Closed then return end;self.Closed=true
 for _,r in ipairs(self.Records)do
  if typeof(r.Part)=='Instance'and r.Part.Parent==nil then r.Part:Destroy()end
  r.Editable:Destroy()
 end
 table.clear(self.Records)
end
return Editable

]========]
sources.WaterSurface = [========[
-- Ocean render geometry may be non-queryable. Read its horizontal surface
-- directly; a raycast alone cannot discover CanQuery=false water tiles.
local Surface={};Surface.__index=Surface
function Surface.new(context)return setmetatable({Context=context,Parts={}},Surface)end
function Surface:At(position)
 local ctx=self.Context;local ocean=ctx.Ocean();local now=ctx.Clock()
 if ocean~=self.Ocean or now>=(self.NextScan or 0)then
  self.Ocean=ocean;self.NextScan=now+1;table.clear(self.Parts)
  if ocean then
   if ocean:IsA('BasePart')then self.Parts[#self.Parts+1]=ocean end
   for _,p in ipairs(ocean:GetDescendants())do if p:IsA('BasePart')then self.Parts[#self.Parts+1]=p end end
  end
 end
 local best
 for _,part in ipairs(self.Parts)do
  if part.Parent and math.abs(part.CFrame.UpVector.Y)>.95 and part.Size.X*part.Size.Z>=64 then
   local point=part.CFrame:PointToObjectSpace(position);local half=part.Size*.5
   if math.abs(point.X)<=half.X and math.abs(point.Z)<=half.Z then
    local top=(part.CFrame*Vector3.new(point.X,half.Y,point.Z)).Y+(ctx.Offset and ctx.Offset()or 0)
    if not best or top>best.Y then best=Vector3.new(position.X,top,position.Z)end
   end
  end
 end
 if best then return best end
 if ctx.Fallback then return ctx.Fallback(position)end
end
return Surface

]========]
sources.WaterWalk = [========[
-- A broad anchored platform with its top at sea level. No ocean edits or
-- automatic character CFrame/velocity writes; explicit teleport is a UI action.
local Walk={};Walk.__index=Walk
function Walk.Install(ctx)
 local self=setmetatable({Context=ctx,Enabled=false},Walk)
 self.Connection=ctx.RunService.PreSimulation:Connect(function()self:Refresh()end)
 return self
end
function Walk:RestoreSwimming()
 local h=self.Humanoid
 if h and h.Parent and self.Swimming~=nil then
  h:SetStateEnabled(Enum.HumanoidStateType.Swimming,self.Swimming and not(self.Context.OtherSwimBlock and self.Context.OtherSwimBlock()))
 end
 self.Humanoid=nil;self.Swimming=nil
end
function Walk:Stop()
 if self.Part then self.Part:Destroy();self.Part=nil end
 self:RestoreSwimming();self.Surface=nil
end
function Walk:Place(point)
 if not self.Part or not self.Part.Parent then
  if self.Part then self.Part:Destroy()end
  local p=Instance.new('Part');p.Name='AstralWaterVoidPlatform';p.Anchored=true;p.Transparency=.82;p.CanTouch=false;p.CanQuery=false;p.CanCollide=true
  p.Size=Vector3.new(250,5,250);p.CustomPhysicalProperties=PhysicalProperties.new(.7,0,0,100,100)
  p.Parent=self.Context.Workspace;self.Part=p
 end
 self.Surface=point.Y;self.Part.CFrame=CFrame.new(point.X,point.Y-2.5,point.Z)
 return self.Part
end
function Walk:SetEnabled(value)self.Enabled=value==true;if not self.Enabled then self:Stop()else self:Refresh()end end
function Walk:Step()
 if self.Closed or not self.Enabled then self:Stop();return end
 local c,r,h=self.Context.Character()
 if not c or not r or not h or h.Health<=0 or r.Anchored or h.SeatPart or(self.Context.Blocked and self.Context.Blocked())then self:Stop();return end
 local point=self.Context.Surface(c,r,h)
 if not point then self:Stop();return end
 local leg=c:FindFirstChild('Left Leg');local offset=leg and r.Size.Y*.5+leg.Size.Y or h.HipHeight+r.Size.Y*.5
 local feet=r.Position.Y-offset
 -- Do not lift an already submerged swimmer onto an invisible floor.
 if point.Y>feet+.75 or feet-point.Y>64 then self:Stop();return end
 if self.Part and not self.Part.Parent then self:Stop()end
 if self.Humanoid~=h then self:RestoreSwimming();self.Humanoid=h;self.Swimming=h:GetStateEnabled(Enum.HumanoidStateType.Swimming)end
 h:SetStateEnabled(Enum.HumanoidStateType.Swimming,false)
 if h:GetState()==Enum.HumanoidStateType.Swimming then h:ChangeState(Enum.HumanoidStateType.Running)end
 if not self.Part then self:Place(point)end
 -- A stable height removes wave/triangle seam jitter. Recenter horizontally
 -- only after sufficient travel, with zero-friction support and no Y snap.
 if math.abs(point.Y-self.Surface)>1 then self:Stop();return end
 local d=r.Position-self.Part.Position
 if Vector3.new(d.X,0,d.Z).Magnitude>72 then self.Part.CFrame=CFrame.new(r.Position.X,self.Surface-2.5,r.Position.Z)end
end
function Walk:Refresh()
 local ok,err=pcall(self.Step,self);if not ok then self.LastError=tostring(err);pcall(self.Stop,self)end
end
function Walk:Dispose()if self.Closed then return end;self.Closed=true;self.Connection:Disconnect();self:Stop()end
return Walk

