sources.AquaEffects = [========[
local Effects={};Effects.__index=Effects
function Effects.new(context)return setmetatable({Context=context,Time=0,Wind=Vector3.zero,Shelter=1},Effects)end
function Effects:Step(frame,model)
 local now=(self.Context.Clock or os.clock)();local dt=self.Last and math.clamp(now-self.Last,0,.1)or 0;self.Last=now;self.Time+=dt
 if now>=(self.NextWind or 0)then
  self.NextWind=now+.25
  local wind,shelter=Vector3.zero,1
  if self.Context.Wind then local ok,w,s=pcall(self.Context.Wind,frame.Position+Vector3.new(0,4,0),model);if ok then wind=w or wind;shelter=s or 1 end end
  self.WorldWind=wind;self.TargetShelter=shelter
 end
 self.Shelter+=(self.TargetShelter-self.Shelter)*(1-math.exp(-dt*5))
 local p=frame.Position;local t=self.Time
 local spatial=math.sin(p.X*.019+math.sin(p.Z*.014))*math.cos(p.Z*.011)
 local gust=.45+.3*math.sin(t*.65+spatial*2)+.2*math.sin(t*.31+p.X*.007)
 local ambient=Vector3.new(math.cos(p.Z*.013+t*.12),0,math.sin(p.X*.015+t*.1))*(.045*gust)
 local raw=(self.WorldWind or Vector3.zero)*.008+ambient
 local target=frame:VectorToObjectSpace(raw)*self.Shelter
 if target.Magnitude>.14 then target=target.Unit*.14 end
 self.Wind+=(target-self.Wind)*(1-math.exp(-dt*4))
 -- A smooth close/open cycle, with a short closed interval. The rest of the
 -- face is untouched; eyelids are attached to the animated head in both modes.
 local phase=t%4.3;local blink=0
 if phase>3.75 and phase<3.96 then
  local x=(phase-3.75)/.21;blink=math.sin(math.pi*x)^2
 end
 return {WindX=self.Wind.X,WindZ=self.Wind.Z,Blink=blink,Time=t}
end
return Effects

