sources.AquaPose = [========[
-- Source skeleton/proportions and the supplied CS default stance, with adapted
-- locomotion clips. The absent external animset_t.mdl is not represented here.
local Pose={};Pose.__index=Pose
local function frame(v)return CFrame.new(table.unpack(v,1,12))end
function Pose.new(data)
    local self=setmetatable({Data=data,Bind={},Inverse={},Basis={},Clips={},Relaxed={},ByName={}},Pose)
    for i,b in ipairs(data.Bones)do
        self.Bind[i]=frame(b.Local);self.Inverse[i]=frame(b.Global):Inverse();self.Basis[i]=frame(b.Global).Rotation;self.ByName[b.Name]=i
        self.Relaxed[i]=frame(data.Relaxed[i])
    end
    for name,clip in pairs(data.Clips)do
        local frames={}
        for n,pose in ipairs(clip.Frames)do local list={};for i,v in ipairs(pose)do list[i]=frame(v)end;frames[n]=list end
        self.Clips[name]={Frames=frames,Cycle=clip.Cycle}
    end
    return self
end
function Pose:Lerp(a,b,t)
    if t<=.0001 then return a elseif t>=.9999 then return b end
    local out={};for i,v in ipairs(a)do out[i]=v:Lerp(b[i],t)end;return out
end
function Pose:At(name,phase)
    local frames=self.Clips[name].Frames
    if #frames==1 then return frames[1]end
    local t=(phase%1)*#frames;local i=math.floor(t)
    return self:Lerp(frames[i+1],frames[(i+1)%#frames+1],t-i)
end
function Pose:Resolve(pose,overlay)
    local walk=math.clamp(pose.Walk or 0,0,1);local run=math.clamp(pose.Run or 0,0,1)
    local crouch=math.clamp(pose.Crouch or 0,0,1);local sit=math.clamp(pose.SitAmount or(pose.Sit and 1 or 0),0,1)
    local phase=pose.Phase or 0
    local frame=self:At('idle',pose.Idle or 0)
    if walk>.0001 then frame=self:Lerp(frame,self:At('walk',phase),walk)end
    if run>.0001 then frame=self:Lerp(frame,self:At('run',phase),run)end
    if crouch>.0001 then frame=self:Lerp(frame,self:Lerp(self:At('crouch_idle',0),self:At('crouch_walk',phase),walk),crouch)end
    if sit>.0001 then frame=self:Lerp(frame,self:At('sit',0),sit)end
    if(pose.Air or 0)>.0001 then frame=self:Lerp(frame,self:At('air',0),math.clamp(pose.Air,0,1))end
    -- Frame tables above are immutable. Dynamic look/inertia never changes a
    -- cached source clip, including when multiple models/reloads share assets.
    local result=table.clone(frame)
    if pose.Style=='Relaxed'then
        for i,b in ipairs(self.Data.Bones)do
            if b.Name:find('arm_',1,true)or b.Name:find('hand_',1,true)or b.Name:find('finger_',1,true)or b.Name:find('clavicle_',1,true)then
                result[i]=self.Relaxed[i]
            end
        end
    end
    if overlay~=false then
        local function apply(name,rotation)
            local i=self.ByName[name];if not i then return end
            local basis=self.Basis[i];result[i]=result[i]*(basis:Inverse()*rotation*basis)
        end
        for _,b in ipairs(self.Data.Bones)do
            if b.Name:sub(1,5)=='hair_'then
                local depth=tonumber(b.Name:match('(%d+)$'))or 1
                apply(b.Name,CFrame.Angles(-(pose.WindZ or 0)*.4/depth,0,(pose.WindX or 0)*.4/depth))
            end
        end
        apply('head_0',CFrame.Angles((pose.LookPitch or 0)*.45,(pose.LookYaw or 0)*.55,0))
        for _,name in ipairs({'spine_0','spine_1','spine_2','spine_3'})do
            apply(name,CFrame.Angles(-(pose.LeanX or 0)*.22,(pose.Turn or 0)*.018,(pose.LeanZ or 0)*.22))
        end
    end
    if(pose.Air or 0)<.02 and sit<.02 then result=self:Ground(result)end
    return result
end
function Pose:Ground(localFrames)
    if not self.Data.FootContacts then return localFrames end
    local matrices=self:Skin(localFrames);local bottom=math.huge
    for _,v in ipairs(self.Data.FootContacts)do
        local p=Vector3.zero;local original=Vector3.new(table.unpack(v.Position))
        for k,id in ipairs(v.Bones)do p+=(matrices[id]*original)*v.Weights[k]end
        bottom=math.min(bottom,p.Y)
    end
    if bottom==math.huge then return localFrames end
    local result=table.clone(localFrames);local offset=math.clamp(.025-bottom,-.6,.6)
    for i,b in ipairs(self.Data.Bones)do if b.Parent==0 then result[i]=result[i]+Vector3.new(0,offset,0)end end
    return result
end
function Pose:World(localFrames)
    local frames={}
    for i,b in ipairs(self.Data.Bones)do frames[i]=b.Parent>0 and frames[b.Parent]*localFrames[i]or localFrames[i]end
    return frames
end
function Pose:Skin(localFrames)
    local world=self:World(localFrames);local matrices={}
    for i,v in ipairs(world)do matrices[i]=v*self.Inverse[i]end
    return matrices
end
function Pose.Sample(style,phase)
    return {Phase=(style=='walk'or style=='run')and phase or 0,Idle=style=='idle'and phase or 0,
        Walk=(style=='walk'or style=='run')and 1 or 0,Run=style=='run'and 1 or 0,Crouch=style=='crouch'and 1 or 0,
        SitAmount=style=='sit'and 1 or 0,Sit=style=='sit',Air=style=='jump'and 1 or 0}
end
function Pose.Blend(a,b,t)
    local out={Phase=b.Phase or a.Phase or 0,Idle=a.Idle or b.Idle or 0,Sit=b.Sit}
    for _,k in ipairs({'Walk','Run','Crouch','SitAmount','Air','LeanX','LeanZ','Turn','LookYaw','LookPitch'})do out[k]=(a[k]or 0)+((b[k]or 0)-(a[k]or 0))*math.clamp(t,0,1)end
    return out
end
return Pose

