sources.AquaModel = [========[
-- Aqua from the supplied CS:GO archive. Native GPU skinning is preferred.
-- A bounded file-mesh animation cache supports executors without that loader.
local requireModule=...
local Assets=requireModule('AquaAssets')
local Pose=requireModule('AquaPose')
local Mesh=requireModule('AquaMesh')
local Effects=requireModule('AquaEffects')
local Editable=requireModule('AquaEditable')
local Model={};Model.__index=Model
local V1=Vector3.new(1,1,1)
local function vector(v)return Vector3.new(table.unpack(v,1,3))end
local function cf(v)return CFrame.new(table.unpack(v,1,12))end
local function scaled(v,s)return v.Rotation+v.Position*s end
local function finite(v)return type(v)=='number'and v==v and math.abs(v)<math.huge end
local function properties(p)
    p.Anchored=true;p.CanCollide=false;p.CanTouch=false;p.CanQuery=false;p.Massless=true;p.CastShadow=true
    p.Color=Color3.new(1,1,1);p.Material=Enum.Material.SmoothPlastic;p.LocalTransparencyModifier=1
end
function Model.Build(context,valid,status)
    local self=setmetatable({Context=context,Data=Assets.Metadata,Name='Aqua (CS:GO)',Scale=1,Parts={},Bones={},Meshes={},Visible=false,
        RigidOnly=false,HasFaceRig=true,Upright=true,Lids={},RunStart=9,RunRange=7},Model)
    local function check()assert(valid()and not self.Closed,'Aqua loading cancelled')end
    local function fresh()
        self.Model=Instance.new('Model');self.Model.Name='AstralLocalAqua'
        self.Parts={};self.Bones={};self.Meshes={}
    end
    fresh()
    local ok,message=pcall(function()
        self.Pose=Pose.new(self.Data);self.Effects=Effects.new(context);self.Textures={}
        status('Loading original Aqua textures…')
        for _,name in ipairs({'MainTexture','DetailTexture','EyeTexture'})do self.Textures[name]=Assets.Get(name,context.Files,valid);check()end
        local nativeOk,nativeError=pcall(function()
            assert(type(context.CreateSkinned)=='function','Native skinned mesh loader unavailable')
            status('Preparing Aqua skeleton…')
            for _,spec in ipairs(self.Data.Parts)do
                local uri=Assets.Get(spec.Key,context.Files,valid);check()
                local part=context.CreateSkinned(uri)
                if not valid()then
                    if typeof(part)=='Instance'and part.Parent==nil then part:Destroy()end
                    check()
                end
                if not(part and part:IsA('MeshPart')and part.Parent==nil)then
                    if typeof(part)=='Instance'and part.Parent==nil then part:Destroy()end
                    error('Native loader did not return an unparented MeshPart',0)
                end
                part.Parent=self.Model
                local queried,skinned=pcall(function()return part.HasSkinnedMesh end)
                assert(not queried or skinned~=false,'Native loader discarded the Aqua skin weights')
                properties(part);part.Name=spec.Key;part.TextureID=self.Textures[spec.Texture];part.Size=vector(spec.Size);part.CFrame=CFrame.new(vector(spec.Center))
                pcall(function()part.DoubleSided=true end);pcall(function()part.RenderFidelity=Enum.RenderFidelity.Precise end)
                part.Parent=self.Model;self.Parts[spec.Key]=part
                local existing={}
                for _,v in ipairs(part:GetDescendants())do if v:IsA('Bone')then existing[v.Name]=v end end
                local bones={};self.Bones[spec.Key]=bones
                for i,b in ipairs(self.Data.Bones)do
                    local bone=existing[b.Name]or Instance.new('Bone');bone.Name=b.Name
                    bone.Parent=b.Parent>0 and bones[b.Parent]or part
                    bone.CFrame=b.Parent>0 and cf(b.Local)or CFrame.new(-vector(spec.Center))*cf(b.Local)
                    bone.Transform=CFrame.new();bones[i]=bone
                end
            end
            context.Preload({self.Model},valid);check()
            self.Mode='Skinned';self.Model.PrimaryPart=self.Parts.Main
        end)
        if not nativeOk then
            check();self.NativeError=tostring(nativeError)
            self.Model:Destroy();fresh()
            local editableOk,editableError=pcall(self.BuildEditable,self,valid,status);check()
            if not editableOk then
                self.EditableError=tostring(editableError)
                if self.Editable then self.Editable:Dispose();self.Editable=nil end
                self.Model:Destroy();fresh()
                self:BuildFiles(valid,status);check()
            end
        end
        self.Model.Parent=context.Workspace;check()
        status('Aqua ready')
        -- The body is usable before optional face textures or later file poses
        -- finish loading. Cancellation remains tied to this model generation.
        local function loadFace()
            local function faceValid()return valid()and not self.Closed end
            local lidsOk,lidsError=pcall(self.BuildLids,self,faceValid)
            if not lidsOk then
                self.EffectError='Eyelids: '..tostring(lidsError)
                for _,lid in ipairs(self.Lids)do lid.Part:Destroy()end;table.clear(self.Lids)
            end
        end
        if context.Spawn then context.Spawn(loadFace)else loadFace();check()end
        if self.PreparePending then
            local prepare=self.PreparePending;self.PreparePending=nil
            local function continuePreparing()
                local prepared,why=pcall(prepare)
                if not prepared and valid()and not self.Closed then self.AnimationError=tostring(why)end
            end
            if context.Spawn then context.Spawn(continuePreparing)else continuePreparing()end
        end
    end)
    if not ok then
        local reasons={'Aqua loading failed: '..tostring(message)}
        if self.NativeError then reasons[#reasons+1]='Native mesh: '..self.NativeError end
        if self.EditableError then reasons[#reasons+1]='EditableMesh: '..self.EditableError end
        self:Dispose();error(table.concat(reasons,'\n'),0)
    end
    return self
end
function Model:BuildEditable(valid,status)
    self.Editable=Editable.Build(self.Context,self.Data,self.Pose,Assets,self.Textures,valid,status)
    self.Parts=self.Editable.Parts
    for _,p in pairs(self.Parts)do properties(p);pcall(function()p.DoubleSided=true end);p.Parent=self.Model end
    self.Context.Preload({self.Model},valid);assert(valid(),'Aqua loading cancelled')
    self.Mode='EditableMesh';self.Model.PrimaryPart=self.Parts.Main
end
function Model:BuildLids(valid)
    local uri=Assets.Get('LidMesh',self.Context.Files,valid);local texture=Assets.Get('LidTexture',self.Context.Files,valid)
    assert(valid()and not self.Closed,'Aqua loading cancelled')
    for i,eye in ipairs(self.Data.Eyes or{})do
        local p=Instance.new('Part');properties(p);p.Name='AquaEyelid'..i;p.CastShadow=false;p.Size=Vector3.new(.1,.1,.1);p.Parent=self.Model
        local mesh=Instance.new('SpecialMesh');mesh.MeshType=Enum.MeshType.FileMesh;mesh.MeshId=uri;mesh.TextureId=texture;mesh.VertexColor=V1;mesh.Parent=p
        self.Lids[i]={Part=p,Mesh=mesh,Eye=eye}
    end
    local parts={};for _,lid in ipairs(self.Lids)do parts[#parts+1]=lid.Part end
    self.Context.Preload(parts,valid);assert(valid()and not self.Closed,'Aqua loading cancelled')
end
function Model:BuildFiles(valid,status)
    local files=self.Context.Files
    assert(type(files.Write)=='function'and type(files.CustomAsset)=='function','Aqua needs local mesh/texture file support')
    local parsed={};self.Prepared={};self.FileRequests={}
    for _,spec in ipairs(self.Data.Parts)do parsed[spec.Key]=Mesh.Parse(Assets.Bytes(spec.Key,valid,files.Wait),spec)end
    local prepared=0
    local function bake(key,frame)
        assert(valid()and not self.Closed,'Aqua loading cancelled')
        if not key:match('^air')and not key:match('^sit')then frame=self.Pose:Ground(frame)end
        local matrices=self.Pose:Skin(frame);local result={Head=self.Pose:World(frame)[self.Pose.ByName.head_0]}
        for _,spec in ipairs(self.Data.Parts)do
            local path='astral_aqua456_'..self.Data.BuildId..'_'..key..'_'..spec.Key..'.mesh'
            local data,center
            if files.Read and files.IsFile then
                local ok,value=pcall(function()
                    if not files.IsFile(path)or not files.IsFile(path..'.center')then return end
                    local expected=buffer.len(parsed[spec.Key].Template)
                    if #files.Read(path)~=expected then return end
                    local x,y,z=files.Read(path..'.center'):match('^([^,]+),([^,]+),([^,]+)$')
                    x,y,z=tonumber(x),tonumber(y),tonumber(z)
                    if finite(x)and finite(y)and finite(z)and math.abs(x)+math.abs(y)+math.abs(z)<100 then return Vector3.new(x,y,z)end
                end)
                if ok then center=value end
            end
            if not center then
                data,center=Mesh.Bake(parsed[spec.Key],matrices,valid)
                assert(valid()and not self.Closed,'Aqua loading cancelled');files.Write(path,data)
                files.Write(path..'.center',string.format('%.9g,%.9g,%.9g',center.X,center.Y,center.Z))
            end
            assert(valid()and not self.Closed,'Aqua loading cancelled')
            local uri=files.CustomAsset(path);assert(type(uri)=='string'and #uri>0,'Aqua pose file could not be loaded')
            result[spec.Key]={URI=uri,Center=center};self.FileRequests[#self.FileRequests+1]=uri
        end
        prepared+=1;status('Preparing Aqua movement… '..prepared..'/73')
        if files.Wait then files.Wait()end
        assert(valid()and not self.Closed,'Aqua loading cancelled')
        return result
    end
    local idle=self.Pose.Clips.idle.Frames
    self.Prepared.idle={bake('idle_1',idle[1])}
    self.PreparePending=function()
        for _,style in ipairs({'idle','walk','run','crouch_idle','crouch_walk','sit','air'})do
            local list=self.Prepared[style]or{};self.Prepared[style]=list
            for i,frame in ipairs(self.Pose.Clips[style].Frames)do
                assert(valid()and not self.Closed,'Aqua loading cancelled')
                if not list[i]then list[i]=bake(style..'_'..i,frame)end
            end
        end
        for _,name in ipairs({'crouch','sit'})do
            local frames={};self.Prepared[name..'_transition']=frames
            local finish=name=='crouch'and self.Pose.Clips.crouch_idle.Frames[1]or self.Pose.Clips.sit.Frames[1]
            for i=0,4 do
                assert(valid()and not self.Closed,'Aqua loading cancelled')
                frames[i+1]=bake(name..'_transition_'..i,self.Pose:Lerp(idle[1],finish,i/4))
            end
        end
        self.AnimationReady=true
    end
    for _,spec in ipairs(self.Data.Parts)do
        local part=Instance.new('Part');properties(part);part.Name=spec.Key;part.Size=Vector3.new(.1,.1,.1);part.CFrame=CFrame.new()
        local mesh=Instance.new('SpecialMesh');mesh.Name='OriginalAquaMesh';mesh.MeshType=Enum.MeshType.FileMesh
        mesh.MeshId=self.Prepared.idle[1][spec.Key].URI;mesh.TextureId=self.Textures[spec.Texture];mesh.VertexColor=V1;mesh.Scale=V1;mesh.Parent=part
        part.Parent=self.Model;self.Parts[spec.Key]=part;self.Meshes[spec.Key]=mesh
    end
    self.Context.Preload({self.Model},valid)
    assert(valid()and not self.Closed,'Aqua loading cancelled')
    self.Mode='FileMesh';self.Model.PrimaryPart=self.Parts.Main
end
function Model:Sample(style,phase)return Pose.Sample(style,phase)end
function Model:Blend(a,b,t)return Pose.Blend(a,b,t)end
function Model:SetScale(value)
    if self.Closed or not finite(value)then return end
    value=math.clamp(value,.65,1.35)
    if math.abs(value-self.Scale)<.0001 then return end
    if self.Mode=='Skinned'then self.Model:ScaleTo(value)
    elseif self.Mode=='FileMesh'then for _,mesh in pairs(self.Meshes)do mesh.Scale=V1*value end end
    self.Scale=value
end
function Model:IsReady()
    if self.Closed or not self.Model or not self.Model.Parent then return false end
    for _,spec in ipairs(self.Data.Parts)do local part=self.Parts[spec.Key];if not part or part.Parent~=self.Model then return false end end
    return true
end
function Model:FileFrame(pose)
    local walk=pose.Walk or 0;local crouch=pose.Crouch or 0;local sit=pose.SitAmount or(pose.Sit and 1 or 0)
    if sit>.02 and sit<.98 and self.Prepared.sit_transition and #self.Prepared.sit_transition>0 then local frames=self.Prepared.sit_transition;return frames[math.min(#frames,math.clamp(math.floor(sit*4+.5)+1,1,5))]end
    if walk<.2 and crouch>.02 and crouch<.98 and self.Prepared.crouch_transition and #self.Prepared.crouch_transition>0 then local frames=self.Prepared.crouch_transition;return frames[math.min(#frames,math.clamp(math.floor(crouch*4+.5)+1,1,5))]end
    local style,phase='idle',pose.Idle or 0
    if sit>=.5 then style='sit';phase=0
    elseif(pose.Air or 0)>.5 then style='air';phase=0
    elseif crouch>.5 then style=walk>.2 and'crouch_walk'or'crouch_idle';phase=pose.Phase or 0
    elseif(pose.Run or 0)>.5 then style='run';phase=pose.Phase or 0
    elseif walk>.2 then style='walk';phase=pose.Phase or 0 end
    local frames=self.Prepared[style];if not frames or #frames==0 then frames=self.Prepared.idle end;return frames[math.floor((phase%1)*#frames+.5)%#frames+1]
end
function Model:Render(pose,ground,hidden)
    if not self:IsReady()then return false end
    local scale=self.Scale
    local effects={WindX=0,WindZ=0,Blink=0}
    local ok,value=pcall(self.Effects.Step,self.Effects,ground,self.Model)
    if ok then effects=value else self.EffectError='Wind/blink: '..tostring(value)end
    pose=table.clone(pose);pose.WindX=effects.WindX;pose.WindZ=effects.WindZ
    local head
    if self.Mode=='Skinned'then
        local frame=self.Pose:Resolve(pose)
        head=self.Pose:World(frame)[self.Pose.ByName.head_0]
        for _,spec in ipairs(self.Data.Parts)do
            self.Parts[spec.Key].CFrame=ground*CFrame.new(vector(spec.Center)*scale)
            for i,bone in ipairs(self.Bones[spec.Key])do
                if bone.Parent then bone.Transform=scaled(self.Pose.Bind[i]:Inverse()*frame[i],scale)end
            end
        end
    elseif self.Mode=='EditableMesh'then
        local frame=self.Pose:Resolve(pose);head=self.Pose:World(frame)[self.Pose.ByName.head_0]
        self.Editable:Render(frame,ground,self.Pose,scale)
    else
        local frame=self:FileFrame(pose);head=frame.Head
        for _,spec in ipairs(self.Data.Parts)do
            local mesh=self.Meshes[spec.Key];local target=frame[spec.Key]
            local pivot=head.Position*scale
            local flow=spec.Key=='Hair'and CFrame.new(pivot)*CFrame.Angles(-effects.WindZ*.4,0,effects.WindX*.4)*CFrame.new(-pivot)or CFrame.new()
            self.Parts[spec.Key].CFrame=ground*flow
            if mesh.MeshId~=target.URI then mesh.MeshId=target.URI end
            mesh.Offset=target.Center*scale
        end
    end
    local skin=head*self.Pose.Inverse[self.Pose.ByName.head_0]
    for _,lid in ipairs(self.Lids)do
        lid.Part.CFrame=ground*scaled(skin*CFrame.new(vector(lid.Eye.Top))*CFrame.Angles(0,lid.Eye.Yaw or 0,0),scale)
        lid.Mesh.Scale=Vector3.new(lid.Eye.Width,lid.Eye.Height*math.max(.001,effects.Blink),1)*scale
        lid.Part.LocalTransparencyModifier=(hidden or effects.Blink<.02)and 1 or 0
    end
    self:SetVisible(not hidden);return true
end
function Model:SetVisible(value)
    if self.Closed or value==self.Visible then return end;self.Visible=value
    for _,part in pairs(self.Parts)do if part.Parent then part.LocalTransparencyModifier=value and 0 or 1 end end
    if not value then for _,lid in ipairs(self.Lids)do lid.Part.LocalTransparencyModifier=1 end end
end
function Model:DescribeRig()
    return {Name=self.Name,Source=self.Data.Source,Mode=self.Mode,NativeError=self.NativeError,EditableError=self.EditableError,Parts=#self.Data.Parts,
        BoneCount=#self.Data.Bones,SourceVertices=self.Data.Source.SourceVertices,FaceRig=#self.Lids>0 and 'Eyelid overlays'or 'Unavailable',EffectError=self.EffectError,AnimationError=self.AnimationError}
end
function Model:Dispose()
    if self.Closed then return end;self.Closed=true
    if self.Model then self.Model:Destroy()end
    if self.Editable then self.Editable:Dispose();self.Editable=nil end
    for _,part in pairs(self.Parts)do pcall(part.Destroy,part)end
    for _,lid in ipairs(self.Lids)do pcall(lid.Part.Destroy,lid.Part)end;table.clear(self.Lids)
    self.Pose=nil
    table.clear(self.Parts);table.clear(self.Bones);table.clear(self.Meshes)
    self.Prepared=nil;self.FileRequests=nil
end
return Model

