sources.AquaMesh = [========[
-- Reads the format-converted source mesh. File-mesh fallback poses are skinned
-- on the user's device once and cached; no posed mesh is fetched from a server.
local Mesh={}
local function vec(b,o)return Vector3.new(buffer.readf32(b,o),buffer.readf32(b,o+4),buffer.readf32(b,o+8))end
local function put(b,o,v)buffer.writef32(b,o,v.X);buffer.writef32(b,o+4,v.Y);buffer.writef32(b,o+8,v.Z)end
function Mesh.Parse(data,part)
    assert(buffer and buffer.fromstring,'Aqua file animation requires the Roblox buffer API')
    assert(data:sub(1,13)=='version 4.00\n','Unsupported Aqua mesh version')
    local b=buffer.fromstring(data)
    local header,_,nv,nf,nl,nb,nn,ns=string.unpack('<I2I2I4I4I2I2I4I2',data,14)
    assert(header==24 and nv==part.Vertices and nf==part.Faces and nb<=128 and ns==part.Subsets,'Aqua mesh header mismatch')
    local vo=37;local eo=vo+nv*40;local fo=eo+nv*8;local so=fo+nf*12+nl*4+nb*60+nn
    assert(so+ns*72==#data,'Invalid Aqua mesh size')
    local center=Vector3.new(table.unpack(part.Center));local vertices={};local covered={}
    for subset=0,ns-1 do
        local s=so+subset*72;local start=buffer.readu32(b,s+8);local count=buffer.readu32(b,s+12);local bones=buffer.readu32(b,s+16)
        assert(start+count<=nv and bones<=26,'Invalid Aqua skinning palette')
        for i=start,start+count-1 do
            assert(not covered[i],'Overlapping Aqua subsets');covered[i]=true
            local weights,ids={},{};local sum=0
            for k=0,3 do
                local w=buffer.readu8(b,eo+i*8+4+k)
                if w>0 then
                    local localBone=buffer.readu8(b,eo+i*8+k);assert(localBone<bones,'Invalid Aqua local bone')
                    local id=buffer.readu16(b,s+20+localBone*2)+1;assert(id<=nb,'Invalid Aqua global bone')
                    weights[#weights+1]=w;ids[#ids+1]=id;sum+=w
                end
            end
            assert(sum==255,'Aqua vertex weights must add up to 255')
            vertices[i+1]={Position=vec(b,vo+i*40)+center,Normal=vec(b,vo+i*40+12),Weights=weights,Bones=ids,UV={buffer.readf32(b,vo+i*40+24),buffer.readf32(b,vo+i*40+28)}}
        end
    end
    assert(#vertices==nv,'Incomplete Aqua vertex ranges')
    local template=buffer.create(25+nv*40+nf*24)
    buffer.writestring(template,0,'version 2.00\n'..string.pack('<I2I1I1I4I4',12,40,12,nv,nf*2))
    buffer.copy(template,25,b,vo,nv*40);buffer.copy(template,25+nv*40,b,fo,nf*12)
    -- SpecialMesh has no DoubleSided property. Reversed render faces retain
    -- the source hair/ribbon silhouettes from behind in the file backend.
    for i=0,nf-1 do
        local source=fo+i*12;local target=25+nv*40+nf*12+i*12
        buffer.writeu32(template,target,buffer.readu32(b,source))
        buffer.writeu32(template,target+4,buffer.readu32(b,source+8))
        buffer.writeu32(template,target+8,buffer.readu32(b,source+4))
    end
    local faces={}
    for i=0,nf-1 do local o=fo+i*12;faces[i+1]={buffer.readu32(b,o)+1,buffer.readu32(b,o+4)+1,buffer.readu32(b,o+8)+1}end
    return {Vertices=vertices,Faces=faces,Template=template,VertexCount=nv,FaceCount=nf}
end
function Mesh.Bake(parsed,matrices,valid)
    local result=buffer.create(buffer.len(parsed.Template));buffer.copy(result,0,parsed.Template)
    local min=Vector3.new(math.huge,math.huge,math.huge);local max=-min
    for i,v in ipairs(parsed.Vertices)do
        local p,n=Vector3.zero,Vector3.zero
        for k,id in ipairs(v.Bones)do
            local m=matrices[id];local w=v.Weights[k]/255
            p+=(m*v.Position)*w;n+=m:VectorToWorldSpace(v.Normal)*w
        end
        if n.Magnitude>1e-8 then n=n.Unit else n=v.Normal end
        min=Vector3.new(math.min(min.X,p.X),math.min(min.Y,p.Y),math.min(min.Z,p.Z))
        max=Vector3.new(math.max(max.X,p.X),math.max(max.Y,p.Y),math.max(max.Z,p.Z))
        put(result,25+(i-1)*40,p);put(result,37+(i-1)*40,n)
        if i%2048==0 then assert(valid(),'Aqua loading cancelled')end
    end
    local center=(min+max)*.5
    for i=0,parsed.VertexCount-1 do local o=25+i*40;put(result,o,vec(result,o)-center)end
    return buffer.tostring(result),center
end
return Mesh

]========]
