sition"]={-0.193050036,0.179536943,-0.18254154},["Bones"]={90,91},["Weights"]={0.694117647,0.305882353}},{["Position"]={-0.193026683,0.227656065,-0.116167317},["Bones"]={90},["Weights"]={1}},{["Position"]={-0.263445662,0.198347195,-0.0980251525},["Bones"]={90},["Weights"]={1}},{["Position"]={-0.121820749,0.152133162,0.19225939},["Bones"]={90},["Weights"]={1}},{["Position"]={-0.135260703,0.0878013269,0.192291567},["Bones"]={90},["Weights"]={1}},{["Position"]={-0.192660593,0.0878219301,0.190868517},["Bones"]={90},["Weights"]={1}},{["Position"]={-0.248002635,0.0878081494,0.189668894},["Bones"]={90},["Weights"]={1}},{["Position"]={-0.235564884,2.1044518e-06,0.193706608},["Bones"]={90},["Weights"]={1}},{["Position"]={-0.0854110006,0.265314416,0.0835842685},["Bones"]={90},["Weights"]={1}},{["Position"]={-0.0748336779,0.28386246,0.15982938},["Bones"]={90},["Weights"]={1}},{["Position"]={-0.194128958,0.152175625,0.190466057},["Bones"]={90},["Weights"]={1}},{["Position"]={-0.0973510576,0.290405048,0.245477242},["Bones"]={90},["Weights"]={1}},{["Position"]={-0.263054896,0.152146756,0.189121143},["Bones"]={90},["Weights"]={1}},{["Position"]={-0.0937713936,0.333992283,0.0854383754},["Bones"]={90},["Weights"]={1}},{["Position"]={-0.196237618,0.176251606,0.185223919},["Bones"]={90},["Weights"]={1}}},["Eyes"]={{["Top"]={-0.138742336,4.97835402,-0.20460715},["Width"]=0.22,["Height"]=0.19,["Yaw"]=0.4},{["Top"]={0.138742332,4.97835402,-0.204607167},["Width"]=0.22,["Height"]=0.19,["Yaw"]=-0.4}},["Neutral"]=true,["BuildId"]="e0636f2427638f5f"}
local encoded={["Main"]={["Data"]="",["Size"]=379704,["Hash"]="036128f3aae81b71",["Extension"]=".mesh"},["Hair"]={["Data"]="",["Size"]=125364,["Hash"]="e870d599c00cdc5f",["Extension"]=".mesh"},["LidMesh"]={["Data"]="",["Size"]=1129,["Hash"]="1e55b1e927d815eb",["Extension"]=".mesh"},["LidTexture"]={["Data"]="",["Size"]=7815,["Hash"]="e828aec40dda359a",["Extension"]=".png"},["Details"]={["Data"]="",["Size"]=32496,["Hash"]="24521f02a69ceb83",["Extension"]=".mesh"},["Eyes"]={["Data"]="",["Size"]=10104,["Hash"]="cb178e278e081bb3",["Extension"]=".mesh"},["MainTexture"]={["Data"]="",["Size"]=3120623,["Hash"]="2230febb723135ac",["Extension"]=".png"},["DetailTexture"]={["Data"]="",["Size"]=10487,["Hash"]="93315a38d6060c1e",["Extension"]=".png"},["EyeTexture"]={["Data"]="",["Size"]=58469,["Hash"]="b112c7815639d839",["Extension"]=".png"}}
local decoded,uris={},{}
local alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function decode(text,valid,wait)
    local api=crypt and(crypt.base64decode or crypt.base64 and crypt.base64.decode)
    if type(api)=="function"then local ok,value=pcall(api,text);if ok and type(value)=="string"then return value end end
    local map={};for i=1,#alphabet do map[alphabet:byte(i)]=i-1 end
    local blocks,pieces={},{}
    for i=1,#text,4 do
        local a,b,c,d=text:byte(i,i+3);local n=map[a]*262144+map[b]*4096+(map[c]or 0)*64+(map[d]or 0)
        local value=string.char(math.floor(n/65536)%256)
        if c~=61 then value..=string.char(math.floor(n/256)%256)end
        if d~=61 then value..=string.char(n%256)end
        pieces[#pieces+1]=value
        if #pieces>=8192 then
            blocks[#blocks+1]=table.concat(pieces);table.clear(pieces)
            assert(valid(),"Aqua loading cancelled");if wait then wait()end
        end
    end
    blocks[#blocks+1]=table.concat(pieces);return table.concat(blocks)
end
function Assets.Bytes(key,valid,wait)
    assert(valid(),"Aqua loading cancelled")
    if decoded[key]then return decoded[key]end
    local item=assert(encoded[key],"Unknown Aqua asset")
    local data=decode(item.Data,valid,wait);assert(valid(),"Aqua loading cancelled")
    assert(#data==item.Size,"Aqua asset decoding failed")
    decoded[key]=data;return data
end
function Assets.Get(key,files,valid)
    assert(valid(),"Aqua loading cancelled")
    if uris[key]then return uris[key]end
    assert(type(files.Write)=="function"and type(files.CustomAsset)=="function","Aqua needs writefile and getcustomasset/getsynasset")
    local item=assert(encoded[key]);local path="astral_aqua456_"..key:lower().."_"..item.Hash..item.Extension
    local exists=false
    if files.IsFile and files.Read then local ok,value=pcall(function()return files.IsFile(path)and #files.Read(path)==item.Size end);exists=ok and value==true end
    if not exists then
        local data=Assets.Bytes(key,valid,files.Wait);assert(valid(),"Aqua loading cancelled");files.Write(path,data)
    end
    assert(valid(),"Aqua loading cancelled")
    local uri=files.CustomAsset(path);assert(type(uri)=="string"and #uri>0,"Executor cannot load Aqua mesh/texture files")
    uris[key]=uri;return uri
end
return Assets

