sources.AntiGrabWalk = [========[
-- Native release plus local walking-rig protection. No root transform,
-- velocity, height or walk-speed controller is introduced.
local requireModule=...
local WalkingRig=requireModule("WalkingRig")
local Guard={};Guard.__index=Guard
local nativeModes={Normal=true,["No Ragdoll"]=true}
local knownModes={Normal=true,["No Ragdoll"]=true,["Anti-Kill"]=true,["Escapes Anything, but buggy"]=true}
function Guard.Install(context)
    local self=setmetatable({Context=context,Calls=0,ClearCalls=0,Status="Disabled",Generation=0},Guard)
    self.Rig=WalkingRig.new({GrabWelds=context.GrabWelds})
    local signal=context.RunService.PreSimulation or context.RunService.Heartbeat
    self.PhysicsConnection=signal:Connect(function()
        if self.Closed then return end
        local ok,message=pcall(self.UpdateRig,self)
        if not ok then self.LastError="Walking rig: "..tostring(message);self.Rig:Call(self.Rig.Unbind,self.Rig)end
    end)
    self.Connection=context.RunService.Heartbeat:Connect(function()self:Refresh()end)
    return self
end
function Guard:UpdateRig()
    local ctx=self.Context
    local c,r,h=ctx.Character()
    local mode=ctx.Mode();if not knownModes[mode]then mode="Normal"end
    local enabled=not self.Closed and ctx.Enabled()and nativeModes[mode]and not(ctx.Blocked and ctx.Blocked())
    self.Rig:Step(c,r,h,enabled,ctx.Held(),ctx.Clock())
end
function Guard:SetActive(value)
    if self.Reported==value then return end
    self.Reported=value
    if self.Context.SetActive then
        local ok,message=pcall(self.Context.SetActive,value)
        if not ok then self.LastError="Anti Grab state: "..tostring(message)end
    end
end
function Guard:Valid(session)
    if self.Closed or self.Session~=session or not self.Context.Enabled()or not self.Context.Held()then return false end
    local c,r,h=self.Context.Character()
    return c==session.Character and r==session.Root and h==session.Humanoid
        and r and r.Parent~=nil and h and h.Parent==c and h.Health>0
end
function Guard:Call(callback,...)
    local ok,message=pcall(callback,...)
    if not ok then self.LastError=tostring(message)end
    return ok
end
function Guard:Stop(reason)
    local session=self.Session;self.Session=nil;self.Generation+=1
    if session then
        local h=session.Humanoid
        if session.WroteSit and h.Parent==session.Character and h.Sit==true and not h.SeatPart then
            h.Sit=session.OriginalSit
            if not session.OriginalSit and h.Health>0 and h.FloorMaterial~=Enum.Material.Air then
                pcall(h.ChangeState,h,Enum.HumanoidStateType.Running)
            end
        end
        -- One final native clear after a confirmed release. Never send a late
        -- callback to a replacement root, or issue requests while unloading.
        if reason=="released"and nativeModes[session.Mode]and not self.Closed then
            local c,r,h=self.Context.Character()
            if c==session.Character and r==session.Root and h==session.Humanoid and r.Parent and h.Health>0 then
                if self:Call(self.Context.Ragdoll,r,0)then self.ClearCalls+=1 end
            end
        end
    end
    self:SetActive(false);self.Status=reason or "Disabled"
end
function Guard:Step()
    if self.Closed then return end
    local ctx=self.Context
    if not ctx.Enabled()then self:Stop("Disabled");return end
    if not ctx.Held()then self:Stop("released");return end
    local c,r,h=ctx.Character()
    if not c or not r or not r.Parent or not h or h.Parent~=c or h.Health<=0 then self:Stop("Waiting for character");return end
    local mode=ctx.Mode();if not knownModes[mode]then mode="Normal"end
    local session=self.Session
    if session and(session.Character~=c or session.Root~=r or session.Humanoid~=h or session.Mode~=mode)then self:Stop("Character/mode changed");session=nil end
    if not session then
        session={Character=c,Root=r,Humanoid=h,Mode=mode,NextStruggle=0,NextClear=0,NextEscape=0}
        self.Session=session;self:SetActive(true)
    end
    local now=ctx.Clock()
    -- Preserve the source's 30 Hz request cadence independently of rendering
    -- FPS. No zero-velocity/CFrame writes suppress gravity between requests.
    if now>=session.NextStruggle then
        session.NextStruggle=now+1/30
        if self:Call(ctx.Struggle)then self.Calls+=1 end
        if nativeModes[mode]and ctx.RecoverAnimation then self:Call(ctx.RecoverAnimation,h)end
    end
    if mode~="Escapes Anything, but buggy"and now>=session.NextClear then
        session.NextClear=now+1/30
        if self:Call(ctx.Ragdoll,r,mode=="Anti-Kill"and .11 or 0)then self.ClearCalls+=1 end
    end
    if nativeModes[mode]then
        self.Status="Walking rig protected; native release requested"
    elseif mode=="Anti-Kill"then
        if not h.SeatPart then
            if not session.WroteSit then session.OriginalSit=h.Sit;session.WroteSit=true end
            h.Sit=true
        end
        self.Status="Anti-Kill release requested"
    elseif ctx.ExtraEscape and not session.EscapeBusy and now>=session.NextEscape then
        session.NextEscape=now+2;session.EscapeBusy=true
        ctx.Spawn(function()
            if self:Valid(session)then self:Call(ctx.ExtraEscape,function()return self:Valid(session)end)end
            session.EscapeBusy=false
        end)
        self.Status="Legacy escape requested"
    end
end
function Guard:Refresh()
    if self.Closed then return end
    local ok,message=pcall(function()self:UpdateRig();self:Step()end)
    if not ok then self.LastError=tostring(message);self.Rig:Call(self.Rig.Unbind,self.Rig);self:Stop("Anti Grab error")end
end
function Guard:Dispose()
    if self.Closed then return end
    self.Closed=true
    if self.Connection then self.Connection:Disconnect()end
    if self.PhysicsConnection then self.PhysicsConnection:Disconnect()end
    self.Rig:Dispose()
    self:Stop("Disabled")
end
return Guard

