sources.ESPMotion = [========[
-- Bounded world-space filtering for the server-location detector overlay.
-- No camera/screen smoothing: camera motion is projected immediately.
local Motion={}
local function finite(n)return type(n)=="number"and n==n and math.abs(n)<math.huge end
local function good(v)return finite(v.X)and finite(v.Y)and finite(v.Z)end
function Motion.New(frame,now)
    return {Frame=frame,Target=frame,Sample=frame,SampleAt=now,RenderedAt=now,Velocity=Vector3.zero}
end
function Motion.Sample(state,frame,now)
    if not good(frame.Position)or not finite(now)then return false end
    local delta=frame.Position-state.Sample.Position
    local elapsed=now-state.SampleAt
    if delta.Magnitude>64 or elapsed>.65 or elapsed<0 then
        state.Frame=frame;state.Velocity=Vector3.zero;state.RenderedAt=now
    elseif elapsed>1/240 then
        local velocity=delta/elapsed
        if velocity.Magnitude>180 then velocity=velocity.Unit*180 end
        state.Velocity=state.Velocity:Lerp(velocity,.55)
    end
    state.Sample=frame;state.Target=frame;state.SampleAt=now
    return true
end
function Motion.Step(state,now,dt)
    if not finite(now)then return state.Frame,false end
    dt=finite(dt)and math.clamp(dt,0,.1)or math.clamp(now-state.RenderedAt,0,.1)
    state.RenderedAt=now
    local age=math.max(0,now-state.SampleAt)
    local lead=state.Velocity*math.min(age,.045)*math.exp(-math.max(0,age-.045)*24)
    if lead.Magnitude>2 then lead=lead.Unit*2 end
    local target=state.Target+lead
    local gap=target.Position-state.Frame.Position
    if gap.Magnitude>64 then state.Frame=state.Target;state.Velocity=Vector3.zero
    else state.Frame=state.Frame:Lerp(target,1-math.exp(-28*dt))end
    local settled=age>.15 and(state.Target.Position-state.Frame.Position).Magnitude<.008
    if settled then state.Frame=state.Target;state.Velocity=Vector3.zero end
    return state.Frame,not settled
end
return Motion

