sources.Intro = [========[
local Intro = {}

function Intro.Play()
    local gui
    local watchdog
    local tweens = {}
    local closed = false

    local function close()
        if closed then return end
        closed = true
        for _, tween in ipairs(tweens) do
            pcall(function() tween:Cancel() end)
        end
        if gui then pcall(function() gui:Destroy() end) end
    end

    local ok, message = xpcall(function()
        local TweenService = game:GetService("TweenService")
        local Players = game:GetService("Players")
        gui = Instance.new("ScreenGui")
        gui.Name = "AstralIntro"
        gui.ResetOnSpawn = false
        gui.IgnoreGuiInset = true
        gui.DisplayOrder = 2147483000
        gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        pcall(function() gui.ScreenInsets = Enum.ScreenInsets.None end)

        local protect = protect_gui or protectgui or (syn and syn.protect_gui)
        if type(protect) == "function" then pcall(protect, gui) end
        local parented = false
        local getRoot = gethui or get_hidden_gui
        if type(getRoot) == "function" then
            parented = pcall(function()
                local parent = getRoot()
                assert(parent, "GUI root unavailable")
                gui.Parent = parent
            end)
        end
        if not parented then
            parented = pcall(function() gui.Parent = game:GetService("CoreGui") end)
        end
        if not parented then
            local player = Players.LocalPlayer
            local parent = player and player:WaitForChild("PlayerGui", 3)
            assert(parent, "Intro GUI parent unavailable")
            gui.Parent = parent
        end

        watchdog = task.delay(20, function()
            watchdog = nil
            close()
        end)

        local shade = Instance.new("Frame")
        shade.Name = "Shade"
        shade.Size = UDim2.fromScale(1, 1)
        shade.BackgroundColor3 = Color3.fromRGB(5, 5, 5)
        shade.BackgroundTransparency = 1
        shade.BorderSizePixel = 0
        shade.Active = true
        shade.Parent = gui

        local center = Instance.new("Frame")
        center.Name = "Title"
        center.AnchorPoint = Vector2.new(0.5, 0.5)
        center.Position = UDim2.new(0.5, 0, 0.5, 18)
        center.Size = UDim2.new(0.9, 0, 0.2, 0)
        center.BackgroundTransparency = 1
        center.Parent = shade
        local bounds = Instance.new("UISizeConstraint")
        bounds.MaxSize = Vector2.new(1100, 150)
        bounds.Parent = center

        local function animate(object, duration, properties)
            if closed then return end
            local tween = TweenService:Create(object, TweenInfo.new(duration, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), properties)
            tweens[#tweens + 1] = tween
            tween:Play()
        end

        local function label(name, zindex)
            local text = Instance.new("TextLabel")
            text.Name = name
            text.Size = UDim2.fromScale(1, 1)
            text.BackgroundTransparency = 1
            text.Text = "astral"
            text.Font = Enum.Font.GothamBold
            text.TextScaled = true
            text.TextWrapped = true
            text.TextColor3 = Color3.fromRGB(255, 255, 255)
            text.TextTransparency = 1
            text.TextStrokeTransparency = 1
            text.ZIndex = zindex
            text.Parent = center
            local limit = Instance.new("UITextSizeConstraint")
            limit.MinTextSize = 16
            limit.MaxTextSize = 40
            limit.Parent = text
            return text
        end

        local strokes = {}
        local softGlow = {0.995, 0.985, 0.97, 0.945, 0.905, 0.84, 0.73, 0.48, 0.2}
        local brightGlow = {0.987, 0.975, 0.955, 0.925, 0.87, 0.78, 0.64, 0.36, 0.08}
        for i, width in ipairs({30, 24, 19, 15, 11, 8, 5, 3, 1}) do
            local glow = label("Glow" .. i, i)
            local stroke = Instance.new("UIStroke")
            stroke.Color = Color3.fromRGB(100 + i * 13, 100 + i * 13, 100 + i * 13)
            stroke.Thickness = width
            stroke.Transparency = 1
            stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual
            stroke.Parent = glow
            strokes[#strokes + 1] = stroke
        end
        local title = label("Text", 12)
        local gradient = Instance.new("UIGradient")
        gradient.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(170, 170, 170)),
            ColorSequenceKeypoint.new(0.5, Color3.fromRGB(255, 255, 255)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(205, 205, 205)),
        })
        gradient.Parent = title

        animate(shade, 1.6, {BackgroundTransparency = 0.05})
        task.wait(0.6)
        if closed then return end
        animate(title, 1.8, {TextTransparency = 0})
        animate(center, 2.4, {Position = UDim2.fromScale(0.5, 0.5)})
        for i, stroke in ipairs(strokes) do
            animate(stroke, 1.8, {Transparency = softGlow[i]})
        end
        task.wait(1.8)
        if closed then return end
        for _ = 1, 2 do
            for i, stroke in ipairs(strokes) do
                animate(stroke, 1.2, {Transparency = brightGlow[i]})
            end
            task.wait(1.2)
            if closed then return end
            for i, stroke in ipairs(strokes) do
                animate(stroke, 1.2, {Transparency = softGlow[i]})
            end
            task.wait(1.2)
            if closed then return end
        end
        animate(title, 1.4, {TextTransparency = 1})
        animate(center, 1.8, {Position = UDim2.new(0.5, 0, 0.5, -6)})
        for _, stroke in ipairs(strokes) do animate(stroke, 1.4, {Transparency = 1}) end
        task.wait(0.8)
        if closed then return end
        animate(shade, 1.4, {BackgroundTransparency = 1})
        task.wait(1.4)
    end, function(err) return tostring(err) end)

    if watchdog then pcall(task.cancel, watchdog) end
    close()
    return ok, message
end

return Intro

]========]
sources.Library = [========[
local requireModule = ...
local Brand=requireModule("Branding")
local Identity = requireModule("AppIdentity")
local MenuDecor = requireModule("MenuDecor")
local FunctionGlyphs = requireModule("FunctionGlyphs")
local cloneref = (cloneref or clonereference or function(instance: any)
    return instance
end)
local CoreGui: CoreGui = cloneref(game:GetService("CoreGui"))
local GuiService: GuiService = cloneref(game:GetService("GuiService"))
local Players: Players = cloneref(game:GetService("Players"))
local RunService: RunService = cloneref(game:GetService("RunService"))
local SoundService: SoundService = cloneref(game:GetService("SoundService"))
local UserInputService: UserInputService = cloneref(game:GetService("UserInputService"))
local TextService: TextService = cloneref(game:GetService("TextService"))
local Teams: Teams = cloneref(game:GetService("Teams"))
local TweenService: TweenService = cloneref(game:GetService("TweenService"))

local getgenv = getgenv or function()
    return shared
end
local setclipboard = setclipboard or nil
local protectgui = protectgui or (syn and syn.protect_gui) or function() end
local gethui = gethui or function()
    return CoreGui
end

local LocalPlayer = Players.LocalPlayer or Players.PlayerAdded:Wait()
local Mouse = cloneref(LocalPlayer:GetMouse())

local Labels = {}
local Buttons = {}
local Toggles = {}
local Options = {}
local Tooltips = {}

local BaseURL = "https://raw.githubusercontent.com/deividcomsono/Obsidian/fb0b7b22604664ab94bea7c67e2a14ab1a47ec27/"
local CustomImageManager = {}
local CustomImageManagerAssets = {
    TransparencyTexture = {
        RobloxId = 139785960036434,
        Path = "Astral/Assets/TransparencyTexture.png",
        URL = BaseURL .. "assets/TransparencyTexture.png",

        Id = nil,
    },

    SaturationMap = {
        RobloxId = 4155801252,
        Path = "Astral/Assets/SaturationMap.png",
        URL = BaseURL .. "assets/SaturationMap.png",

        Id = nil,
    },

    LoadingIcon = {
        RobloxId = 97544096941083,
        Path = "Astral/Assets/LoadingIcon.png",
        URL = BaseURL .. "assets/LoadingIcon.png",

        Id = nil,
    },

    CheckIcon = {
        RobloxId = 97682394690683,
        Path = "Astral/Assets/CheckIcon.png",
        URL = BaseURL .. "assets/CheckIcon.png",

        Id = nil,
    },
}
do
    local function RecursiveCreatePath(Path: string, IsFile: boolean?)
        if not isfolder or not makefolder then
            return
        end

        local Segments = Path:split("/")
        local TraversedPath = ""

        if IsFile then
            table.remove(Segments, #Segments)
        end

        for _, Segment in ipairs(Segments) do
            if not isfolder(TraversedPath .. Segment) then
                makefolder(TraversedPath .. Segment)
            end

            TraversedPath = TraversedPath .. Segment .. "/"
        end

        return TraversedPath
    end

    function CustomImageManager.AddAsset(
        AssetName: string,
        RobloxAssetId: number,
        URL: string,
        ForceRedownload: boolean?
    )
        if CustomImageManagerAssets[AssetName] ~= nil then
            error(string.format("Asset %q already exists", AssetName))
        end

        assert(typeof(RobloxAssetId) == "number", "RobloxAssetId must be a number")

        CustomImageManagerAssets[AssetName] = {
            RobloxId = RobloxAssetId,
            Path = string.format("Astral/CustomAssets/%s", AssetName),
            URL = URL,

            Id = nil,
        }

        CustomImageManager.DownloadAsset(AssetName, ForceRedownload)
    end

    function CustomImageManager.GetAsset(AssetName: string)
        if not CustomImageManagerAssets[AssetName] then
            return nil
        end

        local AssetData = CustomImageManagerAssets[AssetName]
        if AssetData.Id then
            return AssetData.Id
        end

        local AssetID = string.format("rbxassetid://%s", AssetData.RobloxId)

        if getcustomasset then
            local Success, NewID = pcall(getcustomasset, AssetData.Path)

            if Success and NewID then
                AssetID = NewID
            end
        end

        AssetData.Id = AssetID
        return AssetID
    end

    function CustomImageManager.DownloadAsset(AssetName: string, ForceRedownload: boolean?)
        if not getcustomasset or not writefile or not isfile then
            return false, "missing functions"
        end

        local AssetData = CustomImageManagerAssets[AssetName]

        RecursiveCreatePath(AssetData.Path, true)

        if ForceRedownload ~= true and isfile(AssetData.Path) then
            return true, nil
        end

        local success, errorMessage = pcall(function()
            writefile(AssetData.Path, game:HttpGet(AssetData.URL))
        end)

        return success, errorMessage
    end

    for AssetName, _ in CustomImageManagerAssets do
        CustomImageManager.DownloadAsset(AssetName)
    end
end

local Library = {
    LocalPlayer = LocalPlayer,
    IsRobloxFocused = true,

    DevicePlatform = nil,
    IsMobile = false,

    ScreenGui = nil,
