local Lucide = {}

local IS_GETCUSTOMASSET_BROKEN = false

if writefile and isfolder and makefolder and getcustomasset then
    if not isfolder("Astral")then makefolder("Astral")end
	if not isfolder("Astral/Icons") then
		makefolder("Astral/Icons")
	end

	if not isfile("Astral/Icons/version.txt") then
		writefile("Astral/Icons/version.txt", "2026-09-01T03:49:17.713242330+00:00")
	end

	local ShouldUpdate = readfile("Astral/Icons/version.txt") ~= "2026-09-01T03:49:17.713242330+00:00"

	if ShouldUpdate then
		writefile("Astral/Icons/version.txt", "2026-09-01T03:49:17.713242330+00:00")
	end

	for spritesheet = 1, 2 do
		if isfile(`Astral/Icons/{spritesheet}.png`) and not ShouldUpdate then
			continue
		end

		writefile(
			`Astral/Icons/{spritesheet}.png`,
			game:HttpGet(
				`https://raw.githubusercontent.com/mstudio45/lucide-roblox-direct/1c37dd176d79ab42388597aa9dc9e3a1b0dd7416/spritesheets/{spritesheet}.png`
			)
		)
	end

	local Success, _Error = pcall(function()
		return getcustomasset("Astral/Icons/1.png")
	end)

	IS_GETCUSTOMASSET_BROKEN = not Success
end

