									end

									attachment.Position = vector
									tbl18[i2] = attachment
									tbl16[#tbl16 + 1] = { attachment, i, n36 }
								end

								for i2 = 1, 24 do
									local beam = Instance.new("Beam", v30)
									local v31 = tbl18[i2]
									local v32 = tbl18[i2 % 24 + 1]
									beam.Attachment0 = v31
									beam.Attachment1 = v32
									local colorSequence = ColorSequence.new(arg3)
