										else
											n38 = 1
										end

										offsets[#offsets + 1] = CFrame.new((v23.X + n38 * coconutForms.Spacing67 * 0.5) * n37, v23.Y, 0.75)
									end
								elseif CoconutPoses.Counts[v22] then
									for _,offset in ipairs(CoconutPoses.Build(v22))do
