        local packetGuard=requireModule("PacketGuard").Install({RunService=RunService,Player=localPlayer,Clock=os.clock,Spawn=task.spawn,
            GetConnections=getconnections,OwnFunctions=tbl12.PacketMonitorFunctions,
            HookFunction=hookfunction or replaceclosure,RestoreFunction=restorefunction,IsLClosure=islclosure,
            Remotes=function()
                -- Every client-received RemoteEvent that a packet-lagger from ANY
                -- script can abuse, discovered live, with the two known ones first.
                local list,seen={},{}
                local function add(r)
                    if typeof(r)=="Instance" and r:IsA("RemoteEvent") and not seen[r] then
                        seen[r]=true;list[#list+1]=r
                    end
                end
                add(tbl11.Packet);add(tbl11.CreateGrabLine)
                for _,name in ipairs({"GrabEvents","CharacterEvents"})do
                    local folder=ReplicatedStorage:FindFirstChild(name)
                    if folder then for _,child in ipairs(folder:GetChildren())do add(child) end end
                end
                return list
            end,
        })
        packetGuard:SetProfile("Strict")
        lib:OnUnload(function() packetGuard:Dispose() end)
        local packetStatus,nextPacketStatus
        Antis:AddToggle("AntiPacketLag",{Text="Anti Packet-Lag",Default=false,
            Tooltip="Filters every client Grab/Character remote (any script's packet-lag, not just Astral): oversized packets, far line-lag CFrames and floods dropped, flooders muted 5s. getconnections with hookfunction fallback. Does not block network delivery or server lag.",
            Callback=function(value)
                local ok,message=packetGuard:SetEnabled(value)
                tbl12.SetRuntimeConnection("PacketGuardStatus",RunService.Heartbeat,packetGuard.Enabled,function()
                    local now=os.clock();if nextPacketStatus and now<nextPacketStatus then return end;nextPacketStatus=now+.3
                    if packetStatus then packetStatus:SetText(packetGuard:Describe()) end
                    if not packetGuard.Enabled and toggles.AntiPacketLag.Value then toggles.AntiPacketLag:SetValue(false) end
                end)
                if packetStatus then packetStatus:SetText(packetGuard:Describe()) end
                if value and not ok then
                    fn18(message)
                    task.defer(function() if not flag11 and toggles.AntiPacketLag then toggles.AntiPacketLag:SetValue(false) end end)
                end
            end})
