                if tbl8.LoopApplyMethodTServer and tbl7.TargetMethods.Kick then return tbl12.GetTargets(true,tbl7.SelectedPlayers)end
                if tbl8.LoopApplyMethodT and tbl7.TargetMethods.Kick then return tbl12.GetTargets(false,tbl7.SelectedPlayers)end
                return {}
            end})
        lib:OnUnload(function()tbl12.PCLDFreeze:Dispose()end)
        local decoyModels=setmetatable({},{__mode="k"})
        tbl12.DecoyGucci=requireModule("DecoyGucci").Install({RunService=RunService,Library=lib,Clock=os.clock,SpawnThread=task.spawn,Wait=task.wait,
            Character=function()return tbl12.Char()end,
            Targets=function()return tbl12.GetTargets(false,tbl7.SelectedPlayers)end,
            Selected=function(player)return tbl7.SelectedPlayers[player]==true end,
            Protected=tbl12.IsProtectedPlayer,Inventory=tbl12.GetInventory,
            SharedTrain=function()local map=workspace:FindFirstChild("Map");local objects=map and map:FindFirstChild("AlwaysHereTweenedObjects");return objects and objects:FindFirstChild("Train")end,
            TargetSeat=function(player)local _,_,humanoid=tbl12.Char(player);return humanoid and humanoid.SeatPart end,
            TargetCharacter=function(player)local character,_,humanoid=tbl12.Char(player);return character,humanoid end,
            CanSpawn=function()
                if flag11 then return false,"Astral is unloading"end
                return requireModule("GameFlags").CanBuild(localPlayer,tbl7.States,tbl7.SpawnQueue)
            end,
            SpawnToy=function()
                -- No queue wait, SNO or foreign-plot spawn path is allowed.
                if flag11 or not requireModule("GameFlags").CanBuild(localPlayer,tbl7.States,tbl7.SpawnQueue)then return nil end
                local model=tbl12.SpawnToy("YouDecoy",nil,0,true)
                if model and model.Parent==v17 and model~=localPlayer.Character then decoyModels[model]=true end
                return model
            end,
            IsOwnToy=function(model)return model and decoyModels[model]==true and model~=localPlayer.Character and model.Parent==v17 end,
            Destroy=function(model)
                if model and decoyModels[model]and model~=localPlayer.Character then
                    decoyModels[model]=nil;tbl7.ToyAuraReserved[model]=nil;if model.Parent==v17 then tbl12.DestroyToy(model)end
                end
            end,
            BeforeEnable=function()
                if toggles.TargetLoopGucci and toggles.TargetLoopGucci.Value then toggles.TargetLoopGucci:SetValue(false)end
                local busy=tbl12.TargetPanel and tbl12.TargetPanel.Busy.Gucci
                if busy and next(busy)then return false,"Wait for the native Gucci attempt to finish, then enable YouDecoy again"end
                return true
            end,
            AfterEnable=function(value)
                local panel=tbl12.TargetPanel
                if value and panel and panel.GucciToggle and panel.GucciToggle.Value then panel.GucciToggle:SetValue(false)end
                if panel and panel.GucciToggle then panel.GucciToggle:SetDisabled(false)end
                if panel and panel.GucciButton then panel.GucciButton:SetDisabled(false)end
            end,
            Owned=tbl12.IsNetworkOwner,
            RequestOwner=function(root)
                if not root or not root.Parent or not decoyModels[root.Parent]or root.Parent.Parent~=v17 or root.Name~="HumanoidRootPart"then return false,"Only the registered YouDecoy root is accepted"end
                if tbl8.LoopApplyMethodT or tbl8.LoopApplyMethodTServer or tbl7.States.Owning then return false,"Start the decoy before Kick; existing grabbing is not interrupted"end
                tbl12.Grab(root);return true
            end,
            ReleaseRequest=function(root)
                if not root or not root.Parent or not decoyModels[root.Parent]then return false end
                if tbl8.LoopApplyMethodT or tbl8.LoopApplyMethodTServer or tbl7.States.Owning then return false end
                tbl12.RNO(root);return true
            end,
        })
        do
            local function detached(model)
                if not model or not model.Parent then return false end
                for _,item in ipairs(model:GetDescendants())do
                    if (item:IsA("Seat")or item:IsA("VehicleSeat"))and item.Occupant then return false end
                    if item:IsA("BasePart")then
                        for _,part in ipairs(item:GetConnectedParts(true))do if not part:IsDescendantOf(model)then return false end end
                    elseif item:IsA("RigidConstraint")and item.Enabled then
                        for _,key in ipairs({"Attachment0","Attachment1"})do local a=item[key];if a and not a:IsDescendantOf(model)then return false end end
                    end
                end
                return true
            end
            local function character()
                local c=localPlayer.Character;if not c then return end
                return c,c:FindFirstChild("realHrp")or c:FindFirstChild("HumanoidRootPart"),c:FindFirstChildOfClass("Humanoid")
            end
            tbl12.GucciDestroy=requireModule("GucciDestroy").Install({RunService=RunService,Clock=os.clock,Wait=task.wait,Spawn=task.spawn,
                Character=character,TargetCharacter=tbl12.Char,Targets=function()return tbl12.GetTargets(false,tbl7.SelectedPlayers)end,
                Selected=function(player)return tbl7.SelectedPlayers[player]==true end,Protected=tbl12.IsProtectedPlayer,Inventory=tbl12.GetInventory,
                SharedTrain=function()local m=workspace:FindFirstChild("Map");local a=m and m:FindFirstChild("AlwaysHereTweenedObjects");return a and a:FindFirstChild("Train")end,
                PingSeconds=tbl12.KickPingSeconds,
                KickHeld=function(player)return tbl12.KickLoop:IsHolding(player)end,
                OperationBusy=function()return flag11 or tbl7.States.Owning or tbl7.States.Spawning or tbl8.ControllingSomeone end,
                BeforeEnable=function()
                    if toggles.TargetDecoyGucci and toggles.TargetDecoyGucci.Value then toggles.TargetDecoyGucci:SetValue(false)end
                end,
                BorrowKick=function(token)return tbl12.KickLoop:BeginExcursion(token)end,
                ReleaseKick=function(token)tbl12.KickLoop:EndExcursion(token)end,
                PrepareMovement=function(trip)
                    local paused={}
                    local function restore()
                        if flag11 or lib.Unloaded then return end
                        for i=#paused,1,-1 do local control=paused[i];if not control.Value then pcall(control.SetValue,control,true)end end
                    end
                    trip.RestoreMovement=restore
                    for _,id in ipairs({"AntiGrab","GucciAntiGrab","FlyT","DesyncT","AstralLockPosition","AstralWallClimb","LoopTP","LoopTPToLoc","LoopTPToPlayer","LoopSpectatePlayer","AstralDroneEnabled","AstralSpiderEnabled","LoopApplyMethodTServ"})do
                        local control=toggles[id]
                        if control and control.Value then paused[#paused+1]=control;control:SetValue(false)end
                    end
                    return restore,#paused>0
                end,
                Teleport=function(root,frame)
                    local c,r,h=character();if r~=root or not h or h.Health<=0 then return false end
                    local moved=tbl12.Teleport(root,frame)
                    local camera=workspace.CurrentCamera
                    if camera then camera.CameraType=Enum.CameraType.Custom;camera.CameraSubject=h end
                    return moved
                end,
                RequestDelete=function(model,valid)if valid and not valid()then return false end;if model and model.Parent then tbl12.DestroyToy(model);return true end;return false end,
                Detached=detached,
                DetachHeld=function(model,valid)if valid()and model:FindFirstChild("HoldPart")then tbl12.BreakHoldable(model,.25,false,valid)end end,
                Acquire=function(part,valid)
                    local _,root=character()
                    if not root or not valid()or part.Anchored or(part.Position-root.Position).Magnitude>=28 or tbl7.States.Owning then return false end
                    tbl12.SNO(part,.25,valid)
                    return valid()and tbl12.IsNetworkOwner(part)and tbl12.IsPartOwner(part)
                end,
                PhysicalDelete=function(model,part,valid)
                    local _,root=character()
                    if (not valid or valid())and not flag11 and root and part.Parent and(part.Position-root.Position).Magnitude<28 and detached(model)
                        and tbl12.IsPartOwner(part)and tbl12.IsNetworkOwner(part)then return tbl12.DestroyObject(model,part,valid)end
                end,
            })
            lib:OnUnload(function()tbl12.GucciDestroy:Dispose()end)
        end
        -- ASTRAL_DESTROY_DESYNC_BEGIN
        tbl12.DesyncDestroy=requireModule("DestroyDesync").Install({RunService=RunService,Clock=os.clock,Spawn=task.spawn,
            Supported=typeof(sethiddenproperty)=="function"and typeof(gethiddenproperty)=="function",
            Targets=function()return tbl12.GetTargets(false,tbl7.SelectedPlayers)end,
            Selected=function(player)return player and player.Parent and tbl7.SelectedPlayers[player]==true and not tbl12.IsProtectedPlayer(player)end,
            Character=tbl12.Char,LocalCharacter=function()return tbl12.Char()end,
            KickSession=function(player)
                local loop=tbl12.KickLoop;local session=loop and loop.Sessions[player]
                if session and loop:Valid(session)then return session end
            end,
            Paused=function()return flag11 or localPlayer.InPlot.Value or tbl12.KickLoop.Excursion~=nil
                or tbl12.GucciDestroy and tbl12.GucciDestroy.Busy~=nil and tbl12.GucciDestroy.Busy~=false
                or tbl7.KickServerState and tbl7.KickServerState.Running==true end,
            Busy=function()return tbl7.States.Owning==true end,
            Owned=function(root)return not root.Anchored and tbl12.IsNetworkOwner(root)and tbl12.IsPartOwner(root)end,
            Grab=tbl12.Grab,Release=tbl12.RNO,
            Acquire=function(root,valid)return tbl12.SNO(root,.65,valid)end,
            RequestRagdoll=function(character,valid)return tbl12.PalletRagdoll:Request(character,valid)end,
            CancelRagdoll=function(character)tbl12.PalletRagdoll:Cancel(character)end,
            PingSeconds=tbl12.KickPingSeconds,
            Reset=function(root,valid)
                if typeof(sethiddenproperty)~="function"or typeof(gethiddenproperty)~="function"then return false,"Executor cannot verify replication reset"end
                if not root or not root.Parent or root.Anchored or not tbl12.IsNetworkOwner(root)or not tbl12.IsPartOwner(root)then return false,"Ownership lost before reset"end
                if valid and not valid()then return false,"Recovery attempt cancelled"end
                local readable,before=pcall(gethiddenproperty,root,"PhysicsRepRootPart")
                if not readable then return false,"Replication property is unavailable"end
                if valid and not valid()then return false,"Recovery attempt cancelled"end
                if not root.Parent or root.Anchored or not tbl12.IsNetworkOwner(root)or not tbl12.IsPartOwner(root)then return false,"Ownership lost before reset"end
                if before==nil then return true,"Already clear locally",false end
                local wrote=pcall(sethiddenproperty,root,"PhysicsRepRootPart",nil)
                local read,value=pcall(gethiddenproperty,root,"PhysicsRepRootPart")
                if wrote and read and value==nil then return true,"Local reset verified",true end
                return false,"Executor rejected replication reset"
            end,
        })
        lib:OnUnload(function()tbl12.DesyncDestroy:Dispose()end)
        -- ASTRAL_DESTROY_DESYNC_END
        tbl12.TargetPanel=requireModule("TargetPanel").Install({API=tbl12,Data=tbl7,Library=lib,RunService=RunService,Spawn=task.spawn,Notify=fn18,Decoy=tbl12.DecoyGucci,Gucci=tbl12.GucciDestroy,Desync=tbl12.DesyncDestroy})
