            local leg=character:FindFirstChild("Left Leg");local feet=leg and root.Size.Y*.5+leg.Size.Y or hum.HipHeight+root.Size.Y*.5
            tbl12.Teleport(root,CFrame.new(point+Vector3.new(0,feet+.2,0)))
        end})

