														if not (not fn22() or not rigidConstraint.Parent or rigidConstraint.Attachment1 or os.clock() - now3 > 0.7) then
															continue
														end
														break
													end

													if not fn22() or not rigidConstraint.Parent or not rigidConstraint.Attachment1 then
														fn21()
														continue
													else
