    do
        local contentProvider=game:GetService("ContentProvider")
        local modelContext={Workspace=workspace,Spawn=task.spawn,
            Files={Write=writefile,Read=readfile,IsFile=isfile,CustomAsset=getcustomasset or getsynasset,Wait=task.wait},
            Clock=os.clock,
            Wind=function(position,exclude)
                local wind=workspace.GlobalWind
                local direction=wind.Magnitude>.1 and wind.Unit or Vector3.new(1,0,.25).Unit
                do
                    local params=RaycastParams.new();params.FilterType=Enum.RaycastFilterType.Exclude
                    params.FilterDescendantsInstances={exclude,localPlayer.Character};params.IgnoreWater=true
                    if workspace:Raycast(position,-direction*16,params)then return wind*.12,.12 end
                end
                return wind,1
            end,
            CreateSkinned=function(uri)
                return game:GetService("AssetService"):CreateMeshPartAsync(Content.fromUri(uri),{
                    CollisionFidelity=Enum.CollisionFidelity.Box,RenderFidelity=Enum.RenderFidelity.Precise})
            end,
            CreateEditableMesh=function()return game:GetService("AssetService"):CreateEditableMesh()end,
            CreateEditablePart=function(mesh)
                return game:GetService("AssetService"):CreateMeshPartAsync(Content.fromObject(mesh),{
                    CollisionFidelity=Enum.CollisionFidelity.Box,RenderFidelity=Enum.RenderFidelity.Precise})
            end,
            LoadAsset=function(id)
                return game:GetObjects("rbxassetid://"..tostring(id))
            end,
            Preload=function(instances,valid)
                if not valid()then error("Model loading cancelled",0)end
                local failed
                contentProvider:PreloadAsync(instances,function(uri,status)
                    if status==Enum.AssetFetchStatus.Failure or status==Enum.AssetFetchStatus.TimedOut then failed=uri end
                end)
                if not valid()then error("Model loading cancelled",0)end
                assert(not failed,"Roblox could not load model meshes/textures: "..tostring(failed))
            end,
        }
        tbl12.LocalModels=requireModule("LocalModels").Install({RendererContext=modelContext,Character=function()
                local character=localPlayer.Character;if not character or not character.Parent then return end
                return tbl12.Char()
            end,
            Camera=function()return workspace.CurrentCamera end,Spawn=task.spawn,
            Crouching=function()
                if UserInputService:GetFocusedTextBox()then return false end
                return UserInputService:IsKeyDown(Enum.KeyCode.LeftControl)or UserInputService:IsKeyDown(Enum.KeyCode.RightControl)
                    or UserInputService:IsKeyDown(Enum.KeyCode.C)
            end,
            BindRender=function(callback)
                local name="Astral/LocalModels"
                RunService:BindToRenderStep(name,Enum.RenderPriority.Camera.Value+5,callback)
                return {Disconnect=function()RunService:UnbindFromRenderStep(name)end}
            end,
        })
        lib:OnUnload(function()tbl12.LocalModels:Dispose()end)
        local box=tbl15.Fun:AddLeftTabbox("Models")
        local models=box:AddTab("Models","contact-round")
        local modelChoice=models:AddDropdown("AstralLocalModelChoice",{Text="Character Model",Values={"Tung Tung Tung Sahur","Aqua (CS:GO)"},Default=1,AllowNull=false,
            Tooltip="Sahur loads from Creator Store. Aqua uses the supplied CS:GO model with original textures and skeleton.",
            Callback=function(value)tbl12.LocalModels:SetChoice(value)end})
        models:AddToggle("AstralLocalModelEnabled",{Text="Selected Model (Local)",Default=false,Callback=function(v)
            if v and not tbl12.LocalModels:SetChoice(modelChoice.Value)then fn18(tbl12.LocalModels.Status);return end
            tbl12.LocalModels:SetEnabled(v)
        end})
        models:AddToggle("AstralLocalModelWalk",{Text="Walk Animation",Default=true,Tooltip="Blends standing, walking, running, jumping and seated poses.",Callback=function(v)tbl12.LocalModels.AnimeWalk=v end})
        models:AddToggle("AstralLocalModelCrouch",{Text="Crouch Pose [Ctrl / C]",Default=true,Callback=function(v)tbl12.LocalModels.CrouchInput=v end})
        models:AddSlider("AstralLocalModelScale",{Text="Model Scale",Default=1,Min=.65,Max=1.35,Rounding=2,Compact=true,Suffix="x",Callback=function(v)tbl12.LocalModels.Scale=v end})
        models:AddSlider("AstralLocalModelAnimationSpeed",{Text="Animation Speed",Default=1,Min=.5,Max=1.7,Rounding=2,Compact=true,Suffix="x",Callback=function(v)tbl12.LocalModels.AnimationSpeed=v end})
        models:AddToggle("AstralLocalModelFirstPerson",{Text="Hide In First Person",Default=true,Callback=function(v)tbl12.LocalModels.HideFirstPerson=v end})
        models:AddButton({Text="Reload Model",Func=function()
            local selected=requireModule("LocalModels").ResolveChoice(modelChoice.Value)
            if selected==tbl12.LocalModels.Choice then tbl12.LocalModels:Retry()else tbl12.LocalModels:SetChoice(modelChoice.Value)end
        end})
        models:AddButton({Text="Copy Model Info",Func=function()
            local copy=setclipboard or toclipboard
            if type(copy)~="function"then fn18("Clipboard is unavailable in this executor.");return end
            copy(game:GetService("HttpService"):JSONEncode(tbl12.LocalModels:Describe()))
            fn18("Selected model status and loader information copied.")
        end})
        models:AddLabel("Aqua keeps the supplied CS skeleton and textures; movement is adapted for Roblox. Hold Ctrl or C to crouch. Copy Model Info reports the loaded rig.",true)
        local status=models:AddLabel("Disabled",true);local elapsed=0
        lib:GiveSignal(RunService.Heartbeat:Connect(function(dt)
            elapsed+=dt;if elapsed<.2 then return end;elapsed=0;status:SetText(tbl12.LocalModels.Status)
        end))
    end

    do
        local Flags=requireModule("GameFlags")
        local nextOwn=0;local ownTimes=setmetatable({},{__mode="k"})
        local function canBuild()return Flags.CanBuild(localPlayer,tbl7.States,tbl7.SpawnQueue)end
        local context={RunService=RunService,Clock=os.clock,Wait=task.wait,SpawnThread=task.spawn,
            Character=function()return tbl12.Char()end,CanSpawn=canBuild,
            SpawnFrame=function(index)local _,root=tbl12.Char();return root and root.CFrame*CFrame.new((index%3-1)*2,2,-7)end,
            Spawn=function(id,frame)if not canBuild()or not frame then return end;return tbl12.SpawnToy(id,frame,0,true)end,
            Destroy=function(model)return tbl12.DestroyToy(model)end,
            Release=function(model,valid)if valid()then return tbl12.BreakHoldable(model,.6,false,valid)end;return false end,
            IsOwner=function(part)return tbl12.IsNetworkOwner(part)and tbl12.IsPartOwner(part)end,
            RequestOwner=function(part)
                local _,root,h=tbl12.Char();local now=os.clock()
                if not root or not h or h.Health<=0 or not part or not part.Parent or part.Anchored or not part:IsDescendantOf(v17)then return false end
                if now<nextOwn or now<(ownTimes[part]or 0)or tbl7.States.Owning or (root.Position-part.Position).Magnitude>30 then return false end
                nextOwn=now+.125;ownTimes[part]=now+.65;tbl12.Grab(part);return true
            end,
            OwnToy=function(model)return model and model~=localPlayer.Character and model.Parent==v17 end,
            CharacterOwned=function(root)return tbl12.IsNetworkOwner(root)end,
            RiderHipLocked=function()return tbl8.AntiBanana==true end,
            Gravity=function()return workspace.Gravity end,Flying=function()return tbl8.Flight==true end,
            Ground=function(position,up,down)
                local character=tbl12.Char();if not character then return end
                local params=RaycastParams.new();params.FilterType=Enum.RaycastFilterType.Exclude;params.FilterDescendantsInstances={character,v17}
                params.RespectCanCollide=true;params.IgnoreWater=true
                local hit=workspace:Raycast(position+Vector3.yAxis*up,-Vector3.yAxis*(up+down),params)
                if hit and hit.Normal.Y>=.35 then return hit.Position end
            end,
        }
        local forms=requireModule("SparklerForms").Install(context)
        local spider=requireModule("SpiderWalker").Install(context)
        local vehicles=requireModule("VehicleSpeed").Install({RunService=RunService,Workspace=workspace,
            Character=function()local c,_,h=tbl12.Char();return c,h end,IsOwner=tbl12.IsNetworkOwner})
