        spark:AddDropdown("AstralFormationItem",{Text="Formation Item",Values=forms.Items,ValueImages=requireModule("AssetCatalog").Items,Default="FireworkSparkler",AllowNull=false,Searchable=true,Callback=function(v)forms:SetItem(v)end})
        spark:AddDropdown("AstralFormationMaterial",{Text="Material Mix",Values=forms.Materials,Default="Selected Item",AllowNull=false,Callback=function(v)forms:SetMaterial(v)end})
        spark:AddToggle("AstralFormationGuard",{Text="Restore Grabbed Elements",Default=true,Callback=function(v)forms:SetGuard(v)end})
        spark:AddSlider("SparklerMotionSpeed",{Text="Form Motion Speed",Default=1,Min=0,Max=3,Rounding=2,Compact=true,Suffix="x",Callback=function(v)forms.MotionSpeed=v end})
        spark:AddButton({Text="Retry Missing Rods",Func=function()forms:Retry()end})
        spark:AddButton({Text="Rebuild Sparkler Rig",Func=function()forms:Rebuild()end})
