        drone:AddDropdown("AstralRocketVisual",{Text="Flight Visual",Values={"Rocket","Drone"},Default="Rocket",AllowNull=false,Callback=function(v)tbl12.AstralDrone.SetVisual(v)end})
        drone:AddButton({Text="Spawn Controlled Rocket",Func=function()if not toggles.AstralDroneEnabled.Value then toggles.AstralDroneEnabled:SetValue(true)end;tbl12.AstralDrone.SpawnControlled()end})
        drone:AddButton({Text="Attach Under Cursor [F]",Func=function()tbl12.AstralDrone.AttachUnderMouse()end})
        drone:AddButton({Text="Exit Flight [X]",Func=function()tbl12.AstralDrone.Stop()end})
        drone:AddSlider("AstralDroneSpeed",{Text="Speed",Default=55,Min=10,Max=95,Rounding=0,Callback=function(v)tbl12.AstralDrone.Config.Speed=v end})
        drone:AddSlider("AstralRocketCameraDistance",{Text="Chase Camera Distance",Default=12,Min=6,Max=24,Rounding=0,Callback=function(v)tbl12.AstralDrone.Config.CameraDistance=v end})
        local status=drone:AddLabel("Disabled",true);local elapsed=0
        lib:GiveSignal(RunService.Heartbeat:Connect(function(dt)elapsed+=dt;if elapsed<.2 then return end;elapsed=0;local s=tbl12.AstralDrone.GetStatus();status:SetText(s.Reason or "Ready")end))
