			end,
		})

		v20:AddSlider("WaterTransparency", {
			Text = "Transparency",
			Default = math.round(tbl7.WaterSettings.WaterTransparency * 100) / 100,
			Min = 0,
			Max = 1,
			Rounding = 2,
			Compact = true,
			Callback = function(waterTransparency)
				terrain.WaterTransparency = waterTransparency
