sources.Bootstrap = [========[
local sources = ...
local env = getgenv and getgenv() or _G
assert(type(loadstring) == "function", "This executor does not support loadstring")
assert(type(getgenv) == "function", "This executor does not support getgenv")
local cleanup
local function registerCleanup(fn) cleanup = fn end
local cache = {}
local loading = {}
local environment
local function requireModule(name)
    if cache[name] then return cache[name] end
    assert(not loading[name], "Circular module dependency: " .. tostring(name))
    assert(type(sources[name]) == "string", "Missing module: " .. tostring(name))
    loading[name] = true
    local chunk, message = loadstring(sources[name], "@Astral/" .. name)
    assert(chunk, message)
    if environment then setfenv(chunk,environment)end
    local ok, result = pcall(chunk, requireModule)
    loading[name] = nil
    assert(ok, result)
    assert(type(result) == "table", "Invalid module: " .. name)
    cache[name] = result
    return result
end
local Identity=requireModule("AppIdentity")
Identity.RetireLegacyAstral(env)
local app=Identity.Runtime(env)
if app.Running or app.Starting then
    warn("Astral v4.62: unload the running Astral in Settings before executing this update")
    pcall(function()game:GetService("StarterGui"):SetCore("SendNotification",{
        Title="Astral v4.62 update",Text="Unload the old Astral in Settings, then execute this file again.",Duration=8})end)
    return
end
assert(type(setfenv)=="function","Astral requires setfenv to isolate its runtime")
app.Starting=true
environment=Identity.Environment(env,app)
local reloadPath
local ok, result = xpcall(function()
    local introOk, introError = pcall(function()
        local played, message = requireModule("Intro").Play()
        assert(played, message)
    end)
    if not introOk then warn("astral intro: " .. tostring(introError)) end
    if type(writefile) == "function" and type(readfile) == "function" then
        local success = pcall(function()
            local lines = {"local sources = {}"}
            local names={}
            for name,body in pairs(sources)do if type(name)=="string"and type(body)=="string"then names[#names+1]=name end end
            table.sort(names)
            for _, name in ipairs(names) do
                lines[#lines + 1] = string.format("sources[%q] = %q", name, sources[name])
            end
            lines[#lines + 1] = 'local run, message = loadstring(sources.Bootstrap, "@Astral/Bootstrap"); assert(run, message); return run(sources)'
            if type(isfolder)=="function"and type(makefolder)=="function"and not isfolder(Identity.Root)then makefolder(Identity.Root)end
            writefile(Identity.ReloadFile, table.concat(lines, "\n"))
            assert(type(readfile(Identity.ReloadFile)) == "string")
        end)
        if success then reloadPath = Identity.ReloadFile end
    end
    local chunk, message = loadstring(sources.Main, "@Astral/Main")
    assert(chunk, message)
    setfenv(chunk,environment)
    return chunk(requireModule, reloadPath, registerCleanup)
end, function(message)
    if debug and debug.traceback then return debug.traceback(tostring(message), 2) end
    return tostring(message)
end)
app.Starting = false
if not ok then
    if cleanup then pcall(cleanup) end
    app.Running = false
    warn("astral initialization failed: " .. tostring(result))
    return nil, result
end
return result

