sources.AimSupport = [========[
local Aim = {}
function Aim.camera(world)
    local camera = world.CurrentCamera
    if camera and camera:IsA("Camera") then return camera end
end
function Aim.root(character)
    if not character then return end
    for _, name in ipairs({"realHrp", "saviHRP", "HumanoidRootPart"}) do
        local root = character:FindFirstChild(name)
        if root and root:IsA("BasePart") then return root end
    end
end
function Aim.character(player)
    local character = player and player.Character
    if not character or not character.Parent then return end
    local root, humanoid = Aim.root(character), character:FindFirstChildOfClass("Humanoid")
    if root and humanoid and humanoid.Health > 0 then return character, root, humanoid end
end
function Aim.point(camera, input, mobile)
    if mobile then return camera.ViewportSize / 2 end
    return input:GetMouseLocation()
end
function Aim.alpha(value, dt)
    value = math.clamp(value, 0, 1)
    dt = type(dt) == "number" and dt == dt and math.clamp(dt, 0, 1) or 1 / 60
    return 1 - (1 - value) ^ (dt * 60)
end
function Aim.look(camera, position, alpha)
    local delta = position - camera.CFrame.Position
    local distance = delta.Magnitude
    if distance ~= distance or distance < 0.001 or distance == math.huge then return false end
    camera.CFrame = camera.CFrame:Lerp(CFrame.new(camera.CFrame.Position, position), alpha or 1)
    return true
end
function Aim.key(value)
    if not value or value == "None" or value == "Unknown" then return end
    local mouse = {MB1 = "MouseButton1", MB2 = "MouseButton2", MB3 = "MouseButton3"}
    local ok, key = pcall(function() return mouse[value] and Enum.UserInputType[mouse[value]] or Enum.KeyCode[value] end)
    if ok then return key end
end
function Aim.matches(input, key)
    return key ~= nil and (input.KeyCode == key or input.UserInputType == key)
end
function Aim.includeParams(original, character)
    local params = RaycastParams.new()
    if original then
        for _, key in ipairs({"IgnoreWater", "CollisionGroup", "RespectCanCollide", "BruteForceAllSlow"}) do
            pcall(function() params[key] = original[key] end)
        end
    end
    params.FilterType, params.FilterDescendantsInstances = Enum.RaycastFilterType.Include, {character}
    return params
end
function Aim.isCameraRay(camera, origin, direction)
    if not camera or typeof(origin) ~= "Vector3" or typeof(direction) ~= "Vector3" then return false end
    local length = direction.Magnitude
    return length == length and length > 0.001 and length < math.huge
        and (origin - camera.CFrame.Position).Magnitude < 0.1
        and direction.Unit:Dot(camera.CFrame.LookVector) > 0.999
end
return Aim

