sources.AppIdentity = [========[
-- Astral owns its runtime state and storage. Legacy folders are not scanned.
local Identity={Name="Astral",Root="Astral",ConfigFolder="Astral/FTAP",ThemeFolder="Astral",
    ReloadFile="Astral/reload.lua",RuntimeKey="AstralRuntime",UIKey="AstralUI"}
function Identity.Runtime(host)
    assert(type(host)=="table","Astral runtime environment is unavailable")
    local state=rawget(host,Identity.RuntimeKey)
    if type(state)~="table"then state={};host[Identity.RuntimeKey]=state end
    return state
end
function Identity.RetireLegacyAstral(host)
    local old=rawget(host,"Library")
    -- This marker is installed by Astral's own FunIcon module and does not
    -- exist in the supplied original UI. Never clear flags by name alone.
    if type(old)~="table"or type(rawget(old,"AstralFunIcon"))~="table"or type(old.Unload)~="function"then return false end
    local ok=pcall(old.Unload,old)
    if not ok or old.Unloaded~=true then return false end
    host.ResonanceRunning=nil;host.ResonanceStarting=nil
    if rawget(host,"Library")==old then host.Library=nil end
    return true
end
function Identity.Environment(host,state)
    local base=getfenv(0)
    local environment=setmetatable({AstralRuntime=state,_G={},shared={}},{__index=function(_,key)
        local value=host[key];if value~=nil then return value end
        return base[key]
    end})
    environment.getgenv=function()return environment end
    return environment
end
return Identity

