sources.FunIcon = [========[
-- Resolution-independent outline matching the dancing pose, 24x24 viewbox.
local Icon={}
local function draw(image)
    local old=image:FindFirstChild("AstralFunGlyph")
    if old then old:Destroy() end
    local canvas=Instance.new("Frame")
    canvas.Name="AstralFunGlyph";canvas.BackgroundTransparency=1
    canvas.AnchorPoint=Vector2.new(.5,.5);canvas.Position=UDim2.fromScale(.5,.5)
    canvas.Size=UDim2.fromScale(1,1);canvas.Parent=image
    local aspect=Instance.new("UIAspectRatioConstraint");aspect.AspectRatio=1
    aspect.DominantAxis=Enum.DominantAxis.Height;aspect.Parent=canvas
    local lines={}
    local function line(x1,y1,x2,y2)
        local dx,dy=x2-x1,y2-y1
        local f=Instance.new("Frame");f.BorderSizePixel=0
        f.AnchorPoint=Vector2.new(.5,.5);f.Position=UDim2.fromScale((x1+x2)/48,(y1+y2)/48)
        f.Size=UDim2.fromScale(math.sqrt(dx*dx+dy*dy)/24,1.35/24)
        f.Rotation=math.deg(math.atan2(dy,dx));f.Parent=canvas
        local corner=Instance.new("UICorner");corner.CornerRadius=UDim.new(1,0);corner.Parent=f
        lines[#lines+1]=f
    end
    local x,y=17,2
    local function curve(ax,ay,bx,by,cx,cy)
        local sx,sy=x,y
        for i=1,5 do
            local t=i/5;local u=1-t
            local nx=u*u*u*sx+3*u*u*t*ax+3*u*t*t*bx+t*t*t*cx
            local ny=u*u*u*sy+3*u*u*t*ay+3*u*t*t*by+t*t*t*cy
            line(x,y,nx,ny);x,y=nx,ny
        end
    end
    local function to(nx,ny) line(x,y,nx,ny);x,y=nx,ny end
    curve(18.2,2,18.4,2.8,18.1,4)
    curve(17.5,7,16.4,8.9,14.6,10);to(14.6,13);to(17.2,14)
    curve(18.8,14.7,19.1,15.9,18.2,17.5);to(17.1,19.3)
    curve(16.3,20.6,14.9,19.8,15.5,18.6);to(16.3,16.8);to(13.1,15.6);to(10.1,21.6)
    curve(9.4,23,7.9,22.3,8.4,21);to(10.9,14.7);to(10.1,11.8)
    curve(8.5,12.8,7.1,13.2,5.7,13.5);curve(4.1,13.7,3.9,12.2,5.2,11.8)
    curve(7.2,11.2,8.5,10.4,9.5,9.6);curve(10.8,8.7,12.5,8.7,13.5,7.7)
    curve(15.2,6,15.9,4.2,16,2.8);curve(16.1,2.1,16.5,2,17,2)
    for i=0,19 do
        local a,b=i*math.pi/10,(i+1)*math.pi/10
        line(11.4+2*math.cos(a),5.4+2*math.sin(a),11.4+2*math.cos(b),5.4+2*math.sin(b))
    end
    local function update()
        for _,f in ipairs(lines) do
            f.BackgroundColor3=image.ImageColor3
            f.BackgroundTransparency=image.ImageTransparency
        end
    end
    local c1=image:GetPropertyChangedSignal("ImageColor3"):Connect(update)
    local c2=image:GetPropertyChangedSignal("ImageTransparency"):Connect(update)
    canvas.Destroying:Connect(function() c1:Disconnect();c2:Disconnect() end)
    update()
end
function Icon.Install(library)
    library.AstralFunIcon={Url="",ImageRectOffset=Vector2.zero,ImageRectSize=Vector2.zero,Draw=draw}
    return true
end
return Icon

