sources.Drone = [========[
local requireModule=...
local Flight=requireModule("RocketFlight")
local Drone={}
function Drone.Install(context)
    local Players=game:GetService("Players")
    context=context or {};context.Player=Players.LocalPlayer;context.Input=game:GetService("UserInputService")
    context.RunService=game:GetService("RunService");context.Workspace=workspace;context.Mouse=context.Player:GetMouse()
    context.Controls=function()
        local scripts=context.Player:FindFirstChild("PlayerScripts");local module=scripts and scripts:FindFirstChild("PlayerModule")
        local ok,controls=pcall(function()return module and require(module):GetControls()end)
        return ok and controls or nil
    end
    local controller=Flight.Install(context)
    -- Keep the former API IDs so configs and existing GUI bindings still work.
    return {Config=controller.Config,Start=function(v)return controller:Start(v)end,
        SetEnabled=function(v)controller:SetEnabled(v)end,Stop=function()controller:Stop("Exited")end,
        AttachUnderMouse=function()controller:AttachUnderMouse()end,SpawnControlled=function()controller:SpawnControlled()end,
        SetVisual=function(v)controller:SetVisual(v)end,GetStatus=function()return controller:GetStatus()end,
        IsActive=function()return controller.Session~=nil end,Shutdown=function()controller:Shutdown()end,Controller=controller}
end
return Drone

