sources.AntiKickItems = [========[
local Items = {}
Items.__index = Items
Items.Definitions = {
    Shuriken = {Id = "NinjaShuriken", Place = "Back"},
    Katana = {Id = "NinjaKatana", Place = "Back"},
    Pickaxe = {Id = "ToolPickaxe", Place = "Hand"},
    Pencil = {Id = "ToolPencil", Place = "Hand"},
    Kunai = {Id = "NinjaKunai", Place = "Back"},
    Cleaver = {Id = "ToolCleaver", Place = "Hand"},
    ["Rusty Fork"] = {Id = "ToolDiggingForkRusty", Place = "Hand"},
}
function Items:Choices()
    local names={"Shuriken","Katana","Kunai","Cleaver","Rusty Fork","Pencil","Pickaxe"}
    for name in pairs(self.Definitions)do if not table.find(names,name)then names[#names+1]=name end end
    names[#names+1]="Other Sticky Toy";return names
end
function Items:Discover(roots,catalog)
    local scanned=0
    for _,root in ipairs(roots)do
        if not root then continue end
        for _,model in ipairs(root:GetDescendants())do
            scanned+=1;if scanned>12000 then return end
            if model:IsA("Model")then
                local part=model:FindFirstChild("StickyPart")
                local weld=part and part:FindFirstChild("StickyWeld")
                if part and part:IsA("BasePart") and weld and weld:IsA("WeldConstraint")and model.Name:match("^[%w_]+$")and (not catalog or catalog[model.Name])then
                    local known=false;for _,definition in pairs(self.Definitions)do if definition.Id==model.Name then known=true;break end end
                    if not known then self.Definitions[model.Name]={Id=model.Name,Place="Back"}end
                end
            end
        end
    end
end
function Items.Install(context)
    return setmetatable({Context=context,Selected="Shuriken",Placement="Auto",CustomId="NinjaShuriken",Generation=0,Rotation={X=0,Y=0,Z=0},PoseDirty=false,NextPose=0,NextOwn=0,GuardEnabled=true},Items)
end
function Items:Select(name)
    if name=="Digging Fork"then name="Rusty Fork"end
    if not self.Definitions[name] and name~="Other Sticky Toy" then return false end
    if self.Selected==name then return true end
    self.Selected=name;self.Generation+=1
    self.ActiveModel,self.StickyPart,self.Target=nil,nil,nil
    if self.Context.Changed then self.Context.Changed() end
    return true
end
function Items:SetPlacement(value)
    if value~="Auto" and value~="Back" and value~="Hand" then return false end
    if value~=self.Placement then self.Placement=value;self.Generation+=1;self.ActiveModel,self.StickyPart,self.Target=nil,nil,nil;if self.Context.Changed then self.Context.Changed() end end
    return true
end
function Items:SetRotation(axis,value)
    if not self.Rotation[axis] or type(value)~="number" or value~=value or math.abs(value)==math.huge then return false end
    value=math.clamp(value,-180,180)
    if self.Rotation[axis]~=value then
        self.Rotation[axis]=value;self.PoseDirty=true;self.RemoteDirty=true
        self:Update((self.Context.Clock or os.clock)())
    end
    return true
end
function Items:Update(now)
    if self.Closed or not self.Context.Enabled() then return end
    local def=self.Definitions[self.Selected]
    local hand=self.Placement=="Hand" or self.Placement=="Auto" and def and def.Place=="Hand"
    local part,target=self.StickyPart,self.Target
    local weld=part and part.Parent and part:FindFirstChild("StickyWeld")
    if not (self.ActiveModel and self.ActiveModel.Parent and target and target.Parent and weld) then return end
    local character=self.Context.Character()
    if not character or not target:IsDescendantOf(character) then return end
    local owns=self.Context.IsPhysicsOwner or self.Context.IsOwner
    local owned=not owns or owns(part)
    if weld.Part1~=target then
        self.PoseDirty,self.RemoteDirty=true,true
        if not self.GuardEnabled then return end
        if owned and now>=self.NextPose then
            self.NextPose=now+.1
            pcall(self.Context.ApplyOffset,part,target,self:Offset(target))
        elseif not owned and not self.Acquiring and now>=self.NextOwn then
            self.Acquiring=true;self.NextOwn=now+.5
            local version,model=self.Generation,self.ActiveModel
            local function valid()
                return not self.Closed and self.GuardEnabled and self.Context.Enabled() and self.Generation==version
                    and self.ActiveModel==model and model.Parent and part.Parent and target.Parent
                    and self.Context.Character()==character and target:IsDescendantOf(character)
            end
            (self.Context.SpawnThread or task.spawn)(function()
                if valid() then pcall(self.Context.Own,part,valid) end
                self.Acquiring=false
            end)
        end
        return
    end
    if not owned or not self.PoseDirty and not self.RemoteDirty and not hand then return end
    local offset=self:Offset(target)
    if self.PoseDirty or hand then
        local desired=target.CFrame*offset
        -- CFrame on a welded part would move the character's entire assembly.
        -- Position/Orientation recalculate the weld offsets without moving it.
        self.LocalFrames=self.LocalFrames or {}
        if not next(self.LocalFrames) then
            for _,piece in ipairs(self.ActiveModel:GetDescendants()) do
                if piece:IsA("BasePart") then self.LocalFrames[piece]=part.CFrame:ToObjectSpace(piece.CFrame) end
            end
        end
        for piece,relative in pairs(self.LocalFrames) do
            if piece.Parent and piece:IsDescendantOf(self.ActiveModel) then
                local pose=desired*relative
                local x,y,z=pose:ToOrientation()
                piece.Orientation=Vector3.new(math.deg(x),math.deg(y),math.deg(z))
                piece.Position=pose.Position
            end
        end
        self.PoseDirty=false
    end
    -- Preview is immediate; server attachment updates remain bounded.
    if (self.RemoteDirty or hand) and now>=self.NextPose then
        self.NextPose=now+.1
        if pcall(self.Context.ApplyOffset,part,target,offset) then self.RemoteDirty=false end
    end
end
function Items:SetCustomId(value)
    value=tostring(value or ""):match("^%s*(.-)%s*$")
    if not value:match("^[%w_]+$") or #value>80 then return false end
    if self.CustomId~=value then self.CustomId=value;self.Generation+=1;if self.Context.Changed then self.Context.Changed() end end
    return true
end
function Items:Spawn(anchor)
    local version=self.Generation
    local definition=self.Definitions[self.Selected]
    local id=definition and definition.Id or self.CustomId
    local model=self.Context.Spawn(id,anchor.CFrame+Vector3.new(0,15,0))
    local part=model and model:WaitForChild("StickyPart",1.5)
    local weld=part and part:WaitForChild("StickyWeld",1.5)
    if self.Closed or version~=self.Generation or not self.Context.Enabled() then self.Context.Destroy(model);return end
    if not (part and part:IsA("BasePart") and weld and weld:IsA("WeldConstraint")) then
        self.Context.Destroy(model)
        if self.Selected~="Shuriken" then
            self.Context.Notify(id.." has no supported StickyPart/StickyWeld. Reverting to Shuriken.")
            self:Select("Shuriken")
            if self.Context.SetSelection then self.Context.SetSelection("Shuriken") end
        end
        return
    end
    if not self.Context.Own(part) or self.Closed or version~=self.Generation or not self.Context.Enabled() then self.Context.Destroy(model);return end
    self.ActiveModel,self.StickyPart=model,part
    self.LocalFrames={};self.HoldLocal=nil
    local hold=model:FindFirstChild("HoldPart",true)
    if hold and hold:IsA("BasePart") then self.HoldLocal=part.CFrame:ToObjectSpace(hold.CFrame) end
    for _,piece in ipairs(model:GetDescendants()) do
        if piece:IsA("BasePart") then self.LocalFrames[piece]=part.CFrame:ToObjectSpace(piece.CFrame) end
    end
    self.PoseDirty=true;self.RemoteDirty=true
    return model,part,weld
end
function Items:Attach(target,timeout)
    local part,model=self.StickyPart,self.ActiveModel
    local weld=part and part:FindFirstChild("StickyWeld")
    if not (model and model.Parent and target and target.Parent and weld)then return false end
    self.Target=target
    local version=self.Generation;local clock=self.Context.Clock or os.clock
    local deadline=clock()+(timeout or .5);local nextSend=0
    repeat
        if self.Closed or version~=self.Generation or not self.Context.Enabled()or not model.Parent or not target.Parent then return false end
        if weld.Part1==target or weld.Part0==target then self.PoseDirty=true;self.RemoteDirty=true;return true end
        if clock()>=nextSend then
            nextSend=clock()+.15
            -- Establish the original short attachment first. Long tool/hand
            -- offsets are applied only after the real weld acknowledges it.
            pcall(self.Context.ApplyOffset,part,target,CFrame.new(0,-.3,0)*CFrame.Angles(math.pi/2,0,0))
        end
        (self.Context.Wait or task.wait)(.03)
    until clock()>=deadline
    self.Context.Destroy(model);self.ActiveModel,self.StickyPart=nil,nil
    if self.Selected~="Shuriken"then
        self.Context.Notify(self.Selected.." attachment was not acknowledged. Reverting to Shuriken.")
        self:Select("Shuriken");if self.Context.SetSelection then self.Context.SetSelection("Shuriken")end
    end
    return false
end
function Items:Offset(target)
    self.Target=target
    local rotation=CFrame.Angles(math.rad(self.Rotation.X),math.rad(self.Rotation.Y),math.rad(self.Rotation.Z))
    local place=self.Placement
    if place=="Auto" then local def=self.Definitions[self.Selected];place=def and def.Place or "Back" end
    if self.Selected=="Shuriken" and self.Placement=="Auto" then
        return CFrame.new(0,-.3,0)*CFrame.Angles(math.pi/2,0,0)*rotation
    end
    local character=self.Context.Character()
    local body=character and (place=="Hand" and (character:FindFirstChild("RightHand") or character:FindFirstChild("Right Arm"))
        or character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso"))
    local pose=place=="Hand" and CFrame.new(0,-.8,-.2)*CFrame.Angles(0,0,math.rad(-15))
        or CFrame.new(0,0,.75)*CFrame.Angles(0,0,math.rad(-35))
    -- Keep the original protected hitbox as the actual server weld target.
    -- The transform changes the visible position, never the protection target.
    if body then
        local desired=body.CFrame*pose*rotation
        local hold=self.ActiveModel and self.ActiveModel.Parent and self.ActiveModel:FindFirstChild("HoldPart",true)
        if place=="Hand" and hold and hold:IsA("BasePart") and self.StickyPart and self.StickyPart.Parent then
            self.HoldLocal=self.HoldLocal or self.StickyPart.CFrame:ToObjectSpace(hold.CFrame)
            desired=desired*self.HoldLocal:Inverse()
        end
        return target.CFrame:ToObjectSpace(desired)
    end
    return pose*rotation
end
function Items:Dispose()
    self.Closed=true;self.Generation+=1
    if self.Context.Changed then self.Context.Changed() end
    self.ActiveModel,self.StickyPart=nil,nil
end
return Items

