sources.SparklerForms = [========[
-- Free-toy body-attached formations. Independent from CoconutForms / ToyRig.
local requireModule=...
local Layouts=requireModule("FigureLayouts")
local Formation=requireModule("FormationRig")
local Forms={};Forms.__index=Forms
Forms.Counts=Layouts.Counts;Forms.Names=Layouts.Names;Forms.Items=Layouts.Items;Forms.Materials=Layouts.Materials
Forms.Segments=Layouts.Segments
Forms.Measure=Layouts.Measure
Forms.RodFrame=Layouts.Frame
function Forms.Install(context)
    local self=setmetatable({Context=context,Pool=Formation.new(context,Layouts.Measure),Enabled=false,Form="Wings",Item="FireworkSparkler",Material="Selected Item",Models={},Phase=0,Speed=1.4,MotionSpeed=1},Forms)
    self:Configure()
    self.Connection=context.RunService.PreSimulation:Connect(function(dt)
        local ok,message=pcall(self.Step,self,dt)
        if not ok then self:SetEnabled(false);self.Status="Formation: "..tostring(message)end
    end)
    return self
end
function Forms:Configure()self.Pool:Configure(Layouts.Plan(self.Form,self.Item,self.Material))end
function Forms:GoalCount()return self.Counts[self.Form]end
function Forms:Clear()self.Pool:Clear();self.Models={};self.ReferenceLength=nil;self.LastPosition=nil end
function Forms:SetEnabled(value)
    value=value==true and not self.Closed;if self.Enabled==value then return end
    self.Enabled=value;self.Pool.Active=value;self:Clear();self.CharacterModel=nil
    self.Status=value and "Preparing free toys for body attachments"or "Disabled"
end
function Forms:SetForm(value)
    if not self.Counts[value]then return false end
    if self.Form~=value then self.Form=value;self:Configure();self.Pool:Retry()end;return true
end
function Forms:SetItem(value)
    if not table.find(self.Items,value)then return false end
    if self.Item~=value then self.Item=value;self:Configure();self.Pool:Retry()end;return true
end
function Forms:SetMaterial(value)
    if not table.find(self.Materials,value)then return false end
    if self.Material~=value then self.Material=value;self:Configure();self.Pool:Retry()end;return true
end
function Forms:SetGuard(value)self.Pool.Guard=value==true end
function Forms:Retry()self.Pool:Retry()end
function Forms:Rebuild()self:Clear();self.Pool:Retry()end
function Forms:Step(dt)
    if not self.Enabled or self.Closed then return end
    local c,root,h=self.Context.Character()
    if not root or not h or h.Health<=0 then
        if self.CharacterModel then self:Clear();self.CharacterModel=nil end
        self.Status="Waiting for character";return
    end
    if self.CharacterModel and self.CharacterModel~=c or self.LastPosition and (root.Position-self.LastPosition).Magnitude>40 then self:Clear()end
    self.CharacterModel=c;self.LastPosition=root.Position
    local anchor=c:FindFirstChild("UpperTorso")or c:FindFirstChild("Torso")or root
    self.Pool:Update(anchor);self.Models={};local slots={};local total=0
    for i=1,self:GoalCount()do local item=self.Pool.Slots[i];if item then self.Models[#self.Models+1]=item;slots[#slots+1]=i;total+=item.Geometry.Length end end
    self.ReferenceLength=#self.Models>0 and total/#self.Models or nil
    dt=math.clamp(dt or 1/60,0,.05);local flight=self.Context.Flying and self.Context.Flying()or false
    self.Speed+=((flight and 7.5 or 3.8)-self.Speed)*math.min(dt*5,1);self.Phase+=dt*self.Speed*math.clamp(self.MotionSpeed,0,3)
    local segments=self.ReferenceLength and Layouts.Segments(self.Form,self.ReferenceLength,self.Phase,flight,self.Form=="Wings"and math.max(2,#self.Models)or nil)
    local contested=0;local reason
    for i,item in ipairs(self.Models)do local segment=segments and segments[self.Form=="Wings"and i or slots[i]]
        if segment then local cf=Layouts.Frame(segment,item.Geometry.Axis)
            if cf then local ok,message=self.Pool:Move(slots[i],cf);if not ok then contested+=1;reason=message end end
        end
    end
    self.Status=#self.Models.."/"..self:GoalCount().." real toys | "..(contested>0 and ("recovering "..contested.." · "..tostring(reason))or self.Pool.Status)
end
function Forms:Dispose()if self.Closed then return end;self.Closed=true;self.Enabled=false;self.Pool:Dispose();self.Models={};self.Connection:Disconnect()end
return Forms

