sources.FigureLayouts = [========[
-- Fixed-length geometry for real toy formations. No resizing or local toy copies.
local Layouts={};Layouts.__index=Layouts
Layouts.Counts={Wings=12,Halo=12,Star=5,Spiral=12,["Orbit Ring"]=8,Crown=8}
local axes={Vector3.xAxis,Vector3.yAxis,Vector3.zAxis}
function Layouts.Segments(form,length,phase,flight,count)
    local result={}
    local function add(a,b) result[#result+1]={A=a,B=b} end
    if form=="Wings" then
        count=math.max(2,count or 12)
        local feathers=math.floor(count/2)
        local flap=-.2+math.sin(phase)*(flight and .7 or .5)+math.sin(phase*2-.6)*.08
        for i=0,feathers-1 do
            for _,side in ipairs({-1,1}) do
                local t=i/math.max(1,feathers-1)
                local hinge=CFrame.new(0,.5,.65)*CFrame.Angles(-.08,side*(.15+math.cos(phase)*.12),side*flap)
                local ripple=math.sin(phase-t*.9)*(flight and .22 or .12)
                local angle=math.rad(40-t*60)+ripple
                local base=Vector3.new(side*(.4+t*length*.9),-t*length*.25,.2*t)
                local direction=Vector3.new(side*math.cos(angle),math.sin(angle),.08*t).Unit
                add(hinge*base,hinge*(base+direction*length))
            end
        end
        if count%2==1 then add(Vector3.new(0,.5-length/2,.7),Vector3.new(0,.5+length/2,.7)) end
    elseif form=="Orbit Ring" then
        local n=8;local radius=length/(2*math.sin(math.pi/n))
        local rotation=CFrame.new(0,1,.6)*CFrame.Angles(.65,phase*.55,.35)
        for i=0,n-1 do
            local a,b=i*2*math.pi/n,(i+1)*2*math.pi/n
            add(rotation*Vector3.new(radius*math.cos(a),0,radius*math.sin(a)),
                rotation*Vector3.new(radius*math.cos(b),0,radius*math.sin(b)))
        end
    elseif form=="Crown" then
        local n=8;local radius=length*.65
        local rise=math.sqrt(length*length-(2*radius*math.sin(math.pi/n))^2)
        local rotation=CFrame.new(0,2.2+math.sin(phase*.7)*.12,0)*CFrame.Angles(0,phase*.15,0)
        for i=0,n-1 do
            local a,b=i*2*math.pi/n,(i+1)*2*math.pi/n
            add(rotation*Vector3.new(radius*math.cos(a),(i%2)*rise,radius*math.sin(a)),
                rotation*Vector3.new(radius*math.cos(b),((i+1)%2)*rise,radius*math.sin(b)))
        end
    elseif form=="Halo" then
        local n=12;local radius=length/(2*math.sin(math.pi/n))
        for i=0,n-1 do
            local a,b=i*2*math.pi/n,(i+1)*2*math.pi/n
            add(Vector3.new(radius*math.cos(a),3.2,radius*math.sin(a)),Vector3.new(radius*math.cos(b),3.2,radius*math.sin(b)))
        end
    elseif form=="Star" then
        -- Five full-length native rods form a complete pentagram.
        local radius=length/(2*math.sin(2*math.pi/5))
        local points={}
        for i=0,4 do
            local angle=math.pi/2+i*4*math.pi/5
            points[#points+1]=Vector3.new(radius*math.cos(angle),.6+radius*math.sin(angle),.9)
        end
        for i=1,5 do add(points[i],points[i%5+1]) end
    elseif form=="Spiral" then
        local rise=length*.22;local step=math.pi/3
        local radius=math.sqrt(length*length-rise*rise)/(2*math.sin(step/2))
        for i=0,11 do
            add(Vector3.new(radius*math.cos(i*step),(i-6)*rise,.6+radius*math.sin(i*step)),
                Vector3.new(radius*math.cos((i+1)*step),(i+1-6)*rise,.6+radius*math.sin((i+1)*step)))
        end
    end
    return result
end
local legacySegments=Layouts.Segments
Layouts.Names={"Wings","Halo","Star","Spiral","Orbit Ring","Crown","Butterfly","Dragonfly","Scorpion Tail","DNA Helix","Atom","Saturn","Ferris Wheel","Radar Dish","Trident","Bloom","Cube Cage","Shield","Turbine","Solar System"}
local extra={Butterfly=10,Dragonfly=6,["Scorpion Tail"]=10,["DNA Helix"]=12,Atom=12,Saturn=10,["Ferris Wheel"]=12,["Radar Dish"]=9,Trident=9,Bloom=12,["Cube Cage"]=12,Shield=9,Turbine=10,["Solar System"]=9}
for k,v in pairs(extra)do Layouts.Counts[k]=v end
Layouts.Items={"FireworkSparkler","ToolPencil","NinjaKunai","NinjaKatana","NinjaShuriken","BallMagicLight","BallBasketball","AnvilGray","PalletLightBrown","LadderLightBrown"}
Layouts.Materials={"Selected Item","Neon Constellation","Samurai Array","Workshop"}
function Layouts.Plan(form,item,material)
    local kits={["Neon Constellation"]={"FireworkSparkler","BallMagicLight","BallBasketball"},["Samurai Array"]={"NinjaKatana","NinjaKunai","NinjaShuriken"},Workshop={"ToolPencil","PalletLightBrown","LadderLightBrown","AnvilGray"}}
    local kit=kits[material]or {item};local plan={}
    for i=1,Layouts.Counts[form]do plan[i]=kit[(i-1)%#kit+1]end;return plan
end
function Layouts.Segments(form,L,t,flight,count)
    if not extra[form]then return legacySegments(form,L,t,flight,count)end
    local list={}
    local function add(a,b)list[#list+1]={A=a,B=b}end
    local function ray(a,d)add(a,a+d.Unit*L)end
    local function ring(n,frame)
        local radius=L/(2*math.sin(math.pi/n))
        for i=0,n-1 do local a,b=i*math.pi*2/n,(i+1)*math.pi*2/n
            add(frame*Vector3.new(radius*math.cos(a),radius*math.sin(a),0),frame*Vector3.new(radius*math.cos(b),radius*math.sin(b),0))
        end
    end
    if form=="Butterfly"then
        for _,side in ipairs({-1,1})do
            local hinge=CFrame.new(side*.25,.3,1)*CFrame.Angles(0,side*math.sin(t*1.4)*.45,side*.15)
            for i=0,3 do
                local angle=math.rad(-65+i*43);local a=Vector3.new(side*.12,0,0)
                ray(hinge*a,hinge:VectorToWorldSpace(Vector3.new(side*math.cos(angle),math.sin(angle),.1)))
            end
        end
        ray(Vector3.new(0,-L*.7,1),Vector3.yAxis);ray(Vector3.new(0,L*.3,1),Vector3.yAxis)
    elseif form=="Dragonfly"then
        for _,side in ipairs({-1,1})do for _,front in ipairs({-1,1})do
            ray(Vector3.new(0,0,front*L*.22),Vector3.new(side,math.sin(t*5+front)*.3,front*.5))
        end end
        ray(Vector3.new(0,0,-L),Vector3.zAxis);ray(Vector3.zero,Vector3.zAxis)
    elseif form=="Scorpion Tail"then
        local p=Vector3.new(0,-1,1)
        for i=1,8 do local a=(i-1)*.36;local d=Vector3.new(math.sin(t*.7)*.12,math.sin(a),math.cos(a)).Unit;local q=p+d*L;add(p,q);p=q end
        for _,side in ipairs({-1,1})do ray(Vector3.new(side*.4,-1,-.6),Vector3.new(side,.2,-.5))end
    elseif form=="DNA Helix"then
        local r=L*.5;local rise=L/math.sqrt(2);local frame=CFrame.new(0,-rise*2,1.5)*CFrame.Angles(0,t*.35,0)
        for _,offset in ipairs({0,math.pi})do for i=0,3 do local a=i*math.pi/2+offset;local b=a+math.pi/2
            add(frame*Vector3.new(r*math.cos(a),i*rise,r*math.sin(a)),frame*Vector3.new(r*math.cos(b),(i+1)*rise,r*math.sin(b)))
        end end
        for i=0,3 do local a=i*math.pi/2;add(frame*Vector3.new(r*math.cos(a),i*rise,r*math.sin(a)),frame*Vector3.new(-r*math.cos(a),i*rise,-r*math.sin(a)))end
    elseif form=="Atom"then
        for i=0,2 do ring(4,CFrame.new(0,1,1)*CFrame.Angles(i*math.pi/3,t*.2+i*math.pi/3,i*.5))end
    elseif form=="Saturn"then
        ring(8,CFrame.new(0,1,1)*CFrame.Angles(.6,t*.25,.35))
        ray(Vector3.new(-L/2,1,1),Vector3.xAxis);ray(Vector3.new(0,1-L/2,1),Vector3.yAxis)
    elseif form=="Ferris Wheel"then
        local cf=CFrame.new(0,1,1.5)*CFrame.Angles(0,0,t*.35);ring(6,cf)
        for i=0,5 do local a=i*math.pi/3;ray(cf.Position,cf:VectorToWorldSpace(Vector3.new(math.cos(a),math.sin(a),0)))end
    elseif form=="Radar Dish"then
        for i=0,7 do local a=i*math.pi/4;ray(Vector3.new(0,0,1.5),Vector3.new(math.cos(a),math.sin(a),.6))end
        ray(Vector3.new(0,0,1.5),-Vector3.zAxis)
    elseif form=="Trident"then
        for i=0,2 do ray(Vector3.new(0,(i-2)*L,1.5),Vector3.yAxis)end
        for _,side in ipairs({-1,1})do
            ray(Vector3.new(0,L*.5,1.5),Vector3.new(side,0,0));ray(Vector3.new(side*L,L*.5,1.5),Vector3.yAxis)
        end
        ray(Vector3.new(0,L,1.5),Vector3.yAxis);ray(Vector3.new(-L*.5,L*.5,1.5),Vector3.xAxis)
    elseif form=="Bloom"then
        local center=Vector3.new(0,.5,1.5)
        for i=0,3 do local a=i*math.pi/2+t*.15;local b=center+Vector3.new(math.cos(a),math.sin(a),0)*L
            local c=center+Vector3.new(math.cos(a+math.pi/3),math.sin(a+math.pi/3),0)*L
            add(center,b);add(b,c);add(c,center)
        end
    elseif form=="Cube Cage"then
        local cf=CFrame.new(0,.5,2)*CFrame.Angles(t*.13,t*.23,0)
        for axis=1,3 do for _,a in ipairs({-1,1})do for _,b in ipairs({-1,1})do
            local v1,v2
            if axis==1 then v1,v2=Vector3.new(-1,a,b),Vector3.new(1,a,b)
            elseif axis==2 then v1,v2=Vector3.new(a,-1,b),Vector3.new(a,1,b)
            else v1,v2=Vector3.new(a,b,-1),Vector3.new(a,b,1)end
            add(cf*(v1*L*.5),cf*(v2*L*.5))
        end end end
    elseif form=="Shield"then
        local cf=CFrame.new(0,.6,-2.5)*CFrame.Angles(0,math.sin(t*.3)*.15,0);ring(6,cf)
        for i=0,2 do local a=i*math.pi*2/3;ray(cf.Position,cf:VectorToWorldSpace(Vector3.new(math.cos(a),math.sin(a),0)))end
    elseif form=="Turbine"then
        local cf=CFrame.new(0,1,1.5)*CFrame.Angles(0,0,t*.7)
        for i=0,4 do local a=i*math.pi*2/5;local start=cf*Vector3.new(math.cos(a)*L*.25,math.sin(a)*L*.25,0)
            local d=cf:VectorToWorldSpace(Vector3.new(math.cos(a+.5),math.sin(a+.5),.35));local tip=start+d.Unit*L
            add(start,tip);ray(tip,cf:VectorToWorldSpace(Vector3.new(-math.sin(a),math.cos(a),.2)))
        end
    elseif form=="Solar System"then
        ray(Vector3.new(0,1-L*.5,1.5),Vector3.yAxis)
        for i=1,8 do local r=L*(.7+(i%3)*.45);local a=t*(.25+.05*(i%3))+i*2.4;local center=Vector3.new(math.cos(a)*r,1+math.sin(a*.7+i)*L*.4,1.5+math.sin(a)*r)
            ray(center-Vector3.yAxis*L*.5,Vector3.yAxis)
        end
    end
    return list
end
function Layouts.Measure(model,root)
    local best,axis,length,score
    for _,p in ipairs(model:GetDescendants())do
        if p:IsA("BasePart")and p.Name~="SoundPart"and p.Name~="HoldPart"and p.Name~="PartHitDetector"and p.Transparency<.95 then
            local dims={p.Size.X,p.Size.Y,p.Size.Z};local a=1;for i=2,3 do if dims[i]>dims[a]then a=i end end
            local s=dims[a];if s>.05 and (not score or s>score)then best,axis,length,score=p,a,s,s end
        end
    end
    if not best then local ok,cf,size=pcall(model.GetBoundingBox,model);if not ok then return end
        local dims={size.X,size.Y,size.Z};axis=1;for i=2,3 do if dims[i]>dims[axis]then axis=i end end
        return {Axis=axis,Length=dims[axis],RootToGeometry=root.CFrame:ToObjectSpace(cf)}
    end
    return {Axis=axis,Length=length,RootToGeometry=root.CFrame:ToObjectSpace(best.CFrame)}
end
function Layouts.Frame(segment,axis)
    local d=segment.B-segment.A;if d.Magnitude<.001 then return end
    local up=math.abs(d.Unit.Z)>.98 and Vector3.yAxis or Vector3.zAxis
    return CFrame.lookAt((segment.A+segment.B)*.5,(segment.A+segment.B)*.5+d,up)*(axis==1 and CFrame.Angles(0,math.pi/2,0)or axis==2 and CFrame.Angles(-math.pi/2,0,0)or CFrame.Angles(0,math.pi,0))
end
return Layouts

