sources.FormationRig = [========[
-- Independent toy formations with a guarded release for newly held items.
-- Foreign grabs suspend a slot; guarded repair replaces
-- only our own spawned toy, with bounded retries and real server removals.
local Formation={};Formation.__index=Formation
local forces={BodyPosition=true,BodyGyro=true,BodyVelocity=true,BodyAngularVelocity=true,BodyForce=true,BodyThrust=true,
    AlignPosition=true,AlignOrientation=true,LinearVelocity=true,AngularVelocity=true,VectorForce=true,Torque=true}
local function alive(v)return v and v.Parent~=nil end
local function finite(n)return type(n)=="number"and n==n and math.abs(n)<math.huge end
local function rootsOf(model)
    if not alive(model)then return nil,"removed"end
    local roots,parts,seen={},{},{}
    for _,p in ipairs(model:GetDescendants())do
        if p:IsA("BasePart")then
            local root=p.AssemblyRootPart or p
            if root.Anchored then return nil,"anchored"end
            if not root:IsDescendantOf(model)then return nil,"grabbed"end
            parts[#parts+1]=p;if not seen[root]then seen[root]=true;roots[#roots+1]=root end
        elseif p:IsA("RigidConstraint")and p.Enabled~=false then
            for i=0,1 do local a;if i==0 then a=p.Attachment0 else a=p.Attachment1 end
                if a and a.Parent and a.Parent:IsA("BasePart")and not a.Parent:IsDescendantOf(model)then return nil,"grabbed"end
            end
        end
    end
    if #roots==0 or #roots>16 then return nil,"streaming"end
    for _,root in ipairs(roots)do
        local ok,connected=pcall(root.GetConnectedParts,root,true)
        if ok then for _,p in ipairs(connected)do if not p:IsDescendantOf(model)then return nil,"grabbed"end end end
    end
    return roots,parts
end
local function rootOf(model)
    for _,name in ipairs({"Handle","SoundPart","HoldPart"})do local p=model:FindFirstChild(name,true);if p and p:IsA("BasePart")then return p end end
    for _,p in ipairs(model:GetDescendants())do if p:IsA("BasePart")and p.Name~="PartHitDetector"then return p end end
end
function Formation.new(context,measure)
    return setmetatable({Context=context,Measure=measure,Slots={},Plan={},Generation=0,NextSpawn=0,Guard=true,RecoveryDelay=.8,
        RepairTimes={},Deleting={},Failures=0,Losses=0,Lost={},Status="Disabled"},Formation)
end
function Formation:Mine(model)return model and (not self.Context.OwnToy or self.Context.OwnToy(model))end
function Formation:Delete(model)
    if alive(model)and self:Mine(model)and not self.Deleting[model]then self.Deleting[model]=true;pcall(self.Context.Destroy,model)end
end
function Formation:Suspend(item)
    for _,a in ipairs(item.Assemblies)do a.Position.Enabled=false;a.Rotation.Enabled=false end
end
function Formation:Remove(index,deleteToy)
    local item=self.Slots[index];self.Slots[index]=nil;if not item then return end
    self:Suspend(item)
    for _,v in ipairs(item.Created)do pcall(v.Destroy,v)end
    local free=rootsOf(item.Model)
    for _,saved in ipairs(item.Native)do
        if free and alive(saved.Parent)then pcall(function()saved.Value.Parent=saved.Parent end)else pcall(saved.Value.Destroy,saved.Value)end
    end
    for part,s in pairs(item.Properties)do if alive(part)then part.CanCollide=s[1];part.CanTouch=s[2];part.CanQuery=s[3]end end
    if deleteToy then self:Delete(item.Model)end
end
function Formation:Clear()
    self.Generation+=1
    for i in pairs(self.Slots)do self:Remove(i,true)end
    if self.Pending then self:Delete(self.Pending.Model);self.Pending=nil end
    self.Failures=0;self.Losses=0;self.Lost={};self.Paused=false;self.CharacterModel=nil;self.NextSpawn=0;self.LastError=nil
end
function Formation:Configure(plan)
    if self.Pending and plan[self.Pending.Index]~=self.Plan[self.Pending.Index]then self:Clear()end
    for i,item in pairs(self.Slots)do if not plan[i]or plan[i]~=item.Id then self:Remove(i,true)end end
    self.Plan=plan
end
function Formation:Retry()
    self.Failures=0;self.Losses=0;self.Paused=false;self.NextSpawn=0;self.LastError=nil
    for model in pairs(self.Deleting)do if alive(model)and self:Mine(model)then pcall(self.Context.Destroy,model)end end
end
function Formation:Valid(version)
    local c,r,h=self.Context.Character()
    return self.Active and not self.Closed and self.Generation==version and c==self.CharacterModel and r and h and h.Health>0 and alive(self.Anchor)
end
function Formation:Count()local n=0;for _,v in pairs(self.Slots)do if alive(v.Model)then n+=1 end end;return n end
function Formation:Isolate(item)
    for _,v in ipairs(item.Model:GetDescendants())do if forces[v.ClassName]and not item.Own[v]then
        if not item.Saved[v]then item.Native[#item.Native+1]={Value=v,Parent=v.Parent};item.Saved[v]=true end;v.Parent=nil
    end end
end
function Formation:Make(model,id)
    local root=rootOf(model);local geometry=root and self.Measure(model,root)
    if not geometry or not finite(geometry.Length)or geometry.Length<=.05 then return nil,"No visible geometry"end
    local roots,parts=rootsOf(model);if not roots then return nil,parts end
    for _,r in ipairs(roots)do if not self.Context.IsOwner(r)then return nil,"ownership"end end
    local item={Model=model,Id=id,Root=root,Geometry=geometry,Assemblies={},PartRoots={},Properties={},Native={},Saved={},Own={},Created={}}
    local ok,message=pcall(function()
        for _,p in ipairs(parts)do item.PartRoots[p]=p.AssemblyRootPart or p;item.Properties[p]={p.CanCollide,p.CanTouch,p.CanQuery};p.CanCollide=false;p.CanTouch=false;p.CanQuery=false end
        self:Isolate(item)
        local function new(class)local v=Instance.new(class);item.Created[#item.Created+1]=v;item.Own[v]=true;return v end
        for _,r in ipairs(roots)do
            local a=new("Attachment");a.Name="AstralFormationSource";a.Parent=r
            local target=new("Attachment");target.Name="AstralFormationTarget";target.CFrame=self.Anchor.CFrame:ToObjectSpace(r.CFrame);target.Parent=self.Anchor
            local position=new("AlignPosition");position.Name="AstralFormationPosition";position.Enabled=false
            position.Attachment0=a;position.Attachment1=target;position.Mode=Enum.PositionAlignmentMode.TwoAttachment
            position.ApplyAtCenterOfMass=true;position.RigidityEnabled=false;position.ReactionForceEnabled=false;position.MaxVelocity=80;position.Responsiveness=65;position.MaxForce=0;position.Parent=r
            local rotation=new("AlignOrientation");rotation.Name="AstralFormationOrientation";rotation.Enabled=false
            rotation.Attachment0=a;rotation.Attachment1=target;rotation.Mode=Enum.OrientationAlignmentMode.TwoAttachment
            rotation.RigidityEnabled=false;rotation.ReactionTorqueEnabled=false;rotation.Responsiveness=55;rotation.MaxAngularVelocity=18;rotation.MaxTorque=0;rotation.Parent=r
            item.Assemblies[#item.Assemblies+1]={Root=r,Offset=root.CFrame:ToObjectSpace(r.CFrame),Target=target,Position=position,Rotation=rotation}
        end
    end)
    if not ok then self.Slots[-1]=item;self:Remove(-1,false);return nil,tostring(message)end
    return item
end
function Formation:Move(index,localFrame)
    local item=self.Slots[index];if not item then return false end
    item.LastFrame=localFrame
    local roots,parts=rootsOf(item.Model)
    local reason
    if not roots then reason=parts else
        if #roots~=#item.Assemblies then reason="changed assembly"end
        for _,p in ipairs(parts)do if item.PartRoots[p]~=(p.AssemblyRootPart or p)then reason="changed assembly"end end
        if not reason then for _,a in ipairs(item.Assemblies)do if not self.Context.IsOwner(a.Root)then reason="ownership";self.Context.RequestOwner(a.Root)end end end
    end
    if not self:Mine(item.Model)then reason="transferred"end
    if reason then self:Suspend(item);item.Reason=reason;item.UnsafeSince=item.UnsafeSince or self.Context.Clock();return false,reason end
    if not alive(self.Anchor)or localFrame.Position.Magnitude>27 then self:Suspend(item);return false,"Formation too large for the control range"end
    local rootFrame=localFrame*item.Geometry.RootToGeometry:Inverse()
    for _,a in ipairs(item.Assemblies)do
        local target=self.Anchor.CFrame*rootFrame*a.Offset;local mass=a.Root.AssemblyMass
        if not finite(mass)or mass<=0 or mass>1000000 then self:Suspend(item);return false,"Invalid mass"end
        if item.Placed and ((a.Root.Position-target.Position).Magnitude>38 or a.Root.AssemblyLinearVelocity.Magnitude>180)then
            self:Suspend(item);item.Reason="runaway";item.UnsafeSince=item.UnsafeSince or self.Context.Clock();return false,"recovering displaced toy"
        end
    end
    self:Isolate(item)
    for _,a in ipairs(item.Assemblies)do
        local cf=rootFrame*a.Offset;local mass=a.Root.AssemblyMass
        if a.Target.Parent~=self.Anchor then a.Target.Parent=self.Anchor end
        a.Target.CFrame=cf
        a.Position.MaxForce=mass*((self.Context.Gravity and self.Context.Gravity()or 196.2)+450)
        a.Rotation.MaxTorque=mass*math.clamp(item.Geometry.Length^2,4,1600)*200
        if not item.Placed then a.Root.CFrame=self.Anchor.CFrame*cf;a.Root.AssemblyLinearVelocity=Vector3.zero;a.Root.AssemblyAngularVelocity=Vector3.zero end
        a.Position.Enabled=true;a.Rotation.Enabled=true
    end
    item.Placed=true;item.Reason=nil;item.UnsafeSince=nil;return true
end
function Formation:CanRepair()
    local now=self.Context.Clock();local times={};for _,t in ipairs(self.RepairTimes)do if now-t<60 then times[#times+1]=t end end;self.RepairTimes=times
    return #times<8
end
function Formation:StartSpawn()
    if self.Busy or self.Paused or self.Failures>=3 then return end
    for model in pairs(self.Deleting)do if alive(model)then self.Status="Waiting for removed formation toys";return else self.Deleting[model]=nil end end
    local index=self.Pending and self.Pending.Index
    if not index then for i=1,#self.Plan do if not self.Slots[i]then index=i;break end end end
    if not index or not self.Plan[index]then return end
    local ready,reason=self.Context.CanSpawn();if not ready then self.Status=reason;return end
    local version,id=self.Generation,self.Plan[index];self.Busy=true
    self.Context.SpawnThread(function()
        local model,item
        local ok,message=pcall(function()
            model=self.Pending and self.Pending.Model
            if not alive(model)then model=self.Context.Spawn(id,self.Context.SpawnFrame(index))end
            if not model then error("Game did not return a toy",0)end
            if not self:Valid(version)then return end
            self.Pending=self.Pending or {Model=model,Index=index}
            local hold=model:FindFirstChild("HoldPart",true)
            if not self.Pending.Released and hold and hold:FindFirstChild("HoldItemRemoteFunction")and hold:FindFirstChild("DropItemRemoteFunction")then
                if not self.Context.Release or not self.Context.Release(model,function()return self:Valid(version)end)then
                    error("Held formation item was not released",0)
                end
            end
            if not self:Valid(version)then return end
            self.Pending.Released=true
            local deadline=self.Context.Clock()+3;local last=-1;local stable=self.Context.Clock()
            repeat
                if not self:Valid(version)or not alive(model)then return end
                local n=#model:GetDescendants();if n~=last then stable=self.Context.Clock();last=n end
                local roots=rootsOf(model);local owned=roots~=nil
                if roots then for _,r in ipairs(roots)do if not self.Context.IsOwner(r)then owned=false;self.Context.RequestOwner(r)end end end
                if owned and self.Context.Clock()-stable>=.15 then local err;item,err=self:Make(model,id);if not item then error(err,0)end;return end
                self.Context.Wait(.1)
            until self.Context.Clock()>=deadline
            error("Free toy / acknowledged ownership unavailable; same toy kept for Retry",0)
        end)
        if not self:Valid(version)then
            if item then self.Slots[-1]=item;self:Remove(-1,false)end;self:Delete(model)
        elseif item then
            if self.Plan[index]==id then self.Slots[index]=item;self.Failures=0;self.LastError=nil
            else self.Slots[-1]=item;self:Remove(-1,true)end;self.Pending=nil
        else
            self.Failures+=1;self.LastError=tostring(ok and "Toy disappeared"or message)
            if model and not alive(model)then if not self.Lost[model]then self.Lost[model]=true;self.Losses+=1 end;self.Pending=nil end
        end
        self.Busy=false;self.NextSpawn=self.Context.Clock()+.6
    end)
end
function Formation:Update(anchor)
    if self.Closed or not self.Active then return end
    local c,r,h=self.Context.Character();if not r or not h or h.Health<=0 then return end
    if self.CharacterModel and c~=self.CharacterModel then self:Clear()end
    self.CharacterModel=c;self.Anchor=anchor
    local repairing=0
    for index,item in pairs(self.Slots)do
        if item.UnsafeSince and item.LastFrame and alive(item.Model)and alive(item.Root)then self:Move(index,item.LastFrame)end
        if not alive(item.Model)or not alive(item.Root)then
            if not self.Lost[item.Model]then self.Lost[item.Model]=true;self.Losses+=1 end;self:Remove(index,false)
        elseif item.UnsafeSince and self.Guard and self.Context.Clock()-item.UnsafeSince>=(item.Reason=="ownership"and 2.5 or self.RecoveryDelay)then
            if self:CanRepair()then self.RepairTimes[#self.RepairTimes+1]=self.Context.Clock();self:Remove(index,true);repairing+=1
            else self.LastError="Repair limit reached; release the contested toys or Retry later"end
        end
    end
    if self.Pending and not alive(self.Pending.Model)then local m=self.Pending.Model;if not self.Lost[m]then self.Lost[m]=true;self.Losses+=1 end;self.Pending=nil end
    if self.Losses>=2 then self.Paused=true;self.Status="Game removed extra toys; free inventory slots or use mixed items, then Retry";return end
    if self.Paused or self.Failures>=3 then self.Status=self.LastError or "Retry required";return end
    if self.Context.Clock()>=self.NextSpawn then self:StartSpawn()end
    if self.Busy then self.Status="Preparing free toy "..(self:Count()+1).."/"..#self.Plan
    elseif repairing>0 then self.Status="Replacing contested element"
    elseif self:Count()==#self.Plan then self.Status=self.LastError or "Body-bound formation ready"
    elseif self.LastError then self.Status=self.LastError end
end
function Formation:Dispose()if self.Closed then return end;self.Active=false;self:Clear();self.Closed=true end
return Formation

