sources.GameFlags = [========[
-- Read live markers through Player; never capture an out-of-scope Main local.
local Flags={}
function Flags.Read(player,name)
    local marker=player and player:FindFirstChild(name)
    if not marker then return nil end
    local ok,value=pcall(function()return marker.Value end)
    if ok and type(value)=="boolean" then return value end
end
function Flags.CanBuild(player,states,queue)
    local inPlot,owned=Flags.Read(player,"InPlot"),Flags.Read(player,"InOwnedPlot")
    if inPlot==nil or owned==nil then return false,"Waiting for plot markers" end
    if inPlot and not owned then return false,"Leave another player's plot to build" end
    if Flags.Read(player,"CanSpawnToy")~=true then return false,"Waiting for toy spawn permission" end
    if states and (states.Spawning or states.Owning) or queue and #queue>0 then return false,"Waiting for the current game operation" end
    return true
end
return Flags

