sources.ToyRig = [========[
-- Real reserved toy assemblies. One preparation task; persistent finite movers.
local Rig={};Rig.__index=Rig
local forces={BodyPosition=true,BodyGyro=true,BodyVelocity=true,BodyAngularVelocity=true,BodyForce=true,BodyThrust=true,
    AlignPosition=true,AlignOrientation=true,LinearVelocity=true,AngularVelocity=true,VectorForce=true,Torque=true,RocketPropulsion=true}
local function finite(n)return type(n)=="number" and n==n and math.abs(n)<math.huge end
local function alive(v)return v and v.Parent~=nil end
function Rig.Root(model)
    for _,name in ipairs({"Handle","SoundPart","HoldPart"}) do local p=model:FindFirstChild(name,true);if p and p:IsA("BasePart") then return p end end
    for _,p in ipairs(model:GetDescendants())do if p:IsA("BasePart")and p.Name~="PartHitDetector"then return p end end
end
function Rig.Topology(model)
    if not alive(model)then return nil,"Toy removed"end
    local roots,parts,seen={},{},{}
    for _,v in ipairs(model:GetDescendants())do
        if v:IsA("BasePart")then
            local root=v.AssemblyRootPart or v
            if root.Anchored or not root:IsDescendantOf(model)then return nil,"Toy is anchored or externally joined"end
            parts[#parts+1]=v
            if not seen[root]then seen[root]=true;roots[#roots+1]=root end
        elseif v:IsA("RigidConstraint")and v.Enabled~=false then
            for i=0,1 do local a;if i==0 then a=v.Attachment0 else a=v.Attachment1 end
                if a and a.Parent and a.Parent:IsA("BasePart")and not a.Parent:IsDescendantOf(model)then return nil,"Toy is held"end
            end
        end
    end
    if #roots==0 or #roots>16 then return nil,"Waiting for a complete toy assembly"end
    for _,root in ipairs(roots)do
        local ok,list=pcall(root.GetConnectedParts,root,true)
        if ok then for _,p in ipairs(list)do if not p:IsDescendantOf(model)then return nil,"External physical connection"end end end
    end
    return roots,parts
end
function Rig.Box(model,root)
    local ok,frame,size=pcall(model.GetBoundingBox,model)
    if not ok or typeof(size)~="Vector3"then return end
    local dims={size.X,size.Y,size.Z};local axis=1;for i=2,3 do if dims[i]>dims[axis]then axis=i end end
    if dims[axis]<.05 then return end
    return {Axis=axis,Length=dims[axis],Size=size,RootToRod=root.CFrame:ToObjectSpace(frame)}
end
function Rig.new(context,measure)
    return setmetatable({Context=context,Measure=measure or Rig.Box,Slots={},Plan={},Generation=0,NextSpawn=0,Failures=0,Losses=0,Lost={},Deleting={},Status="Disabled"},Rig)
end
function Rig:Suspend(item)
    for _,a in ipairs(item.Assemblies)do a.Position.Enabled=false;a.Rotation.Enabled=false end
end
function Rig:Drop(index,removeToy)
    local item=self.Slots[index];self.Slots[index]=nil;if not item then return end
    self:Suspend(item)
    for _,v in ipairs(item.Created)do pcall(v.Destroy,v)end
    for _,s in ipairs(item.Native)do
        if alive(s.Parent)then pcall(function()s.Value.Parent=s.Parent end)else pcall(s.Value.Destroy,s.Value)end
    end
    for p,values in pairs(item.Properties)do if alive(p)then p.CanCollide=values[1];p.CanTouch=values[2];p.CanQuery=values[3]end end
    if removeToy then self:Delete(item.Model)end
end
function Rig:Delete(model)
    if model and alive(model)and not self.Deleting[model]then self.Deleting[model]=true;pcall(self.Context.Destroy,model)end
end
function Rig:Clear()
    self.Generation+=1
    for i in pairs(self.Slots)do self:Drop(i,true)end
    if self.Pending then self:Delete(self.Pending.Model);self.Pending=nil end
    self.Failures=0;self.Losses=0;self.Lost={};self.Paused=false;self.NextSpawn=0;self.CharacterModel=nil
end
function Rig:Configure(plan)
    for i,item in pairs(self.Slots)do if not plan[i]or item.Id~=plan[i]then self:Drop(i,true)end end
    self.Plan=plan
end
function Rig:Retry()
    self.Failures=0;self.Losses=0;self.Paused=false;self.NextSpawn=0
    for m in pairs(self.Deleting)do if alive(m)then pcall(self.Context.Destroy,m)end end
end
function Rig:Count()local n=0;for _,v in pairs(self.Slots)do if alive(v.Model)then n+=1 end end;return n end
function Rig:Valid(version)
    local character,root,h=self.Context.Character()
    return not self.Closed and self.Active and version==self.Generation and character==self.CharacterModel and root and h and h.Health>0
end
function Rig:MuteForces(item)
    for _,v in ipairs(item.Model:GetDescendants())do if forces[v.ClassName]and not item.Own[v]then
        if not item.Seen[v]then item.Native[#item.Native+1]={Value=v,Parent=v.Parent};item.Seen[v]=true end
        v.Parent=nil
    end end
end
function Rig:Make(model,id)
    local root=Rig.Root(model);local geometry=root and self.Measure(model,root)
    if not geometry then return nil,"Visible toy geometry unavailable"end
    local roots,parts=Rig.Topology(model);if not roots then return nil,parts end
    for _,r in ipairs(roots)do if not self.Context.IsOwner(r)then return nil,"Waiting for acknowledged ownership"end end
    local item={Model=model,Root=root,Geometry=geometry,Id=id,Assemblies={},PartRoots={},Properties={},Created={},Native={},Seen={},Own={}}
    local ok,message=pcall(function()
        for _,p in ipairs(parts)do item.PartRoots[p]=p.AssemblyRootPart or p;item.Properties[p]={p.CanCollide,p.CanTouch,p.CanQuery};p.CanCollide=false;p.CanTouch=false;p.CanQuery=false end
        self:MuteForces(item)
        local function new(class)local v=Instance.new(class);item.Created[#item.Created+1]=v;item.Own[v]=true;return v end
        for _,r in ipairs(roots)do
            local a=new("Attachment");a.Name="AstralToyRig";a.Parent=r
            local p=new("AlignPosition");p.Name="AstralToyPosition";p.Enabled=false;p.Attachment0=a;p.Mode=Enum.PositionAlignmentMode.OneAttachment
            p.ApplyAtCenterOfMass=true;p.RigidityEnabled=false;p.ReactionForceEnabled=false;p.MaxForce=0;p.MaxVelocity=90;p.Responsiveness=60;p.Parent=r
            local g=new("AlignOrientation");g.Name="AstralToyOrientation";g.Enabled=false;g.Attachment0=a;g.Mode=Enum.OrientationAlignmentMode.OneAttachment
            g.RigidityEnabled=false;g.ReactionTorqueEnabled=false;g.MaxTorque=0;g.MaxAngularVelocity=18;g.Responsiveness=55;g.Parent=r
            item.Assemblies[#item.Assemblies+1]={Root=r,Offset=root.CFrame:ToObjectSpace(r.CFrame),Position=p,Rotation=g}
        end
    end)
    if not ok then self.Slots[-1]=item;self:Drop(-1,false);return nil,tostring(message)end
    return item
end
function Rig:Move(index,frame)
    local item=self.Slots[index];if not item then return false end
    local roots,parts=Rig.Topology(item.Model)
    if not roots then self:Suspend(item);return false,parts end
    for _,p in ipairs(parts)do if item.PartRoots[p]~=(p.AssemblyRootPart or p)then self:Suspend(item);return false,"Toy assembly changed; rebuild"end end
    if #roots~=#item.Assemblies then self:Suspend(item);return false,"Toy assembly changed; rebuild"end
    for _,a in ipairs(item.Assemblies)do if not self.Context.IsOwner(a.Root)then
        self:Suspend(item);self.Context.RequestOwner(a.Root);return false,"Waiting for acknowledged ownership"
    end end
    local _,anchor=self.Context.Character()
    if not anchor or (frame.Position-anchor.Position).Magnitude>30 then self:Suspend(item);return false,"Toy target out of range"end
    local target=frame*item.Geometry.RootToRod:Inverse()
    for _,a in ipairs(item.Assemblies)do
        local mass=a.Root.AssemblyMass;local cf=target*a.Offset
        if not finite(mass)or mass<=0 or mass>1000000 then self:Suspend(item);return false,"Invalid toy mass"end
        if item.Placed and ((a.Root.Position-cf.Position).Magnitude>38 or a.Root.AssemblyLinearVelocity.Magnitude>200)then self:Suspend(item);return false,"Toy left rig; Rebuild to recover"end
    end
    self:MuteForces(item)
    for _,a in ipairs(item.Assemblies)do
        local r=a.Root;local cf=target*a.Offset;local mass=r.AssemblyMass
        a.Position.MaxForce=mass*((self.Context.Gravity and self.Context.Gravity()or 196.2)+450)
        a.Rotation.MaxTorque=mass*math.clamp(item.Geometry.Length^2,4,1600)*220
        a.Position.Position=cf.Position;a.Rotation.CFrame=cf.Rotation
        if not item.Placed then r.CFrame=cf;r.AssemblyLinearVelocity=Vector3.zero;r.AssemblyAngularVelocity=Vector3.zero end
        a.Position.Enabled=true;a.Rotation.Enabled=true
    end
    item.Placed=true;return true
end
function Rig:ObserveLoss(model)
    if model and not self.Lost[model]then self.Lost[model]=true;self.Losses+=1 end
end
function Rig:StartSpawn()
    if self.Busy or self.Paused or self.Failures>=3 then return end
    for m in pairs(self.Deleting)do if alive(m)then self.Status="Waiting for old rig removal";return else self.Deleting[m]=nil end end
    local index=self.Pending and self.Pending.Index
    if not index then for i=1,#self.Plan do if not self.Slots[i]then index=i;break end end end
    if not index then return end
    local ready,reason=self.Context.CanSpawn()
    if not ready then self.Status=reason;return end
    local version,id=self.Generation,self.Plan[index];self.Busy=true
    self.Context.SpawnThread(function()
        local model,item
        local ok,message=pcall(function()
            model=self.Pending and self.Pending.Model
            if not alive(model)then model=self.Context.Spawn(id,self.Context.SpawnFrame(index))end
            if not model then error("Game did not return the toy",0)end
            if not self:Valid(version)then return end
            self.Pending=self.Pending or {Model=model,Index=index}
            local deadline=self.Context.Clock()+2
            local last,stable=-1,self.Context.Clock()
            repeat
                if not self:Valid(version)or not alive(model)then return end
                local n=#model:GetDescendants();if n~=last then stable=self.Context.Clock();last=n end
                local root=Rig.Root(model)
                if root and self.Measure(model,root)and self.Context.Clock()-stable>=.2 then break end
                self.Context.Wait(.05)
            until self.Context.Clock()>deadline
            local hold=model:FindFirstChild("HoldPart",true)
            if not self.Pending.Released and hold and hold:FindFirstChild("HoldItemRemoteFunction")and hold:FindFirstChild("DropItemRemoteFunction")then
                if not self.Context.Release(model,function()return self:Valid(version)end)then error("Hold/drop release not confirmed",0)end
            end
            if not self:Valid(version)then return end
            self.Pending.Released=true;deadline=self.Context.Clock()+2.5
            repeat
                if not self:Valid(version)or not alive(model)then return end
                local roots=Rig.Topology(model);local owned=roots~=nil
                if roots then for _,r in ipairs(roots)do if not self.Context.IsOwner(r)then owned=false;self.Context.RequestOwner(r)end end end
                if owned then local errorMessage;item,errorMessage=self:Make(model,id);if not item then error(errorMessage,0)end;return end
                self.Context.Wait(.1)
            until self.Context.Clock()>deadline
            error("Toy kept for retry: release/ownership not confirmed",0)
        end)
        if not self:Valid(version)then
            if item then self.Slots[-1]=item;self:Drop(-1,false)end
            self:Delete(model)
        elseif item then
            if self.Plan[index]==id then self.Slots[index]=item;self.Failures=0;self.LastError=nil
            else self.Slots[-1]=item;self:Drop(-1,true)end
            self.Pending=nil
        else
            self.Failures+=1;self.LastError=tostring(ok and "Toy disappeared"or message)
            if model and not alive(model)then self:ObserveLoss(model);self.Pending=nil end
        end
        self.Busy=false;self.NextSpawn=self.Context.Clock()+.7
    end)
end
function Rig:Update()
    if not self.Active or self.Closed then return end
    local character,root,h=self.Context.Character();if not root or not h or h.Health<=0 then return end
    if self.CharacterModel and self.CharacterModel~=character then self:Clear()end;self.CharacterModel=character
    for i,item in pairs(self.Slots)do if not alive(item.Model)or not alive(item.Root)then self:ObserveLoss(item.Model);self:Drop(i,false)end end
    if self.Pending and not alive(self.Pending.Model)then self:ObserveLoss(self.Pending.Model);self.Pending=nil end
    if self.Losses>=2 then self.Paused=true end
    if self.Paused then self.Status="Game removed multiple toys; free toy slots, then Retry";return end
    if self.Failures>=3 then self.Status=self.LastError.."; Retry";return end
    if self.Context.Clock()>=self.NextSpawn then self:StartSpawn()end
    if self.Busy then self.Status="Preparing toy "..self:Count()+1 .."/"..#self.Plan
    elseif self:Count()==#self.Plan then self.Status="Ready"elseif self.LastError then self.Status=self.LastError end
end
function Rig:Dispose()self.Active=false;self:Clear();self.Closed=true end
return Rig

