sources.ObjectESP = [========[
-- Local visual markers only; event-indexed models, bounded nearest-first rendering.
-- https://create.roblox.com/docs/reference/engine/classes/Highlight
local requireModule=...;local Catalog=requireModule("AssetCatalog")
local ESP={};ESP.__index=ESP
local nextRenderId=0
local vehicles={CreatureBlobman=true,TractorGreen=true,TractorOrange=true,TractorRed=true,SantaSleigh=true,Train=true}
local function finite(value)return type(value)=="number"and value==value and math.abs(value)<math.huge end
local function frameDt(dt)return finite(dt)and math.clamp(dt,0,.1)or 0 end
local function blend(dt)return 1-math.exp(-32*frameDt(dt))end
local function vectorFinite(v)return v and finite(v.X)and finite(v.Y)and finite(v.Z)end
-- Interpolate motion in world space, then project through this frame's camera.
-- Filtering pixel coordinates makes markers lag behind camera panning.
local function motion(record,distance,dt,reset)
    local root=record.Root;local raw=root.CFrame;local position=raw.Position
    if not vectorFinite(position)then return nil,true end
    local step=frameDt(dt)
    if record.MotionSample and(position-record.MotionSample.Position).Magnitude>math.max(48,math.min(192,distance*.01))then reset=true end
    if reset or not record.MotionFrame or not record.MotionSample then
        record.MotionFrame=raw;record.MotionSample=raw;record.MotionAge=0
        return raw,true
    end
    if(position-record.MotionSample.Position).Magnitude>.0001 then
        record.MotionSample=raw;record.MotionAge=0
    else record.MotionAge=math.min((record.MotionAge or 0)+step,.5)end
    -- Small, decaying extrapolation bridges held replication samples. It never
    -- runs indefinitely when ownership/streaming leaves an obsolete velocity.
    local velocity=root.AssemblyLinearVelocity
    local lead=Vector3.zero
    if vectorFinite(velocity)then
        local speed=velocity.Magnitude
        if speed>128 then velocity=velocity*(128/speed)end
        local age=record.MotionAge
        local horizon=math.min(age,.05)*math.clamp(1-(age-.08)/.18,0,1)
        lead=velocity*horizon
    end
    local target=raw+lead
    local filtered=record.MotionFrame:Lerp(target,blend(step))
    local gap=filtered.Position-position
    local limit=math.clamp(distance*.0015,.4,8)
    if gap.Magnitude>limit then filtered=filtered+(gap.Unit*limit-gap)end
    record.MotionFrame=filtered
    return filtered,false
end
local function settings(color)return {Enabled=false,FillColor=color,OutlineColor=Color3.new(1,1,1),NameColor=Color3.new(1,1,1),NameOutlineColor=Color3.new(0,0,0),
    FillTransparency=.5,OutlineTransparency=0,NameEnabled=true,NameSize=12,Distance=1500,ThroughWalls=true,ShowPicture=true}end
function ESP.Install(context)
    local self=setmetatable({Context=context,Candidates=setmetatable({},{__mode="k"}),Records={},Selected={},AllItems=false,Limit=64,Elapsed=0,InventoryRoots={},GucciLimitEnabled=false,GucciCandidates=true,GucciArrows=true,RenderClock=0,
        Config={Blobman=settings(Color3.fromRGB(100,255,135)),Gucci=settings(Color3.fromRGB(255,220,60)),Item=settings(Color3.fromRGB(255,155,70))},Connections={}},ESP)
    self.Items={};self.Images={}
    for name,image in pairs(Catalog.Items)do self.Items[#self.Items+1]=name;self.Images[name]=image end;table.sort(self.Items)
    self.Container=Instance.new("Folder");self.Container.Name="AstralObjectESP";self.Container.Parent=context.Parent
    local function index(value)
        local model=value
        while model and model~=context.Workspace do
            if model:IsA("Model")and (Catalog.Items[model.Name]or vehicles[model.Name])then self.Candidates[model]=model.Name end
            model=model.Parent
        end
    end
    for _,v in ipairs(context.Workspace:GetDescendants())do if v:IsA("Model")then index(v)end end
    self.Connections[#self.Connections+1]=context.Workspace.DescendantAdded:Connect(index)
    self.Connections[#self.Connections+1]=context.RunService.Heartbeat:Connect(function(dt)
        self.Elapsed+=dt;if self.Elapsed<.2 then return end;self.Elapsed=0
        local ok,message=pcall(self.Update,self)
        if not ok then self:Clear();self.Error=tostring(message)end
    end)
    local bound=false
    if type(context.BindRender)=="function"then
        local ok,connection=pcall(context.BindRender,function(dt)self:Render(dt)end)
        if ok and connection and type(connection.Disconnect)=="function"then
            self.Connections[#self.Connections+1]=connection;bound=true
        end
    end
    if not bound and type(context.RunService.BindToRenderStep)=="function"and type(context.RunService.UnbindFromRenderStep)=="function"then
        nextRenderId+=1;local key="Astral/ObjectESP/"..nextRenderId
        local ok=pcall(function()
            context.RunService:BindToRenderStep(key,Enum.RenderPriority.Camera.Value+2,function(dt)self:Render(dt)end)
        end)
        if ok then
            bound=true
            self.Connections[#self.Connections+1]={Disconnect=function()context.RunService:UnbindFromRenderStep(key)end}
        end
    end
    if not bound then
        local hasRender,render=pcall(function()return context.RunService.RenderStepped end)
        self.Connections[#self.Connections+1]=(hasRender and render or context.RunService.Heartbeat):Connect(function(dt)self:Render(dt)end)
    end
    return self
end
function ESP:SetSelected(values)
    local selected={}
    for key,value in pairs(type(values)=="table"and values or {})do
        if type(key)=="number"and type(value)=="string"then selected[value]=true
        elseif type(key)=="string"and value==true then selected[key]=true end
    end
    self.Selected=selected;self:Update()
end
function ESP:OwnerOf(part)
    local node=part
    for _=1,8 do
        if not node or node==self.Context.Workspace then return end
        local player=self.Context.Players:GetPlayerFromCharacter(node)
        if player then return player end
        node=node.Parent
    end
end
function ESP:RefreshOwners()
    self.InventoryRoots={}
    if not self.Config.Gucci.Enabled then return end
    for _,player in ipairs(self.Context.Players:GetPlayers())do
        local a,b
        if self.Context.Inventory then a,b=self.Context.Inventory(player)
        else a=self.Context.Workspace:FindFirstChild(player.Name.."SpawnedInToys")end
        for _,folder in pairs({a,b})do if folder and folder.Parent then self.InventoryRoots[#self.InventoryRoots+1]={Folder=folder,Player=player}end end
    end
end
function ESP:Root(model)
    if model.PrimaryPart and model.PrimaryPart.Parent and model.PrimaryPart:IsA("BasePart")then return model.PrimaryPart end
    for _,name in ipairs({"HumanoidRootPart","SoundPart","VehicleSeat","Seat","Handle"})do local p=model:FindFirstChild(name,true);if p and p:IsA("BasePart")then return p end end
    for _,p in ipairs(model:GetDescendants())do if p:IsA("BasePart")then return p end end
end
function ESP:Gucci(model)
    if not vehicles[self.Candidates[model]or model.Name]then return end
    for _,seat in ipairs(model:GetDescendants())do if seat:IsA("Seat")or seat:IsA("VehicleSeat")then
        local humanoid=seat.Occupant
        local player=humanoid and self:OwnerOf(humanoid.Parent)
        if player then return player.DisplayName or player.Name end
        for _,weld in ipairs(seat:GetChildren())do if weld.Name=="SeatWeld"and (weld:IsA("Weld")or weld:IsA("WeldConstraint")or weld:IsA("Motor6D"))then
            for _,part in pairs({weld.Part0,weld.Part1})do
                local owner=part and self:OwnerOf(part)
                if owner then return owner.DisplayName or owner.Name end
            end
        end end
    end end
    if not self.GucciCandidates then return end
    local root=self:Root(model);if not root then return end
    for _,entry in ipairs(self.InventoryRoots)do if model:IsDescendantOf(entry.Folder)then
        local player=entry.Player;local character=player.Character
        local anchor=character and (character:FindFirstChild("HumanoidRootPart")or character:FindFirstChild("realHrp"))
        local hidden=true
        for _,p in ipairs(model:GetDescendants())do if p:IsA("BasePart")and p.Transparency<.99 and p.LocalTransparencyModifier<.99 then hidden=false;break end end
        if hidden or anchor and math.abs(root.Position.Y-anchor.Position.Y)>200 then return player.DisplayName or player.Name,true end
    end end
end
function ESP:Category(model,id,distance)
    if self.Config.Gucci.Enabled and distance and distance>1000 then local owner,candidate=self:Gucci(model);if owner then return "Gucci",(candidate and "Gucci? · "or "Gucci · ")..owner end end
    if self.Config.Blobman.Enabled and id=="CreatureBlobman"then return "Blobman","Blobman"end
    if self.Config.Item.Enabled and (self.AllItems or self.Selected[id])then return "Item",id end
end
function ESP:Remove(model)
    local record=self.Records[model];self.Records[model]=nil
    if record then for _,v in ipairs(record.Created)do v:Destroy()end end
end
function ESP:Clear()for m in pairs(self.Records)do self:Remove(m)end end
function ESP:Create(model,root)
    local record={Created={},Root=root}
    local function new(class)local v=Instance.new(class);record.Created[#record.Created+1]=v;return v end
    local h=new("Highlight");h.Name="AstralObjectHighlight";h.Adornee=model;h.Parent=self.Container
    local b=new("BillboardGui");b.Name="AstralObjectLabel";b.Adornee=root;b.MaxDistance=math.huge;b.Size=UDim2.fromOffset(240,46);b.StudsOffset=Vector3.new(0,3,0);b.Parent=self.Container
    local image=new("ImageLabel");image.BackgroundTransparency=1;image.Size=UDim2.fromOffset(30,30);image.Position=UDim2.new(.5,-15,0,0);image.Parent=b
    local label=new("TextLabel");label.BackgroundTransparency=1;label.Size=UDim2.new(1,0,0,16);label.Position=UDim2.new(0,0,1,-16)
    label.Font=Enum.Font.Code;label.TextStrokeTransparency=0;label.Parent=b
    record.Highlight,record.Billboard,record.Label,record.Picture=h,b,label,image;self.Records[model]=record;return record
end
function ESP:ResetSmoothing(record,hide)
    record.SmoothLabel=nil;record.SmoothEdge=nil;record.SmoothCamera=nil;record.SmoothViewport=nil;record.LastWorld=nil
    record.MotionFrame=nil;record.MotionSample=nil;record.MotionAge=0
    record.BoxSmoothing=false
    if hide then
        if record.Screen then record.Screen.Visible=false end
        if record.Edge then record.Edge.Visible=false end
        if record.Billboard then record.Billboard.Enabled=false end
    end
end
function ESP:EdgeMarker(record,kind,name,distance,conf,dt,camera,reset,worldFrame)
    camera=camera or self.Context.Camera and self.Context.Camera()
    if kind~="Gucci"or not self.GucciArrows or not camera then if record.Edge then record.Edge.Visible=false end;record.SmoothEdge=nil;return end
    local point,visible=camera:WorldToViewportPoint(worldFrame and worldFrame.Position or record.Root.Position)
    if not finite(point.X)or not finite(point.Y)or not finite(point.Z)then if record.Edge then record.Edge.Visible=false end;record.SmoothEdge=nil;return end
    if visible and distance<=10000 then if record.Edge then record.Edge.Visible=false end;record.SmoothEdge=nil;return end
    if not record.Edge then
        local label=Instance.new("TextLabel");label.Name="AstralGucciDirection";label.AnchorPoint=Vector2.new(.5,.5);label.Size=UDim2.fromOffset(230,36)
        label.BackgroundTransparency=1;label.BorderSizePixel=0;label.Font=Enum.Font.Code;label.TextSize=12;label.TextStrokeTransparency=1
        label.Parent=self.Container;record.Edge=label;record.Created[#record.Created+1]=label
    end
    local viewport=camera.ViewportSize;local center=viewport*.5
    local dx,dy=point.X-center.X,point.Y-center.Y
    if point.Z<0 then dx=-dx;dy=-dy end
    if math.abs(dx)+math.abs(dy)<.001 then dy=-1 end
    local sx=math.max(center.X-125,1)/math.max(math.abs(dx),.001);local sy=math.max(center.Y-35,1)/math.max(math.abs(dy),.001)
    local scale=math.min(sx,sy);local arrow=math.abs(dx)>math.abs(dy)and (dx>0 and "→"or "←")or (dy>0 and "↓"or "↑")
    local target
    if visible then
        target=Vector2.new(math.clamp(point.X,125,math.max(viewport.X-125,125)),math.clamp(point.Y,35,math.max(viewport.Y-35,35)));arrow="◎"
    else target=Vector2.new(center.X+dx*scale,center.Y+dy*scale)end
    local position=target;record.SmoothEdge=target
    record.Edge.Position=UDim2.fromOffset(position.X,position.Y)
    if reset or record.EdgeName~=name or record.EdgeArrow~=arrow or self.RenderClock>=(record.NextEdgeText or 0)then
        record.NextEdgeText=self.RenderClock+.1
        local whole,height=math.floor(distance),math.floor(record.Root.Position.Y)
        if record.EdgeName~=name or record.EdgeArrow~=arrow or record.EdgeDistance~=whole or record.EdgeHeight~=height then
            record.Edge.Text=arrow.." "..name.."\n"..whole.." studs · Y "..height
            record.EdgeName,record.EdgeArrow,record.EdgeDistance,record.EdgeHeight=name,arrow,whole,height
        end
    end
    record.Edge.TextColor3=conf.NameColor;record.Edge.TextStrokeColor3=conf.NameOutlineColor;record.Edge.Visible=true
end
function ESP:Style(record,model,id,kind,name,distance)
    local conf=self.Config[kind];local h,b,label=record.Highlight,record.Billboard,record.Label
    if record.Kind~=kind then self:ResetSmoothing(record,true)end
    record.Kind,record.Name=kind,name
    h.FillColor=conf.FillColor;h.OutlineColor=conf.OutlineColor;h.FillTransparency=conf.FillTransparency;h.OutlineTransparency=conf.OutlineTransparency
    h.DepthMode=conf.ThroughWalls and Enum.HighlightDepthMode.AlwaysOnTop or Enum.HighlightDepthMode.Occluded
    b.AlwaysOnTop=conf.ThroughWalls;b.Enabled=conf.NameEnabled
    label.Text=name.." ["..math.floor(distance).."]";label.TextSize=conf.NameSize;label.TextColor3=conf.NameColor;label.TextStrokeColor3=conf.NameOutlineColor
    label.TextStrokeTransparency=kind=="Gucci"and 1 or 0
    record.Picture.Image=self.Images[id]or "";record.Picture.Visible=conf.ShowPicture and self.Images[id]~=nil
    if kind~="Gucci"then
        if record.Screen then record.Screen.Visible=false end
        label.Parent=b;record.Picture.Parent=b
        self:EdgeMarker(record,kind,name,distance,conf)
    else
        -- Screen-space labels are animated by RenderStepped. The original
        -- billboard remains available for native occlusion when requested.
        b.Enabled=not conf.ThroughWalls and conf.NameEnabled
    end
    -- Fully invisible Gucci cannot render a normal Highlight: use an adornment
    -- around its actual model bounds. No proxy physics part is created.
    local visible=false
    if kind=="Gucci"then for _,p in ipairs(model:GetDescendants())do if p:IsA("BasePart")and p.Transparency<1 and p.LocalTransparencyModifier<1 then visible=true;break end end else visible=true end
    if not visible then
        if not record.Box then local box=Instance.new("BoxHandleAdornment");box.Name="AstralInvisibleGucci";box.Adornee=record.Root;box.ZIndex=1;box.Parent=self.Container;record.Box=box;record.Created[#record.Created+1]=box end
        local ok,frame,size=pcall(model.GetBoundingBox,model)
        if ok then record.TargetBoxSize=size;record.TargetBoxFrame=record.Root.CFrame:ToObjectSpace(frame)
        else record.TargetBoxSize=record.Root.Size;record.TargetBoxFrame=CFrame.new()end
        if not record.BoxSmoothing then record.Box.Size=record.TargetBoxSize;record.Box.CFrame=record.TargetBoxFrame end
        record.Box.Color3=conf.OutlineColor;record.Box.Transparency=math.max(conf.FillTransparency,.55);record.Box.AlwaysOnTop=conf.ThroughWalls;record.Box.Visible=true
    elseif record.Box then record.Box.Visible=false end
end
function ESP:RenderRecord(record,model,camera,anchor,dt)
    local root=record.Root;local kind=record.Kind;local conf=self.Config[kind]
    local distance=(root.Position-anchor.Position).Magnitude
    if not finite(distance)or kind=="Gucci"and(distance<=1000 or self.GucciLimitEnabled and distance>conf.Distance)
        or kind~="Gucci"and distance>conf.Distance then self:Remove(model);return end
    local viewport=camera.ViewportSize
    if not finite(viewport.X)or not finite(viewport.Y)or viewport.X<=0 or viewport.Y<=0 then self:ResetSmoothing(record,true);return end
    local reset=record.SmoothCamera~=camera or not record.SmoothViewport or record.SmoothViewport~=viewport
    local frame,snapped=motion(record,distance,dt,reset)
    if not frame then self:ResetSmoothing(record,true);return end
    reset=reset or snapped
    local point,visible=camera:WorldToViewportPoint(frame.Position+Vector3.new(0,3,0))
    if not finite(point.X)or not finite(point.Y)or not finite(point.Z)then self:ResetSmoothing(record,true);return end
    local rawPoint=camera:WorldToViewportPoint(root.Position+Vector3.new(0,3,0))
    if finite(rawPoint.X)and finite(rawPoint.Y)and finite(rawPoint.Z)then
        if(point.Z>0)~=(rawPoint.Z>0)then
            frame=root.CFrame;record.MotionFrame=frame;point,visible=camera:WorldToViewportPoint(frame.Position+Vector3.new(0,3,0));reset=true
        else
            local gap=Vector2.new(point.X-rawPoint.X,point.Y-rawPoint.Y).Magnitude
            if gap>12 then
                frame=frame+(frame.Position-root.Position)*(12/gap-1)
                record.MotionFrame=frame;point,visible=camera:WorldToViewportPoint(frame.Position+Vector3.new(0,3,0))
            end
        end
    end
    local target=Vector2.new(point.X,point.Y)
    record.SmoothCamera=camera;record.SmoothViewport=viewport;record.LastWorld=root.Position
    local b,label=record.Billboard,record.Label
    if kind=="Gucci"and conf.ThroughWalls then
        if not record.Screen then
            local screen=Instance.new("Frame");screen.Name="AstralGucciScreenLabel";screen.BackgroundTransparency=1
            screen.AnchorPoint=Vector2.new(.5,.5);screen.Size=UDim2.fromOffset(240,46);screen.Parent=self.Container
            record.Screen=screen;record.Created[#record.Created+1]=screen
        end
        label.Parent=record.Screen;record.Picture.Parent=record.Screen;b.Enabled=false
        record.Screen.Visible=conf.NameEnabled and visible and point.Z>0
        if record.Screen.Visible then
            record.SmoothLabel=target;record.Screen.Position=UDim2.fromOffset(target.X,target.Y)
        else record.SmoothLabel=nil end
    else
        -- Preserve engine depth/occlusion. An offset positions the real
        -- BillboardGui at the smoothed point, without a proxy physics part.
        if record.Screen then record.Screen.Visible=false end
        label.Parent=b;record.Picture.Parent=b;b.Enabled=conf.NameEnabled;record.SmoothLabel=nil
        b.StudsOffset=Vector3.zero
        b.StudsOffsetWorldSpace=frame.Position-root.Position+Vector3.new(0,3,0)
    end
    if reset or record.DisplayName~=record.Name or self.RenderClock>=(record.NextLabelText or 0)then
        record.NextLabelText=self.RenderClock+.1
        local whole=math.floor(distance)
        if record.DisplayName~=record.Name or record.DisplayDistance~=whole then
            label.Text=record.Name.." ["..whole.."]";record.DisplayName=record.Name;record.DisplayDistance=whole
        end
    end
    self:EdgeMarker(record,kind,record.Name,distance,conf,dt,camera,reset,frame)
    if record.Box and record.Box.Visible and record.TargetBoxFrame and record.TargetBoxSize then
        local relative=record.TargetBoxFrame
        if not reset and record.BoxSmoothing and record.SmoothBoxRelative then
            relative=record.SmoothBoxRelative:Lerp(relative,blend(dt))
            record.Box.Size=record.Box.Size:Lerp(record.TargetBoxSize,blend(dt))
        else record.Box.Size=record.TargetBoxSize end
        record.SmoothBoxRelative=relative
        -- Adornment stays on the actual root; its local offset absorbs motion
        -- smoothing while keeping the same model/part and exact dimensions.
        record.Box.CFrame=root.CFrame:ToObjectSpace(frame*relative)
        record.BoxSmoothing=true
    end
end
function ESP:RenderGucci(record,model,camera,anchor,dt)
    return self:RenderRecord(record,model,camera,anchor,dt)
end
function ESP:Render(dt)
    if self.Closed or not next(self.Records)then return end
    self.RenderClock+=frameDt(dt)
    local camera=self.Context.Camera and self.Context.Camera()
    local _,anchor=self.Context.Character()
    for model,record in pairs(self.Records)do
        local conf=self.Config[record.Kind]
        if not model.Parent or not record.Root.Parent or not record.Root:IsDescendantOf(model)or not model:IsDescendantOf(self.Context.Workspace)or not conf or not conf.Enabled then
            self:Remove(model)
        elseif not camera or not anchor or not anchor.Parent then self:ResetSmoothing(record,true)
        else
            local ok,message=pcall(self.RenderRecord,self,record,model,camera,anchor,dt)
            if not ok then self:Remove(model);self.Error=tostring(message)end
        end
    end
end
function ESP:Update()
    if self.Closed then return end
    local _,anchor=self.Context.Character()
    if not anchor then self:Clear();return end
    if not self.Config.Blobman.Enabled and not self.Config.Gucci.Enabled and not self.Config.Item.Enabled then self:Clear();self.Matched=0;return end
    local candidates={}
    self:RefreshOwners()
    for model,id in pairs(self.Candidates)do
        if not model.Parent or not model:IsDescendantOf(self.Context.Workspace)then self.Candidates[model]=nil
        else local root=self:Root(model)
            if root then local distance=(root.Position-anchor.Position).Magnitude;local kind,name=self:Category(model,id,distance)
            if kind then
                if kind=="Gucci"and not self.GucciLimitEnabled or distance<=self.Config[kind].Distance then candidates[#candidates+1]={Model=model,Root=root,Id=id,Kind=kind,Name=name,Distance=distance}end
            end end
        end
    end
    local priority={Gucci=1,Blobman=2,Item=3}
    table.sort(candidates,function(a,b)if priority[a.Kind]~=priority[b.Kind]then return priority[a.Kind]<priority[b.Kind]end;return a.Distance<b.Distance end);self.Matched=#candidates
    local keep={}
    for i=1,math.min(#candidates,self.Limit)do local c=candidates[i];keep[c.Model]=true
        local record=self.Records[c.Model]
        if record and record.Root~=c.Root then self:Remove(c.Model);record=nil end
        record=record or self:Create(c.Model,c.Root);self:Style(record,c.Model,c.Id,c.Kind,c.Name,c.Distance)
    end
    for m in pairs(self.Records)do if not keep[m]then self:Remove(m)end end
    if self.ItemStatus then
        local selected=0;for _ in pairs(self.Selected)do selected+=1 end
        local matched=0;for _,v in ipairs(candidates)do if v.Kind=="Item"then matched+=1 end end
        self.ItemStatus:SetText((self.AllItems and "All catalog items"or selected.." items selected").." | "..matched.." nearby matches")
    end
end
function ESP:BuildUI(toggles,config,selection)
    for _,kind in ipairs({"Blobman","Gucci","Item"})do
        local conf=self.Config[kind];local prefix="Astral"..kind.."ESP"
        local toggle=toggles:AddToggle(prefix,{Text=kind.." ESP",Default=false,Callback=function(v)conf.Enabled=v;self:Update()end})
        for _,field in ipairs({"FillColor","OutlineColor","NameColor","NameOutlineColor"})do local key=field
            toggle:AddColorPicker(prefix..field,{Default=conf[key],Title=kind.." "..key,Callback=function(v)conf[key]=v;self:Update()end})
        end
        if kind=="Item"then
            -- Selection belongs directly under the toggle, like Anti-Kick.
            toggles:AddDropdown("AstralItemESPItems",{Text="Items",Values=self.Items,ValueImages=self.Images,Default={},Multi=true,AllowNull=true,Searchable=true,
                Callback=function(v)self:SetSelected(v)end})
            toggles:AddToggle("AstralItemESPAll",{Text="All Shop Items",Default=false,Callback=function(v)self.AllItems=v;self:Update()end})
            self.ItemStatus=toggles:AddLabel("Choose items above to highlight",true)
        elseif kind=="Gucci"then
            toggles:AddToggle("AstralGucciESPDistanceLimit",{Text="Limit Gucci ESP Distance",Default=false,Callback=function(v)self.GucciLimitEnabled=v;self:Update()end})
            toggles:AddToggle("AstralGucciESPArrows",{Text="Gucci Direction Arrows",Default=true,Callback=function(v)self.GucciArrows=v;self:Update()end})
        end
        local box=config:AddDependencyBox();box:SetupDependencies({{selection,kind.." ESP"}})
        if kind=="Item"then
            box:AddLabel(#self.Items.." embedded source-catalog items; pictures use the original game assets.",true)
        end
        box:AddToggle(prefix.."Names",{Text="Show Names",Default=true,Callback=function(v)conf.NameEnabled=v;self:Update()end})
        box:AddToggle(prefix.."Pictures",{Text="Show Item Picture",Default=true,Callback=function(v)conf.ShowPicture=v;self:Update()end})
        box:AddToggle(prefix.."Walls",{Text="Through Walls",Default=true,Callback=function(v)conf.ThroughWalls=v;self:Update()end})
        for _,field in ipairs({"FillTransparency","OutlineTransparency"})do local key=field
            box:AddSlider(prefix..field,{Text=field=="FillTransparency"and "Fill Transparency"or "Outline Transparency",Default=conf[key],Min=0,Max=1,Rounding=2,Compact=true,Callback=function(v)conf[key]=v;self:Update()end})
        end
        box:AddSlider(prefix.."Distance",{Text="Max Distance",Default=1500,Min=50,Max=kind=="Gucci"and 1000000 or 10000,Rounding=0,Compact=true,Callback=function(v)conf.Distance=v;self:Update()end})
        box:AddSlider(prefix.."NameSize",{Text="Name Size",Default=12,Min=8,Max=28,Rounding=0,Compact=true,Callback=function(v)conf.NameSize=v;self:Update()end})
        if kind=="Gucci"then
            box:AddToggle("AstralGucciESPCandidates",{Text="Include Hidden / High Inventory Rigs",Default=true,Callback=function(v)self.GucciCandidates=v;self:Update()end})
            box:AddLabel("Gucci markers start beyond 1000 studs. Nearby vehicles remain ordinary items. Gucci? marks an unseated hidden/high inventory rig. Only loaded objects can be shown.",true)
        end
    end
    local box=config:AddDependencyBox();box:SetupDependencies({{selection,"Item ESP"}})
    box:AddSlider("AstralObjectESPLimit",{Text="Max Object Highlights",Default=64,Min=8,Max=160,Rounding=0,Compact=true,Callback=function(v)self.Limit=v;self:Update()end})
end
function ESP:Dispose()
    if self.Closed then return end;self.Closed=true
    for _,c in ipairs(self.Connections)do c:Disconnect()end;self:Clear();self.Container:Destroy();self.Candidates={}
end
return ESP

