sources.LineStyles = [========[
-- Real repeating textures plus Beam settings; live edits restore original values on disable.
-- https://create.roblox.com/docs/reference/engine/classes/Beam
local requireModule=...;local Assets=requireModule("VisualAssets")
local Lines={};Lines.__index=Lines
local names={"Arrows","Chevron","Lightning","Circuit","Twin Rails","Barcode","Diamonds","Heartbeat","Sine Wave","Star Trail","Triangles","Zigzag","Dashes","DNA","Glow Dots","Runic"}
local fields={"Texture","TextureMode","TextureLength","TextureSpeed","Color","Width0","Width1","LightEmission","LightInfluence"}
function Lines.Install(context)
    local self=setmetatable({Context=context,Records=setmetatable({},{__mode="k"}),Enabled=false,Speed=1,Width=1,Tint=Color3.new(1,1,1),Phase=0,Presets={},Elapsed=0},Lines)
    for name,texture in pairs(context.Types)do self.Presets[name]={Texture=texture,Length=2,Speed=1}end
    local embeddedCount=0
    for _,name in ipairs(names)do local texture=Assets.Get(name);if texture then embeddedCount+=1 end
        local title=name;self.Presets[title]={Texture=texture or context.Types.Laser,Length=name=="DNA"and 5 or 2,Speed=1.5,Embedded=texture~=nil}
        context.Types[title]=self.Presets[title].Texture
    end
    self.AssetStatus=embeddedCount==#names and "16 embedded tiles + 5 animated variants ready"or "Custom textures require writefile/getcustomasset; native textures remain available"
    for _,entry in ipairs({{"Reverse Arrows","Arrows",-2},{"Fast Chevron","Chevron",4},{"Electric Pulse","Lightning",3},{"Rainbow DNA","DNA",1},{"Rainbow Circuit","Circuit",1}})do
        local title=entry[1];self.Presets[title]={Texture=Assets.Get(entry[2])or context.Types.Laser,Length=3,Speed=entry[3],Rainbow=title:find("Rainbow",1,true)~=nil,Pulse=title=="Electric Pulse"};context.Types[title]=self.Presets[title].Texture
    end
    self.Names={};for name in pairs(self.Presets)do self.Names[#self.Names+1]=name end;table.sort(self.Names);self.Selected=self.Names[1]
    local function discover(v)
        if not v:IsA("Beam")or v.Name~="GrabBeam"then return end
        local p=v.Parent;local found=false;while p and p~=context.Workspace do if p.Name=="GrabParts"then found=true;break end;p=p.Parent end
        if not found or self.Records[v]then return end
        local original={};for _,key in ipairs(fields)do original[key]=v[key]end;self.Records[v]=original
    end
    for _,v in ipairs(context.Workspace:GetDescendants())do discover(v)end
    self.Added=context.Workspace.DescendantAdded:Connect(discover)
    self.Connection=context.RunService.RenderStepped:Connect(function(dt)
        self.Phase+=math.min(dt,.1);self.Elapsed+=dt;if self.Elapsed<1/30 then return end;self.Elapsed=0
        if self.Enabled then self:Apply()end
    end)
    return self
end
function Lines:Select(name)if self.Presets[name]then self.Selected=name;if self.Enabled then self:Apply()end end end
function Lines:Apply()
    local style=self.Presets[self.Selected];if not style then return end
    for beam,original in pairs(self.Records)do if not beam.Parent then self.Records[beam]=nil else
        beam.Texture=style.Texture;beam.TextureMode=Enum.TextureMode.Wrap;beam.TextureLength=style.Length;beam.TextureSpeed=style.Speed*self.Speed
        local color=style.Rainbow and Color3.fromHSV((self.Phase*.15)%1,.8,1)or self.Tint
        beam.Color=ColorSequence.new(color);beam.LightEmission=1;beam.LightInfluence=0
        local pulse=style.Pulse and (.8+math.sin(self.Phase*8)*.2)or 1
        beam.Width0=(original.Width0 or .2)*self.Width*pulse;beam.Width1=(original.Width1 or .2)*self.Width*pulse
    end end
end
function Lines:Restore()
    for beam,original in pairs(self.Records)do if beam.Parent then for _,key in ipairs(fields)do if original[key]~=nil then beam[key]=original[key]end end end end
end
function Lines:SetEnabled(value)self.Enabled=value==true;if self.Enabled then self:Apply()else self:Restore()end end
function Lines:Dispose()self.Enabled=false;self:Restore();self.Added:Disconnect();self.Connection:Disconnect();self.Records={}end
return Lines

