sources.VisualAssets = [========[
-- Self-contained generated VFX sprites and deterministic repeating beam tiles.
local Assets={}
local encoded={
    ["Arrows"]="",
    ["Chevron"]="",
    ["Lightning"]="",
    ["Circuit"]="",
    ["Twin Rails"]="iVBORw0KGgoAAAANSUhEUgAAAIAAAAAgCAYAAADaInAlAAAAiElEQVR4nO3aMQ6DMBAAwXPk/3/ZVJFS06CwMxWNEcXqLGSvc87Q9Xn6A3iWAOIEECeAOAHECSBuz4z/wDATIE4Acfvned18x3cLsf4P15sAcQKIE0CcAOIEECeAOAHECSBOAHECiBNAnADi1nEvPM0EiBNA3J7759C8gAkQJ4A4AcQJIE4AcRcvXA8/ia6jpQAAAABJRU5ErkJggg==",
    ["Barcode"]="iVBORw0KGgoAAAANSUhEUgAAAIAAAAAgCAYAAADaInAlAAAAiklEQVR4nO3bsQqAIBRAUY3+/5dtChxqLrjnjD3Ehou4ONdag67j6x/gWwKIE0DcOca4LwHzYf50QZgvs339evm+z+z3g/2cAHECiBNAnADiBBAngDgBxAkgTgBxAogTQJwA4gQQJ4A4AcQJIE4AcQKIE0CcAOIEECeAOAHECSBuehza5gSIE0DcBV/7GTpnYMvvAAAAAElFTkSuQmCC",
    ["Diamonds"]="",
    ["Heartbeat"]="",
    ["Sine Wave"]="",
    ["Star Trail"]="",
    ["Triangles"]="",
    ["Zigzag"]="",
    ["Dashes"]="",
    ["DNA"]="",
    ["Glow Dots"]="",
    ["Runic"]="",
    ["Azure Vortex"]="",
    ["Astral Fire"]="",
}

local cache={}
local alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function decode(text)
 local api=crypt and (crypt.base64decode or crypt.base64 and crypt.base64.decode)
 if type(api)=="function"then local ok,result=pcall(api,text);if ok and type(result)=="string"then return result end end
 local map={};for i=1,#alphabet do map[alphabet:byte(i)]=i-1 end
 local chunks,pieces={},{}
 for i=1,#text,4 do
  local a,b,c,d=text:byte(i,i+3);local n=map[a]*262144+map[b]*4096+(map[c]or 0)*64+(map[d]or 0)
  local value=string.char(math.floor(n/65536)%256)
  if c~=61 then value..=string.char(math.floor(n/256)%256)end
  if d~=61 then value..=string.char(n%256)end
  pieces[#pieces+1]=value
  if #pieces>=1024 then chunks[#chunks+1]=table.concat(pieces);pieces={}end
 end
 chunks[#chunks+1]=table.concat(pieces);return table.concat(chunks)
end
function Assets.Get(name)
 if cache[name]then return cache[name]end
 if not encoded[name]then return end
 local custom=getcustomasset or getsynasset
 if type(custom)~="function"or type(writefile)~="function"then return end
 local ok,value=pcall(function()
  local path="astral_v426_"..name:lower():gsub("[^%w]","_")..".png"
  writefile(path,decode(encoded[name]));return custom(path)
 end)
 if ok and type(value)=="string"then cache[name]=value;return value end
end
Assets.Decode=decode
return Assets

