sources.BlackholeFX = [========[
-- Layered local animation on the game's real Hole/BillboardGui. No physics changes.
local requireModule=...;local Assets=requireModule("VisualAssets")
local FX={};FX.__index=FX
FX.Names={"Azure Vortex","Astral Fire","Chrono Ring"}
local roman={"I","II","III","IV","V","VI","VII","VIII","IX","X","XI","XII"}
local function circle(parent,size,stroke,color)
    local f=Instance.new("Frame");f.Name="Ring";f.BackgroundTransparency=1;f.AnchorPoint=Vector2.new(.5,.5);f.Position=UDim2.fromScale(.5,.5);f.Size=UDim2.fromScale(size,size);f.Parent=parent
    local c=Instance.new("UICorner");c.CornerRadius=UDim.new(1,0);c.Parent=f
    local s=Instance.new("UIStroke");s.Thickness=stroke;s.Color=color;s.Parent=f
    return f,s
end
function FX.Install(context)
    local self=setmetatable({Context=context,Enabled=false,Style="Azure Vortex",Speed=1,Intensity=1,Tint=Color3.new(1,1,1),Phase=0,Records={},Candidates=setmetatable({},{__mode="k"}),MaxEffects=6,Elapsed=0},FX)
    local function discover(value)
        local p=value;while p and p~=context.Workspace do
            if p.Name=="BlackHoleKick"or p.Name=="StayedBH"then self.Candidates[p]=true;break end;p=p.Parent
        end
    end
    for _,v in ipairs(context.Workspace:GetChildren())do discover(v)end
    self.Added=context.Workspace.DescendantAdded:Connect(discover)
    self.Connection=context.RunService.RenderStepped:Connect(function(dt)
        if not self.Enabled then return end
        self.Phase+=math.clamp(dt,0,.1)*self.Speed;self.Elapsed+=dt
        if self.Elapsed<1/30 then return end;self.Elapsed=0
        local ok,message=pcall(self.Update,self)
        if not ok then self:SetEnabled(false);self.Status="Blackhole FX: "..tostring(message)end
    end)
    return self
end
function FX:Remove(model)
    local record=self.Records[model];self.Records[model]=nil;if not record then return end
    if record.Large.Parent then record.Large.Visible=record.LargeVisible end
    if record.Small and record.Small.Parent then record.Small.Visible=record.SmallVisible end
    if record.Hole.Parent then record.Hole.Transparency=record.Transparency end
    record.Frame:Destroy()
end
function FX:Clear()for model in pairs(self.Records)do self:Remove(model)end end
function FX:SetEnabled(value)
    self.Enabled=value==true and not self.Closed
    if not self.Enabled then self:Clear();if self.Context.Restore then self.Context.Restore()end end
end
function FX:SetStyle(value)
    if not table.find(self.Names,value)then return false end
    if self.Style~=value then self.Style=value;self.AssetFailure=nil;self:Clear()end;return true
end
function FX:Build(model)
    if self.AssetFailure==self.Style then return end
    local hole=model:FindFirstChild("Hole");local billboard=hole and hole:FindFirstChild("BillboardGui")
    local large=billboard and billboard:FindFirstChild("Large");local small=billboard and billboard:FindFirstChild("Small")
    if not large or not large:IsA("ImageLabel")then return end
    local record={Hole=hole,Large=large,Small=small,LargeVisible=large.Visible,SmallVisible=small and small.Visible,Transparency=hole.Transparency,Layers={},Particles={},Strokes={}}
    local frame=Instance.new("Frame");frame.Name="AstralAnimatedBlackhole";frame.BackgroundTransparency=1;frame.ClipsDescendants=false;frame.Parent=billboard;record.Frame=frame
    local aspect=Instance.new("UIAspectRatioConstraint");aspect.AspectRatio=1;aspect.Parent=frame
    if self.Style=="Chrono Ring"then
        -- The numerals/ticks are real GUI geometry, so they stay sharp and clean
        -- instead of retaining screenshot characters or baked clock hands.
        for _,size in ipairs({.98,.91,.68})do local _,stroke=circle(frame,size,2,Color3.new(1,1,1));record.Strokes[#record.Strokes+1]=stroke end
        for i=0,59 do
            local a=i*math.pi/30;local tick=Instance.new("Frame");tick.Name="Tick";tick.BorderSizePixel=0;tick.AnchorPoint=Vector2.new(.5,.5)
            tick.Position=UDim2.fromScale(.5+math.sin(a)*.467,.5-math.cos(a)*.467);tick.Size=UDim2.fromScale(.003,i%5==0 and .035 or .019);tick.Rotation=i*6;tick.Parent=frame
            record.Layers[#record.Layers+1]={Object=tick,ClockPart=true}
        end
        for i=1,12 do
            local angle=i*math.pi/6;local label=Instance.new("TextLabel");label.Name="Numeral";label.BackgroundTransparency=1;label.AnchorPoint=Vector2.new(.5,.5)
            label.Position=UDim2.fromScale(.5+math.sin(angle)*.397,.5-math.cos(angle)*.397);label.Size=UDim2.fromScale(.16,.1)
            label.Text=roman[i];label.Font=Enum.Font.Garamond;label.TextScaled=true;label.TextStrokeTransparency=.75;label.Parent=frame
            record.Layers[#record.Layers+1]={Object=label,ClockText=true}
        end
        for i,length in ipairs({.25,.33,.37})do
            local hand=Instance.new("Frame");hand.Name="Hand";hand.BorderSizePixel=0;hand.AnchorPoint=Vector2.new(.5,1);hand.Position=UDim2.fromScale(.5,.5)
            hand.Size=UDim2.fromScale(i==3 and .003 or .009,length);hand.Parent=frame
            record.Layers[#record.Layers+1]={Object=hand,ClockPart=true,Hand=i}
        end
    else
        local texture=Assets.Get(self.Style)
        if not texture then frame:Destroy();self.AssetFailure=self.Style;self.Status="Custom assets unavailable: writefile/getcustomasset required. Chrono Ring works without them.";return end
        local scales={1,1.08,.72};local alpha={0,.68,.76}
        for i=1,3 do
            local image=Instance.new("ImageLabel");image.Name="VortexLayer";image.BackgroundTransparency=1;image.AnchorPoint=Vector2.new(.5,.5);image.Position=UDim2.fromScale(.5,.5)
            image.Size=UDim2.fromScale(scales[i],scales[i]);image.Image=texture;image.Parent=frame
            record.Layers[#record.Layers+1]={Object=image,Scale=scales[i],Alpha=alpha[i],Spin=({25,-17,42})[i],Offset=i*45}
        end
    end
    for i=1,24 do
        local p=Instance.new("Frame");p.Name="OrbitParticle";p.BorderSizePixel=0;p.AnchorPoint=Vector2.new(.5,.5);p.Size=UDim2.fromScale(.004+i%3*.0015,.004+i%3*.0015);p.Parent=frame
        local c=Instance.new("UICorner");c.CornerRadius=UDim.new(1,0);c.Parent=p;record.Particles[i]=p
    end
    self.Records[model]=record;return record
end
function FX:Animate(record)
    local phase=self.Phase;local large=record.Large;local frame=record.Frame
    frame.Size=large.Size;frame.Position=large.Position;frame.AnchorPoint=large.AnchorPoint;frame.ZIndex=large.ZIndex
    large.Visible=false;if record.Small then record.Small.Visible=false end;record.Hole.Transparency=1
    local fade=large.ImageTransparency;local alpha=math.clamp(self.Intensity,0,1)
    for _,layer in ipairs(record.Layers)do local v=layer.Object
        if layer.ClockText then v.TextColor3=self.Tint;v.TextTransparency=1-(1-fade)*alpha
        elseif layer.ClockPart then
            v.BackgroundColor3=self.Tint;v.BackgroundTransparency=1-(1-fade)*alpha
            if layer.Hand then v.Rotation=phase*({4,24,120})[layer.Hand]end
        else
            local scale=layer.Scale*(1+math.sin(phase*2+layer.Offset)*.025)
            v.Size=UDim2.fromScale(scale,scale);v.Rotation=phase*layer.Spin+layer.Offset;v.ImageColor3=self.Tint
            v.ImageTransparency=1-(1-layer.Alpha)*(1-fade)*alpha
        end
    end
    for _,stroke in ipairs(record.Strokes)do stroke.Color=self.Tint;stroke.Transparency=1-(1-fade)*alpha end
    for i,p in ipairs(record.Particles)do
        local t=(phase*.16+i/24)%1;local radius=.55-t*.26;local a=i*2.4+phase*(self.Style=="Chrono Ring"and .3 or .8)
        p.Position=UDim2.fromScale(.5+math.sin(a)*radius,.5+math.cos(a)*radius)
        p.BackgroundColor3=self.Style=="Azure Vortex"and Color3.fromRGB(70,210,255)or self.Style=="Astral Fire"and (i%2==0 and Color3.fromRGB(255,155,45)or Color3.fromRGB(180,100,255))or self.Tint
        p.BackgroundTransparency=1-math.sin(t*math.pi)*(1-fade)*alpha
    end
end
function FX:Update()
    if not self.Enabled or self.Closed then return end
    local count=0
    for model,record in pairs(self.Records)do
        if not model.Parent or not record.Hole.Parent or not record.Large.Parent then self:Remove(model)
        else count+=1;self:Animate(record)end
    end
    for model in pairs(self.Candidates)do
        if not model.Parent then self.Candidates[model]=nil
        elseif not self.Records[model]and count<self.MaxEffects then local r=self:Build(model);if r then count+=1;self:Animate(r)end end
    end
    if count>0 then self.Status=count.." animated blackholes"end
end
function FX:Dispose()if self.Closed then return end;self:SetEnabled(false);self.Closed=true;self.Added:Disconnect();self.Connection:Disconnect()end
return FX

