sources.VehicleSpeed = [========[
local Vehicles={};Vehicles.__index=Vehicles
local kinds={TractorGreen="Tractor",TractorOrange="Tractor",TractorRed="Tractor",SantaSleigh="Sleigh"}
function Vehicles.Kind(seat,workspace)
    local current=seat.Parent
    while current and current~=workspace do
        if current:IsA("Model") and kinds[current.Name] then return kinds[current.Name],current end
        current=current.Parent
    end
end
function Vehicles.Install(context)
    local self=setmetatable({Context=context,Settings={Tractor={Enabled=false,Speed=60},Sleigh={Enabled=false,Speed=60}},Status="Disabled"},Vehicles)
    self.Connection=context.RunService.PreSimulation:Connect(function()
        local ok,message=pcall(self.Step,self)
        if not ok then self:Clear();self.Status="Vehicle control: "..tostring(message) end
    end)
    return self
end
function Vehicles:Configure(kind,key,value)
    local setting=self.Settings[kind]
    if not setting then return false end
    if key=="Enabled" then setting.Enabled=value==true
    elseif key=="Speed" and type(value)=="number" and value==value and math.abs(value)<math.huge then setting.Speed=math.clamp(value,1,1000)
    else return false end
    return true
end
function Vehicles:Clear()
    local s=self.Active;self.Active=nil
    if not s then return end
    if s.Drive then s.Drive:Destroy() end
    if s.Upright then s.Upright:Destroy() end
    if s.UprightAttachment then s.UprightAttachment:Destroy() end
    if s.Attachment then s.Attachment:Destroy() end
    if s.Seat.Parent then s.Seat.MaxSpeed=s.OriginalSpeed end
end
function Vehicles:Step()
    if self.Closed then return end
    local character,humanoid=self.Context.Character()
    local seat=humanoid and humanoid.Health>0 and humanoid.SeatPart
    local kind,model
    if seat and seat:IsA("VehicleSeat") and seat.Occupant==humanoid then kind,model=self.Kind(seat,self.Context.Workspace) end
    if not kind or not self.Settings[kind].Enabled then self:Clear();self.Status="Sit in an enabled tractor or sleigh";return end
    if self.Active and self.Active.Seat~=seat then self:Clear() end
    if not self.Active then self.Active={Seat=seat,OriginalSpeed=seat.MaxSpeed} end
    local s=self.Active;local speed=self.Settings[kind].Speed
    seat.MaxSpeed=speed
    local root=seat.AssemblyRootPart or seat
    local mass=root.AssemblyMass
    if root.Anchored or type(mass)~="number" or mass~=mass or mass<=0 or mass>=math.huge or not self.Context.IsOwner(root) then
        if s.Drive then s.Drive.Enabled=false end
        if s.Upright then s.Upright.Enabled=false end
        self.Status="Waiting for vehicle physics ownership";return
    end
    if s.Root~=root then
        if s.Drive then s.Drive:Destroy() end
        if s.Attachment then s.Attachment:Destroy() end
        if s.Upright then s.Upright:Destroy() end
        if s.UprightAttachment then s.UprightAttachment:Destroy() end
        s.Upright,s.UprightAttachment=nil,nil
        s.Drive,s.Attachment=nil,nil;s.Root=root
    end
    if kind=="Tractor" and not s.Upright then
        s.UprightAttachment=Instance.new("Attachment")
        s.UprightAttachment.Name="AstralVehicleUpright"
        -- The constraint's primary X axis follows the seat's local UP axis.
        s.UprightAttachment.CFrame=root.CFrame:ToObjectSpace(seat.CFrame)*
            CFrame.fromMatrix(Vector3.zero,Vector3.yAxis,Vector3.zAxis,Vector3.xAxis)
        s.UprightAttachment.Parent=root
        s.Upright=Instance.new("AlignOrientation")
        s.Upright.Name="AstralAntiRollover";s.Upright.Attachment0=s.UprightAttachment
        s.Upright.Mode=Enum.OrientationAlignmentMode.OneAttachment
        s.Upright.AlignType=Enum.AlignType.PrimaryAxisParallel
        s.Upright.PrimaryAxis=Vector3.yAxis;s.Upright.SecondaryAxis=Vector3.zAxis
        s.Upright.RigidityEnabled=false;s.Upright.ReactionTorqueEnabled=false
        s.Upright.Responsiveness=35;s.Upright.MaxAngularVelocity=12;s.Upright.Parent=root
    end
    if s.Upright then
        local size=root.Size or Vector3.new(4,4,4)
        pcall(function() size=model:GetExtentsSize() end)
        s.Upright.MaxTorque=mass*math.clamp(size:Dot(size),4,400)*80
        s.Upright.Enabled=true
    end
    if not s.Drive or not s.Drive.Parent or not s.Attachment.Parent then
        if s.Drive then s.Drive:Destroy() end;if s.Attachment then s.Attachment:Destroy() end
        s.Attachment=Instance.new("Attachment");s.Attachment.Name="AstralVehicleDrive";s.Attachment.Parent=root
        s.Drive=Instance.new("LinearVelocity");s.Drive.Attachment0=s.Attachment
        s.Drive.Name="AstralVehicleSpeed";s.Drive.RelativeTo=Enum.ActuatorRelativeTo.World
        s.Drive.VelocityConstraintMode=Enum.VelocityConstraintMode.Plane
        s.Drive.PrimaryTangentAxis=Vector3.xAxis;s.Drive.SecondaryTangentAxis=Vector3.zAxis
        s.Drive.ForceLimitsEnabled=true;s.Drive.ForceLimitMode=Enum.ForceLimitMode.PerAxis
        s.Drive.Parent=root
    end
    local center=root.AssemblyCenterOfMass
    if typeof(center)=="Vector3" then
        s.Attachment.Position=root.CFrame:PointToObjectSpace(center)
    end
    local forward=Vector3.new(seat.CFrame.LookVector.X,0,seat.CFrame.LookVector.Z)
    if forward.Magnitude>.01 then forward=forward.Unit else forward=Vector3.zero end
    local stable=kind~="Tractor" or seat.CFrame.UpVector:Dot(Vector3.yAxis)>.35
    local target=forward*(math.clamp(seat.ThrottleFloat,-1,1)*speed*(stable and 1 or 0))
    s.Drive.PlaneVelocity=Vector2.new(target.X,target.Z)
    s.Drive.MaxPlanarAxesForce=Vector2.new(mass*160,mass*160)
    s.Drive.Enabled=true
    self.Status=kind.." target: "..math.floor(speed).." studs/s"
end
function Vehicles:Dispose()
    self.Closed=true;self:Clear();self.Connection:Disconnect()
end
return Vehicles

