sources.CharacterTools = [========[
-- Local character controls. No anchoring, remote respawn loop or stale spawn position.
local Tools={};Tools.__index=Tools
function Tools.Install(context)
    return setmetatable({Context=context,Locked=false,AntiAFK=false},Tools)
end
function Tools:StepLock()
    if self.Closed or not self.Locked then return end
    local character,root,humanoid=self.Context.Character()
    if not root or not humanoid or humanoid.Health<=0 or humanoid.SeatPart then
        self.LockRoot=nil;self.LockPoint=nil;return
    end
    if root~=self.LockRoot or character~=self.LockCharacter then
        self.LockRoot=root;self.LockCharacter=character;self.LockPoint=root.Position
    end
    -- Translation only: do not overwrite spin/orientation or change assembly ownership.
    root.CFrame=root.CFrame+(self.LockPoint-root.Position)
    root.AssemblyLinearVelocity=Vector3.zero
end
function Tools:SetLocked(value)
    value=value==true and not self.Closed
    if self.Locked==value then return end
    if self.LockConnection then self.LockConnection:Disconnect();self.LockConnection=nil end
    self.Locked=value;self.LockRoot=nil;self.LockPoint=nil;self.LockCharacter=nil
    if value then
        if self.Context.BeforeLock then self.Context.BeforeLock() end
        self:StepLock()
        self.LockConnection=self.Context.RunService.PreSimulation:Connect(function() self:StepLock() end)
    end
end
function Tools:SetAntiAFK(value)
    value=value==true and not self.Closed
    if self.AntiAFK==value then return end
    if self.IdleConnection then self.IdleConnection:Disconnect();self.IdleConnection=nil end
    self.AntiAFK=value
    if value then
        self.IdleConnection=self.Context.Player.Idled:Connect(function()
            if self.Closed or not self.AntiAFK then return end
            local ok,message=pcall(self.Context.IdleAction)
            if not ok and self.Context.Notify then self.Context.Notify("Anti AFK unavailable: "..tostring(message)) end
        end)
    end
end
function Tools:Respawn()
    if self.Closed then return false end
    local _,_,humanoid=self.Context.Character()
    if not humanoid or humanoid.Health<=0 then return false end
    humanoid.Health=0
    humanoid:ChangeState(Enum.HumanoidStateType.Dead)
    return true
end
function Tools:Dispose()
    if self.Closed then return end
    self.Closed=true;self:SetLocked(false);self:SetAntiAFK(false)
end
return Tools

