sources.PositionDesync = [========[
-- Same PhysicsRepRootPart / S2PhysicsSenderRate mechanism as the supplied source.
-- A non-yielding state machine replaces overlapping Heartbeat callbacks.
local Desync={};Desync.__index=Desync
function Desync.Install(context)
    local supported=type(context.SetHidden)=="function" and type(context.GetHidden)=="function"
        and type(context.SetFlag)=="function" and type(context.GetFlag)=="function"
    return setmetatable({Context=context,Enabled=false,
        Status=supported and "Disabled" or "Required executor APIs unavailable",Supported=supported},Desync)
end
function Desync:SetRate(value)
    for _,candidate in ipairs({tostring(value),value}) do
        local wrote=pcall(self.Context.SetFlag,"S2PhysicsSenderRate",candidate)
        local ok,result=pcall(self.Context.GetFlag,"S2PhysicsSenderRate")
        if wrote and ok and tonumber(result)==tonumber(value) then return true end
    end
    return false
end
function Desync:SetRoot(root,value)
    local wrote=pcall(self.Context.SetHidden,root,"PhysicsRepRootPart",value)
    local read,current=pcall(self.Context.GetHidden,root,"PhysicsRepRootPart")
    return wrote and read and current==value
end
function Desync:RestoreRoot()
    local root=self.Root
    if root and root.Parent then
        if not self:SetRoot(root,self.OriginalRoot)then return false end
    end
    self.Root=nil;self.OriginalRoot=nil;self.Phase=nil
    return true
end
function Desync:Stop(reason)
    if self.Stopping then return false end
    self.Stopping=true
    if self.Connection then self.Connection:Disconnect();self.Connection=nil end
    local clean=self:RestoreRoot()
    if self.OriginalRate~=nil then
        local restored=self:SetRate(self.OriginalRate)
        clean=restored and clean
        if restored then self.OriginalRate=nil end
    end
    self.Enabled=false
    self.Status=reason or "Disabled"
    if not clean then self.Status..=" (restore rejected by executor)" end
    if self.Context.Changed then self.Context.Changed(false,self.Status) end
    self.Stopping=false
    return false
end
function Desync:Step()
    if self.Closed or not self.Enabled then return end
    local now=self.Context.Clock()
    if now>=self.NextRateCheck then
        self.NextRateCheck=now+1
        local ok,value=pcall(self.Context.GetFlag,"S2PhysicsSenderRate")
        if (not ok or tonumber(value)~=1000) and not self:SetRate(1000) then return self:Stop("Physics sender flag rejected") end
    end
    local character,root,humanoid=self.Context.Character()
    if not root or not character or not character.Parent or not humanoid or humanoid.Health<=0 then
        if self.Root and not self:RestoreRoot() then return self:Stop("Root restore rejected") end
        self.Status="Enabled - waiting for character";return
    end
    if root~=self.Root then
        if not self:RestoreRoot() then return self:Stop("Root restore rejected") end
        local read,value=pcall(self.Context.GetHidden,root,"PhysicsRepRootPart")
        if not read then return self:Stop("Cannot read the original replication root")end
        self.Root=root;self.OriginalRoot=value
        self.Phase="Attach";self.NextPhase=now
    end
    if now<self.NextPhase then return end
    local attach=self.Phase=="Attach"
    -- Avoid `attach and root or nil` ambiguity with false-like mock values.
    local target=nil;if attach then target=root end
    if not self:SetRoot(root,target)then return self:Stop("Replication-root write was not verified")end
    self.Phase=attach and "Release" or "Attach"
    self.NextPhase=now+(attach and .14 or .1)
    self.Status="Local settings verified; server desync unverified"
end
function Desync:SetEnabled(value)
    if value~=true or self.Closed then
        if self.Enabled or self.Root or self.OriginalRate~=nil then return self:Stop() end
        return false
    end
    if self.Enabled then return true end
    if self.Root or self.OriginalRate~=nil then
        self:Stop("Restoring previous settings")
        if self.Root or self.OriginalRate~=nil then return false end
    end
    if not self.Supported then return self:Stop("Required executor APIs unavailable") end
    local ok,value=pcall(self.Context.GetFlag,"S2PhysicsSenderRate")
    if not ok or not tonumber(value) then return self:Stop("Physics sender flag unavailable") end
    self.OriginalRate=value
    if not self:SetRate(1000) then return self:Stop("Physics sender flag rejected") end
    self.Enabled=true;self.Status="Enabled";self.NextRateCheck=self.Context.Clock()+1
    self.Connection=self.Context.RunService.Heartbeat:Connect(function()
        local succeeded,message=pcall(self.Step,self)
        if not succeeded then self:Stop("Desync stopped: "..tostring(message)) end
    end)
    if self.Context.Changed then self.Context.Changed(true,self.Status) end
    self:Step()
    return self.Enabled
end
function Desync:Dispose()
    if self.Closed then return end
    self.Closed=true;self:Stop()
end
return Desync

]========]
sources.WallClimb = [========[
-- Wall contact is measured by a short ray; forces affect only the local character.
local Climb={};Climb.__index=Climb
local function destroy(value) if value then value:Destroy() end end
function Climb.Install(context)
    local self=setmetatable({Context=context,Enabled=false,Speed=16,Cooldown=0},Climb)
    self.Connection=context.RunService.PreSimulation:Connect(function()
        local ok,message=pcall(self.Step,self)
        if not ok then self:Release();self.Status="Wall Climb: "..tostring(message) end
    end)
    self.Jump=context.Input.JumpRequest:Connect(function()
        local active=self.Active
        if not active then return end
        self.Cooldown=context.Clock()+.5
        self:Release()
        if active.Root.Parent and active.Humanoid.Health>0 then
            active.Root.AssemblyLinearVelocity=active.Normal*25+Vector3.yAxis*22
            active.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
        end
    end)
    return self
end
function Climb:SetEnabled(value)
    self.Enabled=value==true and not self.Closed
    if not self.Enabled then self:Release() end
end
function Climb:SetSpeed(value)
    if type(value)~="number" or value~=value or math.abs(value)==math.huge then return false end
    self.Speed=math.clamp(value,5,60);return true
end
function Climb:Release()
    local active=self.Active;self.Active=nil
    if not active then return end
    destroy(active.Drive);destroy(active.Align);destroy(active.Attachment)
    if active.Track then pcall(function()active.Track:Stop(.15)end) end
    if active.Humanoid.Parent then
        active.Humanoid.AutoRotate=active.AutoRotate
        active.Humanoid.PlatformStand=active.PlatformStand
    end
end
function Climb:FindWall(character,root,humanoid)
    local params=RaycastParams.new()
    params.FilterType=Enum.RaycastFilterType.Exclude
    local exclusions={character}
    if self.Context.Inventory then
        local inventory=self.Context.Inventory();if inventory then exclusions[#exclusions+1]=inventory end
    end
    params.FilterDescendantsInstances=exclusions;params.RespectCanCollide=true;params.IgnoreWater=true
    local directions={}
    if self.Active then directions[#directions+1]=-self.Active.Normal end
    directions[#directions+1]=root.CFrame.LookVector
    if humanoid.MoveDirection.Magnitude>.1 then directions[#directions+1]=humanoid.MoveDirection end
    for _,direction in ipairs(directions) do
        local horizontal=Vector3.new(direction.X,0,direction.Z)
        if horizontal.Magnitude>.05 then
            local hit=self.Context.Workspace:Raycast(root.Position,horizontal.Unit*3.2,params)
            if hit and math.abs(hit.Normal:Dot(Vector3.yAxis))<.35 then return hit end
        end
    end
end
function Climb:Step()
    if self.Closed or not self.Enabled then return end
    local character,root,humanoid=self.Context.Character()
    local blocked=self.Context.Blocked and self.Context.Blocked()
    if blocked or not root or not humanoid or humanoid.Health<=0 or humanoid.SeatPart or self.Context.Clock()<self.Cooldown then
        self:Release();return
    end
    if self.Active and self.Active.Root~=root then self:Release() end
    local mass=root.AssemblyMass
    if root.Anchored or mass<=0 or mass>=math.huge or mass~=mass or not self.Context.IsOwner(root) then self:Release();return end
    if self.Context.Input:GetFocusedTextBox() then self:Release();return end
    local hit=self:FindWall(character,root,humanoid)
    if not hit then self:Release();return end
    if not self.Active then
        local active={Root=root,Humanoid=humanoid,AutoRotate=humanoid.AutoRotate,PlatformStand=humanoid.PlatformStand}
        self.Active=active
        active.Attachment=Instance.new("Attachment");active.Attachment.Name="AstralWallClimb";active.Attachment.Parent=root
        active.Drive=Instance.new("LinearVelocity");active.Drive.Attachment0=active.Attachment
        active.Drive.RelativeTo=Enum.ActuatorRelativeTo.World;active.Drive.VelocityConstraintMode=Enum.VelocityConstraintMode.Vector
        active.Drive.ForceLimitsEnabled=true;active.Drive.ForceLimitMode=Enum.ForceLimitMode.PerAxis;active.Drive.Parent=root
        active.Align=Instance.new("AlignOrientation");active.Align.Attachment0=active.Attachment
        active.Align.Mode=Enum.OrientationAlignmentMode.OneAttachment;active.Align.AlignType=Enum.AlignType.AllAxes
        active.Align.RigidityEnabled=false;active.Align.Responsiveness=25;active.Align.MaxAngularVelocity=12;active.Align.Parent=root
        local animate=character:FindFirstChild("Animate")
        local folder=animate and animate:FindFirstChild("climb")
        local animation=folder and folder:FindFirstChildOfClass("Animation")
        local animator=humanoid:FindFirstChildOfClass("Animator")
        if animation and animator then pcall(function()
            active.Track=animator:LoadAnimation(animation);active.Track.Looped=true;active.Track:Play(.15)
        end) end
    end
    local active=self.Active;active.Normal=hit.Normal.Unit
    local up=(Vector3.yAxis-active.Normal*active.Normal.Y).Unit
    local right=up:Cross(active.Normal).Unit
    local function down(name) return self.Context.Input:IsKeyDown(Enum.KeyCode[name]) and 1 or 0 end
    local x,y=down("D")-down("A"),down("W")-down("S")
    local tangent=right*x+up*y
    if tangent.Magnitude>1 then tangent=tangent.Unit end
    humanoid.AutoRotate=false;humanoid.PlatformStand=true
    -- Finite adhesion toward a measured wall; no Y anchoring/teleporting.
    active.Drive.VectorVelocity=tangent*self.Speed-active.Normal*4
    active.Drive.MaxAxesForce=Vector3.new(mass*120,mass*(self.Context.Workspace.Gravity+120),mass*120)
    active.Align.CFrame=CFrame.lookAt(root.Position,root.Position-active.Normal,up)
    active.Align.MaxTorque=mass*2500
    if active.Track then pcall(function()active.Track:AdjustSpeed(tangent.Magnitude*self.Speed/12)end) end
end
function Climb:Dispose()
    if self.Closed then return end
    self.Closed=true;self.Enabled=false;self:Release();self.Connection:Disconnect();self.Jump:Disconnect()
end
return Climb

]========]
sources.PosePresets = [========[
-- Static R6 transforms for the existing owned-character physics pose editor.
-- Original three presets retain their source data. Added presets are authored
-- body/limb transforms: no animation IDs, external scripts or asset permissions.
-- Joint/pose hierarchy reference: https://create.roblox.com/docs/reference/engine/classes/Pose
local Pack={}
Pack.Categories={"All","Partner","Original","Standing","Gestures","Seated","Action","Balance","Flight","Rest"}
local limbs={"Torso","Head","Right Arm","Left Arm","Right Leg","Left Leg"}
local swaps={["Right Arm"]="Left Arm",["Left Arm"]="Right Arm",["Right Leg"]="Left Leg",["Left Leg"]="Right Leg"}
local function vec(v)
    if typeof(v)=="Vector3" then return v end
    return Vector3.new(v and v[1] or 0,v and v[2] or 0,v and v[3] or 0)
end
local function finite(n)return type(n)=="number" and n==n and math.abs(n)<math.huge end
function Pack.Validate(pose)
    if pose.Facing~=nil and pose.Facing~="Center" and pose.Facing~="Relative"then return false end
    if pose.HandAnchor~=nil and pose.HandAnchor~="None" and pose.HandAnchor~="Right Hand" and pose.HandAnchor~="Left Hand"then return false end
    if pose.Yaw~=nil and (not finite(pose.Yaw) or math.abs(pose.Yaw)>180)then return false end
    local rotation=pose.Rotation or pose
    for _,name in ipairs(limbs)do
        local v=vec(rotation[name])
        for _,n in ipairs({v.X,v.Y,v.Z})do if not finite(n) or math.abs(n)>180 then return false end end
        if pose.LimbOffsets and pose.LimbOffsets[name]then
            local p=vec(pose.LimbOffsets[name])
            for _,n in ipairs({p.X,p.Y,p.Z})do if not finite(n) or math.abs(n)>5 then return false end end
        end
    end
    local body=pose.BodyOffset and pose.BodyOffset.Position or vec(pose.BodyPos)
    return finite(body.X) and finite(body.Y) and finite(body.Z) and math.abs(body.X)<=10 and body.Y>=-5 and body.Y<=20 and math.abs(body.Z)<=10
end
function Pack.Signature(pose)
    local result={pose.Facing or "Center",tostring(pose.Yaw or 0),pose.HandAnchor or "None"};local function add(v)
        for _,n in ipairs({v.X,v.Y,v.Z})do local rounded=math.round(n*10000);result[#result+1]=tostring(rounded==0 and 0 or rounded)end
    end
    add(pose.BodyOffset and pose.BodyOffset.Position or vec(pose.BodyPos))
    for _,name in ipairs(limbs)do
        local v=vec((pose.Rotation or pose)[name]);local cf=CFrame.Angles(math.rad(v.X),math.rad(v.Y),math.rad(v.Z))
        add(cf.RightVector);add(cf.UpVector);add(cf.LookVector)
        if pose.LimbOffsets and pose.LimbOffsets[name]then add(vec(pose.LimbOffsets[name]))end
    end
    return table.concat(result,",")
end
function Pack.Mirror(pose)
    local r={BodyPos={},Rotation={},LimbOffsets={},Facing=pose.Facing,Yaw=pose.Yaw and -pose.Yaw or nil}
    r.HandAnchor=pose.HandAnchor=="Right Hand" and "Left Hand" or pose.HandAnchor=="Left Hand" and "Right Hand" or pose.HandAnchor
    local body=vec(pose.BodyPos);r.BodyPos={-body.X,body.Y,body.Z}
    for _,name in ipairs(limbs)do
        local value=vec(pose.Rotation[swaps[name] or name])
        r.Rotation[name]=Vector3.new(value.X,-value.Y,-value.Z)
        local offset=pose.LimbOffsets[swaps[name] or name]
        if offset then r.LimbOffsets[name]=Vector3.new(-offset.X,offset.Y,offset.Z)end
    end
    return r
end
function Pack.FacingFrame(centerFrame,position,centerPosition,facing,yaw)
    local direction
    if facing~="Relative"then
        local delta=centerPosition-position
        direction=Vector3.new(delta.X,0,delta.Z)
    end
    if not direction or direction.Magnitude<.0001 then
        local look=centerFrame.LookVector
        direction=Vector3.new(look.X,0,look.Z)
        if direction.Magnitude<.0001 then direction=Vector3.new(0,0,-1)end
    end
    yaw=finite(yaw) and math.clamp(yaw,-180,180) or 0
    return CFrame.lookAt(position,position+direction)*CFrame.Angles(0,math.rad(yaw),0)
end
function Pack.BodyGoal(centerFrame,character,bodyOffset,anchor)
    local position=(centerFrame*bodyOffset).Position
    if not character or (anchor~="Right Hand" and anchor~="Left Hand")then return position end
    local side=anchor=="Right Hand" and 1 or -1
    local arm=character:FindFirstChild(side==1 and "Right Arm" or "Left Arm")
    local torso=character:FindFirstChild("Torso")
    if not arm or not torso or not arm:IsA("BasePart") or not torso:IsA("BasePart")then return position end
    local size=arm.Size or Vector3.new(1,2,1);local torsoSize=torso.Size or Vector3.new(2,2,1)
    local hand=(arm.CFrame*CFrame.new(0,-size.Y/2,0)).Position
    local neutral=(centerFrame*CFrame.new(side*(torsoSize.X+size.X)/2,torsoSize.Y/2-size.Y,0)).Position
    local delta=hand-neutral
    -- Follow the real animated hand with finite travel; never teleport limbs
    -- or install an extra character force alongside the existing pose mover.
    if delta.Magnitude>3 then delta=delta.Unit*3 end
    return position+delta
end
function Pack.Build(original,offsets)
    local poses,metadata,seen={},{},{}
    for name,pose in pairs(original)do
        poses[name]=pose;metadata[name]="Original";seen[Pack.Signature(pose)]=true
