sources.PacketGuard = [========[
-- Client callback filter for the game's ExtendGrabLine/CreateGrabLine remotes.
-- Runs AFTER network delivery/decoding: it stops the handler work (string ops,
-- line rebuilds, notifications) that a packet flood causes, not the bandwidth.
-- Two capture paths per handler:
--   relay : connection:Disable() + our own connection that forwards allowed calls
--   hook  : hookfunction(handler) when Disable/Enable is missing (Lua closures only)
-- Connection API: https://docs.sunc.io/Signals/Connection/
local Guard={};Guard.__index=Guard
-- {MaxBytes, Rate/s, MaxInFlight, BurstSeconds, MaxCoord}
local profiles={Strict={1024,30,16,.5,50000},Balanced={4096,60,32,1,100000}}
local kMuteSeconds=5      -- sender muted after flooding
local kMuteStrikes=3      -- size/shape rejects inside kStrikeWindow that trigger a mute
local kStrikeWindow=1
local function read(object,key)
    local ok,value=pcall(function()return object[key]end)
    if ok then return value end
    return nil
end
local function finite(n)return type(n)=="number" and n==n and math.abs(n)<math.huge end
local function safeDisconnect(c)if c then pcall(function()c:Disconnect()end)end end
local function isPlayer(v)return typeof(v)=="Instance" and v:IsA("Player")end
function Guard.Install(context)
    local self=setmetatable({Context=context,Enabled=false,Epoch=0,States={},RelayFunctions={},Hooks={},HookedFunctions={},Dormant={},
        MaxBytes=4096,Rate=120,MaxInFlight=64,MaxCoord=100000,InFlight=0,
        Senders=setmetatable({},{__mode="k"}),Strikes=setmetatable({},{__mode="k"}),Muted=setmetatable({},{__mode="k"}),
        Profile="Custom",Counters={Received=0,Allowed=0,BlockedSize=0,BlockedShape=0,BlockedRate=0,BlockedBusy=0,BlockedMuted=0,CallbackErrors=0},
        Channels={EGL={Received=0,Allowed=0,Blocked=0},CGL={Received=0,Allowed=0,Blocked=0},GEN={Received=0,Allowed=0,Blocked=0}},
        GenMaxBytes=65536,
        Captured=0,CapturedOwn=0,CapturedHook=0,Unsupported=0,Status="Disabled"},Guard)
    if context.Player and context.Player.CharacterAdded then
        self.CharacterConnection=context.Player.CharacterAdded:Connect(function()
            if self.Enabled then self.RefreshAt=self:Now()+.75 end
        end)
    end
    return self
end
function Guard:Now()return (self.Context.Clock or os.clock)()end
function Guard:SetProfile(name)
    if name~="Custom" and not profiles[name]then return false end
    self.Profile=name;return true
end
function Guard:Limits()
    local p=profiles[self.Profile]
    if p then return p[1],p[2],p[3],p[4],true,p[5] end
    return self.MaxBytes,self.Rate,self.MaxInFlight,2,false,self.MaxCoord
end
function Guard:Configure(key,value)
    if not finite(value)then return false end
    if key=="MaxBytes"then self.MaxBytes=math.clamp(math.floor(value),512,65536)
    elseif key=="Rate"then self.Rate=math.clamp(math.floor(value),30,1000)
    elseif key=="MaxInFlight"then self.MaxInFlight=math.clamp(math.floor(value),16,256)
    elseif key=="MaxCoord"then self.MaxCoord=math.clamp(math.floor(value),5000,1e7)
    elseif key=="GenMaxBytes"then self.GenMaxBytes=math.clamp(math.floor(value),4096,1048576)
    else return false end
    return true
end
function Guard:Strike(sender)
    if not sender then return end
    local now=self:Now()
    local s=self.Strikes[sender]
    if not s or now-s.At>kStrikeWindow then s={N=0,At=now};self.Strikes[sender]=s end
    s.N+=1
    if s.N>=kMuteStrikes then self.Muted[sender]=now+kMuteSeconds;self.Strikes[sender]=nil end
end
function Guard:Reject(state,reason,sender)
    self.Counters["Blocked"..reason]+=1
    local channel=self.Channels[state.Channel]
    if channel then channel.Blocked+=1 end
    if reason=="Size" or reason=="Shape" then self:Strike(sender)end
    return false
end
function Guard:AdmitRate(state,sender)
    local _,rate,_,burstSeconds=self:Limits()
    local burst=math.max(1,rate*burstSeconds)
    local bucket
    if sender then bucket=self.Senders[sender]else bucket=self.DefaultBucket end
    local now=self:Now()
    if not bucket then
        bucket={Tokens=burst,At=now}
        if sender then self.Senders[sender]=bucket else self.DefaultBucket=bucket end
    end
    bucket.Tokens=math.min(burst,bucket.Tokens+math.max(0,now-bucket.At)*rate);bucket.At=now
    local total=self.GlobalBucket
    if not total then total={Tokens=burst*2,At=now};self.GlobalBucket=total end
    total.Tokens=math.min(burst*2,total.Tokens+math.max(0,now-total.At)*rate*2);total.At=now
    if bucket.Tokens<1 or total.Tokens<1 then return self:Reject(state,"Rate",sender)end
    bucket.Tokens-=1;total.Tokens-=1
    return true
end
function Guard:CheckValue(value,budget,depth,path)
    budget.Nodes+=1
    if budget.Nodes>256 or depth>4 then return false,"Shape"end
    local kind=typeof(value)
    if kind=="string"then local maxBytes=budget.MaxBytes or self:Limits();budget.Bytes+=#value;return budget.Bytes<=maxBytes,"Size"
    elseif kind=="number"then return finite(value),"Shape"
    elseif kind=="Vector3" or kind=="Vector2"then
        return finite(value.X) and finite(value.Y) and (kind=="Vector2" or finite(value.Z)),"Shape"
    elseif kind=="CFrame"then
        for _,v in ipairs({value.Position,value.RightVector,value.UpVector,value.LookVector})do
            if not finite(v.X) or not finite(v.Y) or not finite(v.Z)then return false,"Shape"end
        end
        return true
    elseif kind=="table"then
        if path[value]then return false,"Shape"end
        path[value]=true;local entries=0
        for key,item in next,value do
            entries+=1;if entries>128 then path[value]=nil;return false,"Shape"end
            local ok,reason=self:CheckValue(key,budget,depth+1,path)
            if ok then ok,reason=self:CheckValue(item,budget,depth+1,path)end
            if not ok then path[value]=nil;return false,reason end
        end
        path[value]=nil
    end
    return true
end
-- Synchronous verdict; returns allowed, packedArgs
function Guard:Allow(state,...)
    local n=select("#",...)
    local first=...
    local sender=isPlayer(first) and first or nil
    -- Muted flooders are dropped before any other work.
    if sender then
        local untilT=self.Muted[sender]
        if untilT then
            if self:Now()<untilT then
                self.Counters.BlockedMuted+=1
                local channel=self.Channels[state.Channel];if channel then channel.Blocked+=1 end
                return false
            end
            self.Muted[sender]=nil
        end
    end
    -- O(1) size precheck on the top-level args: a multi-MB string is rejected
    -- before rate accounting, packing or any traversal.
    local maxBytes,_,maxInFlight,_,protocol,maxCoord=self:Limits()
    -- Unknown remotes may legitimately carry larger-but-sane payloads; only a
    -- flood-sized string (>GenMaxBytes, e.g. a multi-MB packet) is dropped there.
    local sizeCap=(state.Channel=="GEN") and math.max(maxBytes,self.GenMaxBytes) or maxBytes
    if n>16 then return self:Reject(state,"Shape",sender)end
    for i=1,n do
        local v=select(i,...)
        if type(v)=="string" and #v>sizeCap then return self:Reject(state,"Size",sender)end
    end
    if not self:AdmitRate(state,sender)then return false end
    if state.Mode=="relay" and self.InFlight+#state.Callbacks>maxInFlight then return self:Reject(state,"Busy",sender)end
    -- Strict argument shapes only for the two known grab channels. Unknown
    -- remotes from other scripts get the generic size/rate/flood guard, never
    -- a hardcoded arg-shape rule that would wrongly reject their normal calls.
    if protocol and (state.Channel=="EGL" or state.Channel=="CGL")then
        local _,part,transform=...
        if not sender then return self:Reject(state,"Shape")end
        if state.Channel=="EGL"then
            if n~=2 or not finite(part)then return self:Reject(state,"Shape",sender)end
        elseif n~=3 or typeof(part)~="Instance" or not part:IsA("BasePart") or typeof(transform)~="CFrame"then
            return self:Reject(state,"Shape",sender)
        end
    end
    -- Grab lines aimed at absurd coordinates are line-lag, never real grabs.
    if state.Channel=="CGL"then
        local transform=select(3,...)
        if typeof(transform)=="CFrame" then
            local p=transform.Position
            if not finite(p.X) or not finite(p.Y) or not finite(p.Z) or p.Magnitude>maxCoord then
                return self:Reject(state,"Shape",sender)
            end
        end
    end
    local args=table.pack(...);local budget={Bytes=0,Nodes=0,MaxBytes=sizeCap}
    for i=1,args.n do
        local ok,allowed,reason=pcall(self.CheckValue,self,args[i],budget,0,{})
        if not ok or not allowed then
            return self:Reject(state,ok and reason=="Size" and "Size" or "Shape",sender)
        end
    end
    self.Counters.Allowed+=1
    local channel=self.Channels[state.Channel]
    if channel then channel.Allowed+=1 end
    return true,args
end
function Guard:Usable(connection)
    return read(connection,"Enabled")==true and read(connection,"ForeignState")~=true
        and type(read(connection,"Function"))=="function" and type(read(connection,"Disable"))=="function"
        and type(read(connection,"Enable"))=="function"
end
function Guard:Hookable(connection)
    local ctx=self.Context
    if type(ctx.HookFunction)~="function" then return false end
    if read(connection,"ForeignState")==true then return false end
    local fn=read(connection,"Function")
    if type(fn)~="function" or self.RelayFunctions[fn] or self.HookedFunctions[fn] then return false end
    if type(ctx.IsLClosure)=="function" then
        local ok,isL=pcall(ctx.IsLClosure,fn)
        if not ok or not isL then return false end
    end
    return true
end
function Guard:Unbind()
    for _,state in ipairs(self.States)do safeDisconnect(state.Relay)end
    for _,state in ipairs(self.States)do
        for _,record in ipairs(state.Callbacks)do
            if read(record.Connection,"Connected")~=false then pcall(function()record.Connection:Enable()end)end
        end
    end
    -- Hooked handlers become pass-through until restored, so an epoch bump alone
    -- is already safe; restore when the executor supports it.
    local ctx=self.Context
    for _,h in ipairs(self.Hooks)do
        h.Live=false
        local restored=false
        if type(ctx.RestoreFunction)=="function" then restored=pcall(ctx.RestoreFunction,h.Function)
        elseif type(ctx.HookFunction)=="function" and h.Original then restored=pcall(ctx.HookFunction,h.Function,h.Original)end
        -- a hook that could not be removed stays as a pass-through and is reused on rebind
        if not restored then self.Dormant[h.Function]=h end
        self.HookedFunctions[h.Function]=nil
    end
    self.States={};self.RelayFunctions={};self.Hooks={}
    self.Captured,self.CapturedOwn,self.CapturedHook,self.Unsupported=0,0,0,0
end
function Guard:HookHandler(state,connection)
    local fn=read(connection,"Function")
    local h=self.Dormant[fn]
    if h then
        self.Dormant[fn]=nil;h.State=state;h.Live=true
    else
        h={Function=fn,Live=true,State=state}
        local guard=self
        local original
        local ok=pcall(function()
            original=self.Context.HookFunction(fn,function(...)
                if h.Live and not guard.Closed and guard.Enabled then
                    guard.Counters.Received+=1
                    guard.Channels[h.State.Channel].Received+=1
                    local allowed=guard:Allow(h.State,...)
                    if not allowed then return end
                end
                return original(...)
            end)
        end)
        if not ok or type(original)~="function" then return false end
        h.Original=original
    end
    self.Hooks[#self.Hooks+1]=h
    self.HookedFunctions[fn]=true
    self.CapturedHook+=1;self.Captured+=1
    if self.Context.OwnFunctions and self.Context.OwnFunctions[fn]then self.CapturedOwn+=1 end
    return true
end
function Guard:Bind()
    local get=self.Context.GetConnections
    if type(get)~="function"then return false,"Executor does not expose getconnections; client filter unavailable",false end
    local remotes=self.Context.Remotes();local seen={}
    local epoch=self.Epoch
    for _,remote in pairs(remotes)do
        if remote and remote.Parent and not seen[remote]then
            seen[remote]=true
            local signal=remote.OnClientEvent
            local ok,connections=pcall(get,signal)
            if not ok or type(connections)~="table"then self.Unsupported+=1;continue end
            local channel
            if remote.Name=="CreateGrabLine"then channel="CGL"
            elseif remote.Name=="ExtendGrabLine"then channel="EGL"
            else channel="GEN" end
            local state={Remote=remote,Callbacks={},Channel=channel,Mode="relay"}
            local hookState={Remote=remote,Callbacks={},Channel=channel,Mode="hook"}
            self.States[#self.States+1]=state
            for index,connection in ipairs(connections)do
                if index>128 then self.Unsupported+=#connections-128;break end
                local callback=read(connection,"Function")
                if self.RelayFunctions[callback] then continue end
                local captured=false
                if self:Usable(connection) and #state.Callbacks<64 then
                    local disabled=pcall(function()connection:Disable()end)
                    if disabled and read(connection,"Enabled")==false then
                        state.Callbacks[#state.Callbacks+1]={Connection=connection,Function=callback};self.Captured+=1
                        if self.Context.OwnFunctions and self.Context.OwnFunctions[callback]then self.CapturedOwn+=1 end
                        captured=true
                    else
                        pcall(function()connection:Enable()end)
                    end
                end
                if not captured and self:Hookable(connection) then
                    captured=self:HookHandler(hookState,connection)
                end
                if not captured and read(connection,"Enabled")~=false then self.Unsupported+=1 end
            end
            if #state.Callbacks>0 then
                local relay=function(...)
                    if self.Closed or not self.Enabled or self.Epoch~=epoch then return end
                    self.Counters.Received+=1
                    self.Channels[state.Channel].Received+=1
                    local allowed,args=self:Allow(state,...)
                    if not allowed then return end
                    self.InFlight+=#state.Callbacks
                    for _,record in ipairs(state.Callbacks)do
                        local started=pcall(self.Context.Spawn or task.spawn,function()
                            if not self.Closed and self.Enabled and self.Epoch==epoch and read(record.Connection,"Connected")~=false
                                and type(read(record.Connection,"Function"))=="function"then
                                local success=pcall(record.Function,table.unpack(args,1,args.n))
                                if not success then self.Counters.CallbackErrors+=1 end
                            end
                            self.InFlight-=1
                        end)
                        if not started then self.InFlight-=1;self.Counters.CallbackErrors+=1 end
                    end
                end
                self.RelayFunctions[relay]=true
                state.Relay=signal:Connect(relay)
            end
        end
    end
    -- Nothing to capture yet is retryable: the game may connect its handlers later.
    if self.Captured==0 then return false,"Waiting for Grab event handlers (none accessible yet)",true end
    return true
end
function Guard:NeedsRefresh()
    if self.Captured==0 then return true end
    for _,state in ipairs(self.States)do
        if not state.Remote.Parent then return true end
        local ok,connections=pcall(self.Context.GetConnections,state.Remote.OnClientEvent)
        if ok and type(connections)=="table"then
            for index,connection in ipairs(connections)do
                if index>128 then break end
                local fn=read(connection,"Function")
                if not self.RelayFunctions[fn] and not self.HookedFunctions[fn] then
                    if self:Usable(connection) or self:Hookable(connection) then return true end
                end
            end
        end
    end
    return false
end
function Guard:Refresh()
    if not self.Enabled or self.Closed then return false end
    self.Epoch+=1;self:Unbind()
    local ok,ready,message,retry=pcall(self.Bind,self)
    if not ok or not ready then
        if ok and retry then
            -- stay enabled and keep scanning instead of switching the toggle off
            self.Status=message;self.LastFailure=nil
            self.NextScan=self:Now()+1
            return true
        end
        self:SetEnabled(false)
        self.Status=not ok and "Filter setup failed: "..tostring(ready) or message
        self.LastFailure=self.Status
        return false,self.Status
    end
    if self.Unsupported>0 then self.Status="Partial client filter: some callbacks are inaccessible"
    elseif self.CapturedHook>0 then self.Status="Client callback filter active (hook fallback)"
    else self.Status="Client callback filter active" end
    if self.Context.OwnFunctions and self.Captured==self.CapturedOwn then
        self.Status="Only Astral callbacks captured; game coverage unverified"
    end
    self.LastFailure=nil
    self.NextScan=self:Now()+2
    return true
end
function Guard:SetEnabled(enabled)
    enabled=enabled==true and not self.Closed
    if self.Enabled==enabled then return true end
    self.Enabled=enabled;self.Epoch+=1
    safeDisconnect(self.Heartbeat);self.Heartbeat=nil
    if not enabled then
        self:Unbind();self.Senders=setmetatable({},{__mode="k"});self.DefaultBucket=nil;self.GlobalBucket=nil
        self.Strikes=setmetatable({},{__mode="k"});self.Muted=setmetatable({},{__mode="k"})
        self.Status="Disabled";return true
    end
    local ok,message=self:Refresh()
    if not ok then return false,message end
    self.Heartbeat=self.Context.RunService.Heartbeat:Connect(function()
        if not self.Enabled then return end
        local now=self:Now()
        if self.RefreshAt and now>=self.RefreshAt then self.RefreshAt=nil;self:Refresh()
        elseif now>=(self.NextScan or 0)then
            self.NextScan=now+(self.Captured==0 and 1 or 2)
            if self:NeedsRefresh()then self:Refresh()end
        end
    end)
    return true
end
function Guard:MutedCount()
    local n,now=0,self:Now()
    for _,t in pairs(self.Muted)do if t>now then n+=1 end end
    return n
end
function Guard:Describe()
    local c=self.Counters
    local bytes,rate,pending=self:Limits()
    local text=("%s\n%s: %d B | %d/s | pending %d/%d\nCaptured: Astral %d, other %d (hooked %d), inaccessible %d\nEGL %d/%d | CGL %d/%d | other %d/%d | rejected %d | muted now %d"):format(
        self.Status,self.Profile,bytes,rate,self.InFlight,pending,self.CapturedOwn,self.Captured-self.CapturedOwn,self.CapturedHook,self.Unsupported,
        self.Channels.EGL.Allowed,self.Channels.EGL.Received,self.Channels.CGL.Allowed,self.Channels.CGL.Received,
        self.Channels.GEN.Allowed,self.Channels.GEN.Received,
        c.BlockedSize+c.BlockedShape+c.BlockedRate+c.BlockedBusy+c.BlockedMuted,self:MutedCount())
    if c.CallbackErrors>0 then text..=" | handler errors "..c.CallbackErrors end
    if self.LastFailure and self.Status~=self.LastFailure then text..="\n"..self.LastFailure end
    return text
end
function Guard:Dispose()
    if self.Closed then return end
    self:SetEnabled(false);self.Closed=true
    safeDisconnect(self.CharacterConnection)
end
return Guard

