local aliases={Blobman="CreatureBlobman",Tractor="TractorGreen",["Tractor [Invisible]"]="TractorGreen",
    ["Train [Invisible]"]="Train",["Sleigh [Invisible]"]="SantaSleigh",Sleigh="SantaSleigh"}
function Decor.ItemImage(value)
    if typeof(value)=="Instance"then value=value.Name end
    if type(value)~="string"then return nil end
    return Catalog.Items[aliases[value]or value]
end
-- A semantic fallback may decorate actions, never unknown item/mode names.
function Decor.ValueIcon(value)
    if typeof(value)=="Instance"then value=value.Name end
    return type(value)=="string"and exact[value]or nil
end
function Decor.BlockedTab(name)
    name=tostring(name):gsub("<[^>]*>",""):lower()
    return name=="settings"or name=="keybinds"
end
local words={{"anti packet","network"},{"anti burn","flame"},{"anti poison","flask-conical"},{"head","user-round"},{"torso","shirt"},{"leg","footprints"},{"arm","hand"},{"wing","feather"},{"sparkler","sparkles"},{"forms","shapes"},{"player","user-round"},{"fling","tornado"},{"slide","move-right"},{"anti explosion","shield-alert"},{"anti kick","shield-check"},{"anti grab","hand"},{"anti void","arrow-up-from-line"},{"anti lag","zap"},{"network","network"},{"trigger","mouse-pointer-click"},{"silent","crosshair"},{"noclip","scan-line"},{"gravity","orbit"},{"height","arrow-up-down"},{"distance","ruler"},{"transparen","blend"},{"offset","move-3d"},{"rotation","rotate-cw"},{"size","maximize"},{"scale","scaling"},{"duration","timer"},{"delay","clock"},{"volume","volume-2"},{"material","layers"},{"texture","image"},{"font","type"},{"cursor","mouse-pointer"},{"key","keyboard"},{"limit","list-filter"},{"mode","sliders-horizontal"},{"method","wrench"},{"anti","shield"},{"packet","network"},{"ragdoll","person-standing"},{"teleport","map-pin"},{"flight","feather"},
    {"fly","feather"},{"speed","gauge"},{"jump","arrow-up"},{"spin","refresh-cw"},{"freeze","snowflake"},{"camera","camera"},
    {"aim","crosshair"},{"snow","snowflake"},{"rocket","rocket"},{"invis","eye-off"},{"delete","trash-2"},{"break","hammer"},
    {"grab","hand"},{"loop","repeat-2"},{"spectate","eye"},{"position","move-3d"},{"color","palette"},{"music","music"},
    {"sound","volume-2"},{"water","waves-horizontal"},{"light","sun"},{"save","save"},{"load","download"},{"unload","power"}}
local byId={PlayerHighlightEnabled="highlighter",NameESPEnabled="type",PCLDNameEnabled="tag",
    LookFigures="person-standing",SparklerFormsEnabled="astral-stick-spark",AstralDroneEnabled="plane"}
function Decor.Icon(value,fallback,context,id)
    if id and byId[id]then return byId[id]end
    if type(value)~="string"then return fallback end
    local text=value:gsub("<[^>]*>",""):gsub("%s*%[astral%]%s*$","")
    if exact[text]then return exact[text]end
    local lower=text:lower()
    if lower=="enabled"or lower=="toggle"or lower=="disable"or lower=="type"or lower=="speed"then
        local contextual=context and Decor.Icon(context)
        if contextual then return contextual end
        return lower=="type"and "box"or "power"
    end
    for _,entry in ipairs(words)do if lower:find(entry[1],1,true)then return entry[2]end end
    return fallback
end
return Decor

