sources.FunctionGlyphs = [========[
-- Small code-drawn glyphs in the same 24-unit outline style as the existing UI.
-- No downloaded files, Unicode font dependencies, or generated image assets.
local Glyphs={}
Glyphs.Paths={
    ["astral-ladder"]={{{6,3},{6,21}},{{18,3},{18,21}},{{6,6},{18,6}},{{6,11},{18,11}},{{6,16},{18,16}},{{6,21},{18,21}}},
    ["astral-ladder-speed"]={{{3,3},{3,21}},{{12,3},{12,21}},{{3,6},{12,6}},{{3,11},{12,11}},{{3,16},{12,16}},{{17,19},{17,6}},{{14,9},{17,6},{20,9}}},
    ["astral-slide-tp"]={{{3,18},{6,18}},{{9,18},{12,18}},{{15,18},{21,18}},{{17,14},{21,18},{17,22}},{{4,12},{4,5},{10,5}}},
    ["astral-freeze-pcld"]={{{4,6},{20,6},{20,20},{4,20},{4,6}},{{8,3},{16,3}},{{12,9},{12,17}},{{8,11},{16,15}},{{8,15},{16,11}}},
    ["astral-stick-spark"]={{{4,21},{14,11}},{{15,2},{15,6}},{{20,5},{18,7}},{{23,10},{19,10}},{{14,10},{16,12}},{{10,4},{12,6}}},
    ["astral-reattach"]={{{7,9},{4,9},{4,4},{9,4}},{{4,4},{10,10}},{{17,15},{20,15},{20,20},{15,20}},{{20,20},{14,14}},{{9,15},{7,13},{7,11},{10,8},{12,8},{14,10}},{{10,14},{12,16},{14,16},{17,13},{17,11},{15,9}}},
    ["astral-coconuts"]={{{3,10},{4,6},{8,4},{12,6},{13,10},{11,14},{7,15},{3,12},{3,10}},{{13,8},{17,7},{21,10},{22,14},{20,18},{16,20},{12,18},{10,15}},{{7,7},{7,8}},{{10,8},{10,9}}},
    ["astral-orbit-rods"]={{{3,9},{7,5},{17,5},{21,9},{21,15},{17,19},{7,19},{3,15},{3,9}},{{9,12},{15,12}},{{12,9},{12,15}}},
    ["astral-crown-rods"]={{{3,7},{7,13},{12,4},{17,13},{21,7},{19,20},{5,20},{3,7}}},
}
function Glyphs.Get(name)
    local paths=Glyphs.Paths[name]
    if not paths then return nil end
    return {Url="",ImageRectOffset=Vector2.zero,ImageRectSize=Vector2.zero,Draw=function(image)
        image.Image=""
        local old=image:FindFirstChild("AstralFunctionGlyph");if old then old:Destroy()end
        local canvas=Instance.new("Frame");canvas.Name="AstralFunctionGlyph"
        canvas.BackgroundTransparency=1;canvas.Size=UDim2.fromScale(1,1);canvas.Parent=image
        local aspect=Instance.new("UIAspectRatioConstraint");aspect.AspectRatio=1;aspect.Parent=canvas
        local lines={}
        for _,path in ipairs(paths)do
            for i=2,#path do
                local a,b=path[i-1],path[i];local dx,dy=b[1]-a[1],b[2]-a[2]
                local line=Instance.new("Frame");line.BorderSizePixel=0;line.AnchorPoint=Vector2.new(.5,.5)
                line.Position=UDim2.fromScale((a[1]+b[1])/48,(a[2]+b[2])/48)
                line.Size=UDim2.fromScale(math.sqrt(dx*dx+dy*dy)/24,1.7/24)
                line.Rotation=math.deg(math.atan2(dy,dx));line.Parent=canvas
                local corner=Instance.new("UICorner");corner.CornerRadius=UDim.new(1,0);corner.Parent=line
                lines[#lines+1]=line
            end
        end
        local function update()
            for _,line in ipairs(lines)do line.BackgroundColor3=image.ImageColor3;line.BackgroundTransparency=image.ImageTransparency end
        end
        local color=image:GetPropertyChangedSignal("ImageColor3"):Connect(update)
        local transparency=image:GetPropertyChangedSignal("ImageTransparency"):Connect(update)
        canvas.Destroying:Connect(function()color:Disconnect();transparency:Disconnect()end)
        update()
    end}
end
return Glyphs

