sources.ProvidedPhotos = [========[
local Photos={};local cache={}
local encoded={
House="",
Train="",
}
local alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function decode(value)
 local map={};for i=1,#alphabet do map[alphabet:byte(i)]=i-1 end
 local result={}
 for i=1,#value,4 do
  local a,b,c,d=value:byte(i,i+3);local n=map[a]*262144+map[b]*4096+(map[c]or 0)*64+(map[d]or 0)
  result[#result+1]=string.char(math.floor(n/65536)%256)
  if c~=61 then result[#result+1]=string.char(math.floor(n/256)%256)end
  if d~=61 then result[#result+1]=string.char(n%256)end
 end
 return table.concat(result)
end
function Photos.Get(name)
 local key=tostring(name):lower():gsub("[%s_]","")
 key=key:find("train",1,true)and "Train"or (key:find("haunt",1,true)or key:find("mansion",1,true))and "House"or nil
 if not key then return end
 if cache[key]then return cache[key]end
 local asset=getcustomasset or getsynasset
 if type(writefile)~="function"or type(asset)~="function"then return end
 local ok,result=pcall(function()
  local path="astral_"..key:lower().."_photo.png";writefile(path,decode(encoded[key]));return asset(path)
 end)
 if ok and type(result)=="string"then cache[key]=result;return result end
end
Photos.Decode=decode
return Photos

