sources.FreezePCLD = [========[
local Freeze={};Freeze.__index=Freeze
function Freeze.Install(context)
    local self=setmetatable({Context=context,States={},Enabled=false,Status="Disabled",Elapsed=0},Freeze)
    self.Connection=context.RunService.Heartbeat:Connect(function(dt)self.Elapsed+=dt;if self.Elapsed>=.1 then self.Elapsed=0;self:Step()end end)
    return self
end
function Freeze:Clear(player)local state=self.States[player];if state then state.Mover:Destroy();self.States[player]=nil end end
function Freeze:SetEnabled(value)self.Enabled=value==true and not self.Closed;if not self.Enabled then for p in pairs(self.States)do self:Clear(p)end;self.Status="Disabled"end end
function Freeze:Step()
    if not self.Enabled or self.Closed then return end
    local active=self.Context.Targets();local used={};local held,skipped=0,0
    for _,player in ipairs(active)do
        local part=self.Context.Detector(player)
        if part and part.Parent and not part.Anchored and (not part.AssemblyRootPart or part.AssemblyRootPart==part)
            and self.Context.Owned(part)then
            used[player]=true;local state=self.States[player]
            if state and state.Part~=part then self:Clear(player);state=nil end
            if not state then
                local mover=Instance.new("BodyPosition");mover.Name="AstralFreezePCLD";mover.MaxForce=Vector3.new(1e6,1e6,1e6)
                mover.P=10000;mover.D=1250;mover.Position=part.Position;mover.Parent=part
                self.States[player]={Part=part,Mover=mover}
            end
            held+=1
        else skipped+=1 end
    end
    for player in pairs(self.States)do if not used[player]then self:Clear(player)end end
    self.Status=("Frozen owned detectors: %d | unavailable/server-controlled: %d"):format(held,skipped)
end
function Freeze:Dispose()self:SetEnabled(false);self.Closed=true;self.Connection:Disconnect()end
return Freeze

