do
local RunService = game:GetService("RunService")
local localPlayer = game:GetService("Players").LocalPlayer

local desync = {
enabled = false,
loc = CFrame.new(),
isOffsetted = false,
_requestActive = false,
_targetCFFunc = nil,
_requestTimeout = 5,
_requestStartTime = 0,
_spinConn = nil,
serverCF = nil,
}

_DS_startSpin = function()
if desync._spinConn then
return
end

desync._spinConn = bridge:TrackConnection(RunService.Heartbeat:Connect(function()
local character = localPlayer.Character
character = character and character:FindFirstChild("HumanoidRootPart")

if character and desync.enabled then
character.AssemblyAngularVelocity = Vector3.new(0, 0.01, 0)
end
end))
end

_DS_stopSpin = function()
bridge:TrackThread(task.delay(5, function()
if desync._spinConn and not desync.enabled then
desync._spinConn:Disconnect()
desync._spinConn = nil
end
end))
end

desync.GetServerCFrame = function(arg)
local character = localPlayer.Character

if character then
character = character:FindFirstChild("saviHRP") or character:FindFirstChild("HumanoidRootPart")
end

if not character then
return nil
end

if arg.enabled then
if arg._requestActive and arg._targetCFFunc then
local ok, result = pcall(arg._targetCFFunc)
if ok and typeof(result) == "CFrame" then
return result
end
end

if arg.serverCF and typeof(arg.serverCF) == "CFrame" then
return arg.serverCF
end
end

return character.CFrame
end

desync.RequestDesync = function(arg, targetCFFunc, requestTimeout)
if arg._requestActive then
return false
end
arg._requestActive = true
arg._targetCFFunc = targetCFFunc
arg._requestTimeout = requestTimeout or 5
arg._requestStartTime = tick()

if not arg.enabled then
arg.enabled = true
_DS_startSpin()
local character = localPlayer.Character
character = character and character:FindFirstChild("HumanoidRootPart")

if character then
arg.loc = character.CFrame
arg.isOffsetted = false
end
end

return true
end

desync.CancelRequest = function(arg)
if not arg._requestActive then
return
end
arg._requestActive = false
arg._targetCFFunc = nil
arg.serverCF = nil
local character = localPlayer.Character
character = character and character:FindFirstChild("HumanoidRootPart")

if character and arg.isOffsetted then
character.CFrame = arg.loc
end

arg.isOffsetted = false
arg.enabled = false
_DS_stopSpin()
end

desync.IsAvailable = function(arg)
return not arg._requestActive
end

bridge:TrackConnection(RunService.Stepped:Connect(function()
if desync.enabled and desync.isOffsetted and localPlayer.Character then
local humanoidRootPart = localPlayer.Character:FindFirstChild("HumanoidRootPart")

if humanoidRootPart and desync.loc then
humanoidRootPart.CFrame = desync.loc
desync.isOffsetted = false
end
end
end))

bridge:BindRender(RunService, "Astral/Extra/_GlobalDesyncCamFix", 0, function()
if desync.enabled and desync.isOffsetted and localPlayer.Character then
local humanoidRootPart = localPlayer.Character:FindFirstChild("HumanoidRootPart")

if humanoidRootPart and desync.loc then
humanoidRootPart.CFrame = desync.loc
desync.isOffsetted = false
end
end
end)

bridge:TrackConnection(RunService.Heartbeat:Connect(function()
if not desync.enabled or not localPlayer.Character then
return
end
local humanoidRootPart = localPlayer.Character:FindFirstChild("HumanoidRootPart")
if not humanoidRootPart then
return
end
desync.loc = humanoidRootPart.CFrame

if desync._requestActive and desync._requestStartTime then
local requestStartTime = desync._requestStartTime
if desync._requestTimeout <= tick() - requestStartTime then
desync:CancelRequest()
return
end
end

if desync._requestActive and desync._targetCFFunc then
local ok, cFrame = pcall(desync._targetCFFunc)

if ok and cFrame then
humanoidRootPart.CFrame = cFrame
desync.serverCF = cFrame
desync.isOffsetted = true
end
end
end))

bridge:TrackConnection(localPlayer.CharacterAdded:Connect(function(character)
task.wait(0.1)
desync.loc = character:WaitForChild("HumanoidRootPart").CFrame
desync.isOffsetted = false
desync.serverCF = nil

if desync._requestActive then
desync._requestActive = false
desync._targetCFFunc = nil
desync.enabled = false
_DS_stopSpin()
end
end))

getgenv()._DESYNC = desync
end
