_lerpNum = function(arg, arg2, arg3)
return arg + (arg2 - arg) * arg3
end

_lerpColor = function(arg, arg2, arg3)
local clamp = math.clamp
local n34 = arg.B + (arg2.B - arg.B) * arg3
return Color3.new(math.clamp(arg.R + (arg2.R - arg.R) * arg3, 0, 1), math.clamp(arg.G + (arg2.G - arg.G) * arg3, 0, 1), clamp(n34, 0, 1))
end

