]====]
local requireModule = ...
local Aim = requireModule("AimSupport")
local FeatureHost = {}
FeatureHost.__index = FeatureHost
FeatureHost.Aim = Aim

local function plain(value)
    return tostring(value or ""):gsub("<[^>]*>", "")
end

local function copy(value)
    local result = {}
    for key, item in pairs(value or {}) do result[key] = item end
    return result
end

local tabMap = {
    Home = "Home", Player = "Player", Defence = "Invincibility",
    Miscellaneous = "Combat", Combat = "Combat", Target = "Internal",
    Blobman = "Internal", Pose = "Internal", Aim = "Aim",
    ESP = "Visual", Visual = "Visual", AimTrainer = "Player",
    Whitelist = "Internal", Settings = "Settings",
}

-- These are alternatives from the two inputs, not new gameplay methods.
local equivalents = {
    DefAntiGrab = {"AntiGrab", "GucciAntiGrab"}, DefAntiGrabGucci = {"AntiGrab", "GucciAntiGrab"},
    DefAntiRagdoll = {"AntiGrab", "GucciAntiGrab"},
    DefAntiNetOwner = {"AntiKick", "AntiKick2"}, DefAntiKick = {"AntiKick", "AntiKick2"},
    DefAntiLag = {"AntiLag"}, DefAutoAntiLag = {"AutoAntiLag"},
    DefAntiPoison = {"AntiPoison"}, DefAntiBurn = {"AntiBurn"},
    DefAntiBlobman = {"AntiBlobman"}, DefAntiVoid = {"AntiVoid"},
    DefAntiSticky = {"AntiSticky"}, DefAntiStickyLag = {"AntiInputLag"},
    DefAntiExplosion = {"AntiExplosion"}, DefAntiPaint = {"AntiPaint"},
    DefAutoReset = {"AutoReset"}, DefAntiBanana = {"AntiBanana"},
    DefLoopReset = {"AutoReset"}, DefBreakPCLD = {"AntiKick", "AntiKick2"},
    OceanWalk = {"WaterWalk"},
    WalkspeedT = {"WalkspeedT"}, JumpPowerT = {"JumpPowerT"}, SpinT = {"SpinT"},
    FlyToggle = {"FlyT", "DesyncT", "LoopTP", "LoopTPToLoc", "LoopTPToPlayer"},
    DefLoopTP = {"FlyT", "DesyncT", "LoopTP", "LoopTPToLoc", "LoopTPToPlayer"},
    Desync = {"FlyT", "DesyncT", "LoopTP", "LoopTPToLoc", "LoopTPToPlayer"},
    Fakepos = {"FlyT", "DesyncT", "LoopTP", "LoopTPToLoc", "LoopTPToPlayer"},
    LoopTPToLoc = {"FlyT", "DesyncT", "LoopTP", "LoopTPToLoc", "LoopTPToPlayer"},
    LoopTPToPlayer = {"FlyT", "DesyncT", "LoopTP", "LoopTPToLoc", "LoopTPToPlayer"},
    NoclipT = {"NoclipT"}, ThirdPersonT = {"ThirdpersonT"}, InfJumpT = {"InfJumpT"},
    LoopSpectatePlayer = {"LoopSpectatePlayer"}, AutoSpinSlots = {"AutoSlotsT"},
    PlayAnimationT = {"AnimationToggle"}, ToggleExtendLine = {"ExtLineToggle"},
    CrazyLine = {"CrazyLineToggle"},
 ToyAurasT = {"ToggleTAuras"},
    ApplyExplosionTarget = {"AutoExpTarget"}, PoseApplyToTarget = {"AutoClicker"},
    PosePenis = {"CoconutFormsToggle"},
    AutoBreakHB = {"BreakBarrierT"}, AutoPreserveHouseTime = {"autohouse"},
    CustomBHToggle = {"EnableCBH"}, StayingBlackholesToggle = {"EnableBHStaying"},
    ShaderToggle = {"ShadersT"}, JerkOffT = {"JerkOffT"},
    FartherReachGP = {"FartherReach"}, MultiColorLineGP = {"GradientLineT"},
    EscapeFasterGP = {"FasterEscapeT"}, WhitelistToggle = {"WhitelistToggle"},
    AutoWhitelistFriends = {"AutoWhitelistFriends"},
    TriggerbotToggle = {"TriggerToggle"}, SilentAimToggle = {"SilentAim"},
    SA2Toggle = {"SilentAim"}, AB_Toggle = {"AimbotToggle"},
    NewESP_PlayerESP = {"PlrESPT"}, NewESP_PCLDESP = {"PCLDESPT"},
    NewESP_StickyESP = {"StickyESPT"}, LocalDisplay_DisableRagdollBlur = {"DisableBlurT"},
}

-- Native kick restore: old copied configs must never start a second target,
-- grab/aura kick or counter while the original Resonance worker is active.
local sourceKickOnly={TLApplyTarget=true,TLApplyServer=true,GrabsT=true,AurasT=true,DefCounterAttack=true,RagdollLoopToggle=true}
local nativeKickControls={LoopApplyMethodTSel=true,LoopApplyMethodTServ=true,LoopApplyMethodSel=true,LoopApplyMethodServ=true,RagdollNK=true,AntiKickRemoverNK=true,EKIToggle=true,RagdollInRG=true,CAToggle=true,ToggleGrabs=true,ToggleAuras=true,SupStrength=true}

local activationIds = {
    DefAntiRagdoll = true, AntiFling = true, ClaimSelectedPlot = true,
    TLApplyServer = true, LiquidGlassMenuToggle = true, CoinBoxDesign = true,
    GrabPlotCheckbox1 = true, GrabPlotCheckbox2 = true, GrabPlotCheckbox3 = true,
    GrabPlotCheckbox4 = true, GrabPlotCheckbox5 = true, WaterSplashToggle = true,
    BeachToggle = true, BeachAtmosphereSound = true, ForestToggle = true,
    ForestAtmosphereSound = true, ZoomT = true, RagdollLoopToggle = true,
    AutoClickerT = true, FreeGrabAnchoredParts = true, AutoCompileAnchoredParts = true,
    AimTrainerLoad = true, ProtectionGiveAntiGrab = true, ProtectionGiveAntiKick = true,
    PM370_Toggle = true, OL_Toggle = true, MT_Toggle = true,
    LocalDisplay_VisualizeLimbs = true,
}

function FeatureHost:TrackConnection(connection)
    if self.Disposed and connection then pcall(function() connection:Disconnect() end); return connection end
    if connection then self.Connections[connection] = true end
    return connection
end

function FeatureHost:TrackThread(thread)
    if self.Disposed and type(thread) == "thread" then pcall(task.cancel, thread); return thread end
    if type(thread) == "thread" then self.Threads[thread] = true end
    return thread
end

function FeatureHost:TrackInstance(instance)
    if self.Disposed and instance then pcall(function() instance:Destroy() end); return instance end
    if instance then self.Instances[instance] = true end
    return instance
end

function FeatureHost:BindRender(service, name, priority, callback)
    self.Bindings[name] = service
    return service:BindToRenderStep(name, priority, callback)
end

function FeatureHost:SetProperty(object, property, value)
    if typeof(object) == "Instance" and not self.Instances[object] then
        local values = self.Properties[object]
        if not values then values = {}; self.Properties[object] = values end
        if values[property] == nil then
            local ok, previous = pcall(function() return object[property] end)
            if ok then values[property] = {previous} end
        end
    end
    object[property] = value
end

function FeatureHost:SafeUnit(vector)
    local magnitude = vector.Magnitude
    if magnitude > 0 and magnitude < math.huge then return vector / magnitude end
    return Vector3.zero
end

function FeatureHost:GetFOV()
    if self.Context.GetFOV then
        local value = self.Context.GetFOV()
        if type(value) == "number" and value == value then return math.clamp(value, 1, 120) end
    end
    local original = self.Context.Library.Options.FOVsl
    if original then return original.Value end
    local camera = workspace.CurrentCamera
    return camera and camera.FieldOfView or 70
end

function FeatureHost:IsZoomActive()
    local control = self.Library and self.Library.Toggles.ZoomT
    return not self.Disposed and control ~= nil and control.Value == true
end

function FeatureHost:DisableAlternative(side, id)
    if self.Disposed or self.Changing then return end
    self.Changing = true
    if side == "Extra" then
        if id == "SilentAimToggle" or id == "SA2Toggle" then
            local sibling = self.Library.Toggles[id == "SilentAimToggle" and "SA2Toggle" or "SilentAimToggle"]
            if sibling and sibling.Value then sibling:SetValue(false) end
        end
        for _, otherId in ipairs(equivalents[id] or {}) do
            local other = self.Context.Library.Toggles[otherId]
            if other and other.Value then other:SetValue(false) end
        end
    else
        for otherId, originalIds in pairs(equivalents) do
            if table.find(originalIds, id) then
                local other = self.Library.Toggles[otherId]
                if other and other.Value then other:SetValue(false) end
            end
        end
    end
    self.Changing = false
end

function FeatureHost:GuardControl(control, side, id)
    if side == "Core" and nativeKickControls[id] then return end
    if not control or self.Guarded[control] then return end
    local old = control.SetValue
    if type(old) ~= "function" then return end
    self.Guarded[control] = old
    local bridge = self
    control.SetValue = function(item, value, ...)
        if bridge.Disposed and side == "Extra" and value then return end
        if value then bridge:DisableAlternative(side, id) end
        return old(item, value, ...)
    end
end

function FeatureHost:GuardAlternatives()
    for id, control in pairs(self.Library.Toggles) do self:GuardControl(control, "Extra", id) end
    for id, control in pairs(self.Context.Library.Toggles) do
        if not tostring(id):match("^SAV_") then self:GuardControl(control, "Core", id) end
    end
end

local UI = {}

local function methodOf(object, name)
    return object and object[name]
end

function FeatureHost:Wrap(object, kind, tabName)
    if not object then return nil end
    local wrapper = {_object = object, _bridge = self, _kind = kind, _tabName = tabName}
    return setmetatable(wrapper, {
        __index = function(item, key)
            local own = UI[key]
            if own then return own end
            local value = object[key]
            if type(value) == "function" then
                if (item._tabName=="Target" or item._tabName=="Blobman") and key=="OnClick" then return function()return item end end
                return function(_, ...) return value(object, ...) end
            end
            return value
        end,
        __newindex = function(_, key, value) object[key] = value end,
    })
end

function FeatureHost:PrepareInfo(id, info, kind)
    local result = copy(info)
    for _, field in ipairs({"Text", "Title", "Tooltip", "DisabledTooltip"}) do
        if type(result[field]) == "string" then result[field] = result[field]:gsub("Resonance", "astral"):gsub("Astral", "astral"):gsub("RESONANCE", "astral"):gsub("ASTRAL", "astral") end
    end
    if type(result.Text) == "string" and kind ~= "AddKeyPicker" then result.Text = result.Text .. " [astral]" end
    if kind == "AddKeyPicker" and type(result.Text) == "string" then
        result.Text = result.Text:gsub("%s*%[astral%]%s*$", "")
    end
    if kind == "AddDropdown" and result.AllowNull == nil then result.AllowNull = true end
    if kind == "AddCheckbox" or kind == "AddToggle" then
        if equivalents[id] or activationIds[id] or tostring(id):match("^TLMethod_") then
            result.Default = false
        end
    elseif kind == "AddKeyPicker" then
        result.Default = "None"
    end
    for _, field in ipairs({"Callback", "ChangedCallback", "Func"}) do
        local callback = result[field]
        local beginsZoom = id == "ZoomT" and field == "Callback"
        if type(callback) == "function" then
            local bridge = self
            result[field] = function(...)
                if bridge.Disposed then return end
                if beginsZoom and (...) and bridge.Context.BeginExtraZoom then bridge.Context.BeginExtraZoom() end
                return callback(...)
            end
        end
    end
    return result
end

function UI:_AddControl(kind, id, info)
    local bridge, object = self._bridge, self._object
    if id == "FovS" and bridge.Context.Library.Options.FOVsl then
        local shared = bridge.Context.Library.Options.FOVsl
        bridge.Library.Options[id] = shared
        return bridge:Wrap(shared, "Control", self._tabName)
    end
    local definition = bridge:PrepareInfo(id, info, kind)
    local suppressed = self._tabName == "Pose" or self._tabName == "Whitelist" or self._tabName == "Target" or self._tabName == "Blobman" or sourceKickOnly[id] or tostring(id):match("^TLMethod_")
    if suppressed then
        definition.Visible = false
        if kind == "AddCheckbox" or kind == "AddToggle" then definition.Default = false end
        if (self._tabName=="Target" or self._tabName=="Blobman") and kind~="AddCheckbox" and kind~="AddToggle" then
            definition.Callback=function()end;definition.ChangedCallback=function()end
        end
    end
    local method = methodOf(object, kind)
    assert(type(method) == "function", "astral UI method missing: " .. kind)
    local control = method(object, "SAV_" .. tostring(id), definition)
    if kind == "AddCheckbox" or kind == "AddToggle" then
        bridge.Library.Toggles[id] = control
        bridge:GuardControl(control, "Extra", id)
        if suppressed then
            local set = control.SetValue
            control.SetValue = function(item) return set(item, false) end
        end
        if id == "SilentAimToggle" and not (hookmetamethod and newcclosure and getnamecallmethod) then
            control:SetDisabled(true)
        end
    else
        bridge.Library.Options[id] = control
    end
    return bridge:Wrap(control, "Control", self._tabName)
end

for _, name in ipairs({"AddCheckbox", "AddToggle", "AddSlider", "AddDropdown", "AddInput", "AddKeyPicker", "AddColorPicker"}) do
    UI[name] = function(self, id, info) return self:_AddControl(name, id, info) end
end

function UI:AddButton(info, callback)
    if type(info) == "string" then info = {Text = info, Func = callback} end
    local definition = self._bridge:PrepareInfo(nil, info, "AddButton")
    if self._tabName=="Target" or self._tabName=="Blobman" then definition.Visible=false;definition.Func=function()end end
    return self._bridge:Wrap(self._object:AddButton(definition), "Button", self._tabName)
end

function UI:AddLabel(...)
    return self._bridge:Wrap(self._object:AddLabel(...), "Label", self._tabName)
end

function UI:AddImage(id, info)
    return self._bridge:Wrap(self._object:AddImage("SAV_" .. tostring(id), info), "Image", self._tabName)
end

function UI:AddUIPassthrough(id, info)
    return self._bridge:Wrap(self._object:AddUIPassthrough("SAV_" .. tostring(id), info), "Passthrough", self._tabName)
end

function UI:AddDependencyBox(...)
    return self._bridge:Wrap(self._object:AddDependencyBox(...), "Dependency", self._tabName)
end

function UI:AddDependencyGroupbox(...)
    return self._bridge:Wrap(self._object:AddDependencyGroupbox(...), "Dependency", self._tabName)
end

function UI:OnChanged(callback)
    if self._tabName=="Target" or self._tabName=="Blobman" then return self end
    local bridge = self._bridge
    return self._object:OnChanged(function(...)
        if bridge.Disposed then return end
        return callback(...)
    end)
end

function UI:AddTabbox(info)
    return self._bridge:Wrap(self._object:AddTabbox(info), "Tabbox", self._tabName)
end

function UI:AddLeftTabbox(name)
    return self._bridge:Wrap(self._object:AddLeftTabbox(plain(name) .. " [astral]"), "Tabbox", self._tabName)
end

function UI:AddRightTabbox(name)
    return self._bridge:Wrap(self._object:AddRightTabbox(plain(name) .. " [astral]"), "Tabbox", self._tabName)
end

function UI:AddTab(name, icon)
    return self._bridge:Wrap(self._object:AddTab(name, icon), "Groupbox", self._tabName)
end

function UI:_Group(side, name, icon, visible, collapsed, disableCollapsing)
    local bridge = self._bridge
    local title = plain(name) .. " [astral]"
    if self._tabName == "ESP" or self._tabName == "Aim" or self._tabName == "AimTrainer" then
        title = self._tabName .. ": " .. title
    end
    local method = side == "Left" and "AddLeftGroupbox" or "AddRightGroupbox"
    local group = self._object[method](self._object, title, icon, visible, collapsed, disableCollapsing)
    table.insert(bridge.Groupboxes, group)
    return bridge:Wrap(group, "Groupbox", self._tabName)
end

function UI:AddLeftGroupbox(...) return self:_Group("Left", ...) end
function UI:AddRightGroupbox(...) return self:_Group("Right", ...) end

function FeatureHost:NewLibrary()
    local bridge = self
    local library = {
        Options = {}, Toggles = {}, Tabs = {}, Registry = {}, KeybindToggles = {},
        Scheme = copy(self.Context.Library.Scheme), CornerRadius = self.Context.Library.CornerRadius,
        IsMobile = self.Context.Library.IsMobile, Unloaded = false, Toggled = true,
        ScreenGui = nil, SearchText = "", SearchTextRaw = "",
    }
    function library:CreateWindow() return bridge.Window end
    function library:GiveSignal(connection) return bridge:TrackConnection(connection) end
    function library:OnUnload(callback) table.insert(bridge.Cleanups, callback) end
    function library:Unload() return bridge.Context.Library:Unload() end
    function library:Notify(info, ...)
        if bridge.Disposed then return end
        if type(info) == "table" then
            info = copy(info)
            info.Title = "Astral"
            info.BigIcon = "sparkle"
        end
        return bridge.Context.Library:Notify(info, ...)
    end
    function library:GetCustomIcon(value) return bridge.Context.Library:GetCustomIcon(value) end
    function library:ApplyLucideIcon(...) return bridge.Context.Library:ApplyLucideIcon(...) end
    function library:SafeCallback(callback, ...) if callback then return callback(...) end end
    function library:UpdateSearch() return bridge.Context.Library:UpdateSearch(bridge.Context.Library.SearchText) end
    -- The presentation settings belong to Astral. No duplicate window,
    -- cursor, theme manager, command panel, footer or menu scale is installed.
    for _, name in ipairs({"SetDPIScale", "SetFont", "SetNotifySide", "UpdateColorsUsingRegistry", "MakeDraggable", "SetWatermark", "SetWatermarkVisibility"}) do
        library[name] = function() end
    end
    self.Library = library
    self.Window = {}
    function self.Window:AddTab(name)
        local label = plain(name)
        local targetName = tabMap[label]
        local target
        if targetName == "Internal" then
            if not bridge.InternalTab then
                bridge.InternalTab = bridge.Context.Library.Window:AddTab("Internal Compatibility", nil, "")
                bridge.InternalTab:SetVisible(false)
                bridge.InternalTab.Show = function() end
            end
            target = bridge.InternalTab
        else target = targetName and bridge.Context.Tabs[targetName] end
        assert(target, "Unmapped integration tab: " .. label)
        local tab = bridge:Wrap(target, "Tab", label)
        library.Tabs[name] = tab
        return tab
    end
    function self.Window:SetAnimations() end
    function self.Window:SetFooter() end
    function self.Window:SetTitle() end
end

function FeatureHost:Environment(host)
    local bridge = self
    local environment = setmetatable({}, {__index = host})
    environment._G = {}
    environment.shared = {}
    environment.getgenv = function() return environment end
    environment.Library = self.Library
    environment._G.SA2 = {}
    if type(host.setfflag) == "function" then
        environment.setfflag = function(name, value)
            if bridge.FlagRestores[name] == nil and type(host.getfflag) == "function" then
                local ok, previous = pcall(host.getfflag, name)
                if ok then bridge.FlagRestores[name] = {previous} end
            end
            return host.setfflag(name, value)
        end
    end
    local realHook = host.hookmetamethod
    if type(realHook) == "function" then
        environment.hookmetamethod = function(object, method, callback)
            local previous
            local function guarded(...)
                if bridge.Disposed then return previous(...) end
                return callback(...)
            end
            previous = realHook(object, method, host.newcclosure and host.newcclosure(guarded) or guarded)
            return previous
        end
    end
    self.EnvironmentTable = environment
    return environment
end

function FeatureHost:Dispose()
    if self.Disposed then return end
    -- Allow the source's own off callbacks to run before closing the guards.
    for _, toggle in pairs(self.Library.Toggles) do
        if toggle.Value and toggle.SetValue then pcall(toggle.SetValue, toggle, false) end
    end
    for _, cleanup in ipairs(self.Cleanups) do pcall(cleanup) end
    local env = self.EnvironmentTable
    if env then
        local desync = env._DESYNC
        if desync and (desync.enabled or desync._requestActive) then
            desync._requestActive = true
            pcall(desync.CancelRequest, desync)
        end
        for _, name in ipairs({"_ASTRAL_ACTION_WHEEL_CLEANUP", "_ASTRAL_COMMAND_PANEL_CLEANUP", "_AP_unanchorAll"}) do
            if type(env[name]) == "function" then pcall(env[name]) end
        end
    end
    self.Disposed = true
    self.Library.Unloaded = true
    for connection in pairs(self.Connections) do pcall(function() connection:Disconnect() end) end
    for name, service in pairs(self.Bindings) do pcall(function() service:UnbindFromRenderStep(name) end) end
    local current = coroutine.running()
    for thread in pairs(self.Threads) do
        if thread ~= current and coroutine.status(thread) ~= "dead" then pcall(task.cancel, thread) end
    end
    for instance in pairs(self.Instances) do pcall(function() instance:Destroy() end) end
    for instance, properties in pairs(self.Properties) do
        for property, previous in pairs(properties) do
            pcall(function()
                if property == "FieldOfView" and instance == workspace.CurrentCamera then
                    instance[property] = self:GetFOV()
                else instance[property] = previous[1] end
            end)
        end
    end
    local host = self.HostEnvironment
    if host and type(host.setfflag) == "function" then
        for name, previous in pairs(self.FlagRestores) do pcall(host.setfflag, name, previous[1]) end
    end
    -- Restore the native control methods when the integration is detached.
    for control, previous in pairs(self.Guarded) do control.SetValue = previous end
end

function FeatureHost.Install(context, gameplaySource)
    gameplaySource = gameplaySource or embeddedGameplay
    assert(type(setfenv) == "function", "Embedded features need setfenv for isolated state")
    local bridge = setmetatable({
        Context = context, Connections = setmetatable({}, {__mode = "k"}),
        Threads = setmetatable({}, {__mode = "k"}), Instances = setmetatable({}, {__mode = "k"}),
        Properties = setmetatable({}, {__mode = "k"}), Guarded = setmetatable({}, {__mode = "k"}),
        Bindings = {}, Cleanups = {}, Groupboxes = {}, FlagRestores = {}, Disposed = false, Changing = false,
    }, FeatureHost)
    bridge:NewLibrary()
    context.Library:OnUnload(function() bridge:Dispose() end)
    local chunk, message = loadstring(gameplaySource, "@Astral/ExtraFeatures")
    assert(chunk, message)
    local host = getfenv(0)
    bridge.HostEnvironment = host
    setfenv(chunk, bridge:Environment(host))
    local ok, result = xpcall(function() return chunk(bridge) end, function(err)
        return debug and debug.traceback and debug.traceback(tostring(err), 2) or tostring(err)
    end)
    if not ok then
        bridge:Dispose()
        for _, group in ipairs(bridge.Groupboxes) do pcall(function() group:Destroy() end) end
        error(result, 0)
    end
    if not bridge.Library.Toggles.LocalDisplay_VisualizeLimbs then
        bridge:Dispose()
        for _, group in ipairs(bridge.Groupboxes) do pcall(function() group:Destroy() end) end
        error("Embedded feature initialization stopped at a missing game dependency", 0)
    end
    bridge:GuardAlternatives()
    return bridge
end

return FeatureHost

