-- Actual FTAP rocket flight first; the optional drone is a local visual skin.
-- A real physics controller with finite forces and explicit gravity support.
-- https://create.roblox.com/docs/reference/engine/classes/LinearVelocity
local Flight={};Flight.__index=Flight
local kinds={BombMissile=true,FireworkMissile=true}
local forceClasses={BodyPosition=true,BodyVelocity=true,BodyGyro=true,BodyAngularVelocity=true,BodyForce=true,BodyThrust=true,
    RocketPropulsion=true,LinearVelocity=true,AngularVelocity=true,AlignPosition=true,AlignOrientation=true,VectorForce=true,Torque=true}
local function finite(n)return type(n)=="number"and n==n and math.abs(n)<math.huge end
local function alive(v)return v and v.Parent~=nil end
local function alpha(rate,dt)return 1-math.exp(-rate*math.clamp(dt,0,.1))end
function Flight.Install(context)
    local self=setmetatable({Context=context,Clock=context.Clock or os.clock,SpawnThread=context.SpawnThread or task.spawn,Wait=context.Wait or task.wait,
        Config={Enabled=false,AutoAttach=true,Speed=55,FastSpeed=95,Visual="Rocket",CameraDistance=12,CameraHeight=4,CameraFOV=80,TurnSensitivity=.0025,
            -- the server only keeps rocket ownership while your character is within grab range (~30 studs):
            -- the avatar trails the rocket so ownership never drops mid-flight
            FollowAvatar=true,FollowBack=10,FollowUp=2,ReturnAvatar=true,LossGrace=2.5},
        Generation=0,Pending=setmetatable({},{__mode="k"}),Ignored=setmetatable({},{__mode="k"}),Connections={},Status="Disabled",NextRequest=0},Flight)
    local function connect(signal,fn)if signal then local c=signal:Connect(fn);self.Connections[#self.Connections+1]=c end end
    connect(context.Workspace.DescendantAdded,function(v)self:Consider(v)end)
    connect(context.RunService.Heartbeat,function()self:Discover()end)
    local hasPhysics,physics=pcall(function()return context.RunService.PreSimulation end)
    connect(hasPhysics and physics or context.RunService.Heartbeat,function(dt)
        if self.Session then local ok,err=pcall(self.Step,self,dt);if not ok then self:Stop("Flight error: "..tostring(err))end end
    end)
    connect(context.RunService.RenderStepped,function(dt)
        if self.Session then local ok,err=pcall(self.CameraStep,self,dt);if not ok then self:Stop("Camera error: "..tostring(err))end end
    end)
    connect(context.Input.InputBegan,function(input,processed)
        if context.Input:GetFocusedTextBox()then return end
        if input.KeyCode==Enum.KeyCode.X and (self.Session or self.Starting)then self:Stop("Exited")
        elseif input.KeyCode==Enum.KeyCode.F and not processed and not self.Session then self:AttachUnderMouse()end
    end)
    connect(context.Input.InputChanged,function(input)
        local s=self.Session;if s and input.UserInputType==Enum.UserInputType.MouseMovement and not context.Input:GetFocusedTextBox()then s.Mouse+=Vector2.new(input.Delta.X,input.Delta.Y)end
    end)
    connect(context.Input.WindowFocusReleased,function()if self.Session then self:Stop("Window focus lost")end end)
    connect(context.Player.CharacterAdded,function()if self.Session or self.Starting then self:Stop("Character respawned")end end)
    return self
end
function Flight:OwnFolder()return self.Context.Workspace:FindFirstChild(self.Context.Player.Name.."SpawnedInToys")end
function Flight:Resolve(value)
    local node=value;local folder=self:OwnFolder()
    while node and node~=self.Context.Workspace do
        if node:IsA("Model")and kinds[node.Name]and folder and node:IsDescendantOf(folder)then return node end
        node=node.Parent
    end
end
function Flight:Validate(model)
    if not self:Resolve(model)then return nil,"Choose your own BombMissile or FireworkMissile"end
    local wedge=model:FindFirstChild("Wedge",true)
    if not wedge or not wedge:IsA("BasePart")then return nil,"Waiting for rocket Wedge"end
    local root=wedge.AssemblyRootPart or wedge
    if root.Anchored then return nil,"Rocket is still anchored"end
    if not root:IsDescendantOf(model)then return nil,"Release the rocket from your character first"end
    for _,p in ipairs(root:GetConnectedParts(true))do if not p:IsDescendantOf(model)then return nil,"Rocket has an external physical connection"end end
    for _,p in ipairs(model:GetDescendants())do
        if p:IsA("BasePart")and p.Name~="PartHitDetector"then
            local assembly=p.AssemblyRootPart or p
            if assembly~=root then return nil,"Rocket body is not one connected assembly"end
        elseif p:IsA("RigidConstraint")and p.Enabled~=false then
            for i=0,1 do local a;if i==0 then a=p.Attachment0 else a=p.Attachment1 end
                if a and a.Parent and a.Parent:IsA("BasePart")and not a.Parent:IsDescendantOf(model)then return nil,"Drop the held rocket first"end
            end
        end
    end
    local mass=root.AssemblyMass
    if not finite(mass)or mass<=0 or mass>1000000 then return nil,"Invalid rocket mass"end
    return root,wedge
end
function Flight:Request(root)
    local now=self.Clock();if now<self.NextRequest then return end
    self.NextRequest=now+.3
    local _,avatar,h=self.Context.Character()
    if not avatar or not h or h.Health<=0 or (root.Position-avatar.Position).Magnitude>30 then return end
    if self.Context.RequestOwner(root)then self.Requested=root end
end
function Flight:Consider(value)
    if not self.Config.Enabled or not self.Config.AutoAttach or self.Session or self.Spawning or self.Starting then return end
    local model=self:Resolve(value);if model and not self.Ignored[model]then self.Pending[model]=self.Pending[model]or self.Clock()end
end
function Flight:Discover()
    if self.Closed or not self.Config.Enabled or not self.Config.AutoAttach or self.Session or self.Starting or self.Spawning then return end
    for model,at in pairs(self.Pending)do
        if not model.Parent or self.Clock()-at>4 then self.Pending[model]=nil
        else local root=self:Validate(model)
            if root then local _,avatar=self.Context.Character()
                if avatar and ((root.Position-avatar.Position).Magnitude<=30 or self.Context.Owned(root))then self.Pending[model]=nil;self:Start(model);return end
            end
        end
    end
end
function Flight:SetEnabled(value)
    if self.Closed then return end
    self.Config.Enabled=value==true
    if not self.Config.Enabled then self:Stop("Disabled");self.Pending={};return end
    self.Ignored=setmetatable({},{__mode="k"})
    self.Status="Ready: spawn a rocket, use Spawn Controlled Rocket, or aim + F"
    local folder=self:OwnFolder();if folder then for _,v in ipairs(folder:GetChildren())do self:Consider(v)end end
end
function Flight:PrepareMovement(version)
    if self.Preparation then return end
    local preparation={Generation=version};self.Preparation=preparation
    local settle
    if self.Context.BeforeFlight then
        local restore;restore,settle=self.Context.BeforeFlight()
        preparation.Restore=type(restore)=="function"and restore or nil
    end
    local character,root,humanoid=self.Context.Character()
    settle=settle or not(character and root and root.Parent and not root.Anchored and humanoid and humanoid.Health>0
        and not humanoid.SeatPart and humanoid.Sit~=true and(not self.Context.MovementReady or self.Context.MovementReady()))
    if settle then
        local deadline=self.Clock()+4;local lastRoot,stableAt
        repeat
            if self.Closed or version~=self.Generation or not self.Config.Enabled then error("Flight preparation cancelled",0)end
            local character,root,humanoid=self.Context.Character()
            local ready=character and root and root.Parent and not root.Anchored and humanoid and humanoid.Health>0
                and not humanoid.SeatPart and humanoid.Sit~=true and(not self.Context.MovementReady or self.Context.MovementReady())
            if ready then
                if root~=lastRoot then lastRoot=root;stableAt=self.Clock()end
                if self.Clock()-stableAt>=.1 then return end
            else lastRoot=nil;stableAt=nil end
            self.Wait()
        until self.Clock()>=deadline
        error("Leave the seat and wait for your character to restore before flight",0)
    end
end
function Flight:Start(value)
    if self.Closed or not self.Config.Enabled or self.Spawning or self.Starting or self.Session then return false end
    local model=self:Resolve(value);if not model then self.Status="Aim at your own rocket";return false end
    self.Pending[model]=nil;self.Ignored[model]=nil;self.StartingTarget=model
    self.Generation+=1;local version=self.Generation;self.Starting=true;self.Status="Waiting for streamed rocket / acknowledged ownership";self.NextRequest=0
    self.SpawnThread(function()
        local ok,message=pcall(function()
            self:PrepareMovement(version)
            local deadline=self.Clock()+3;local root,wedge
            local firstRequest=true
            repeat
                if self.Closed or not self.Config.Enabled or version~=self.Generation then return end
                if not model.Parent then error("Rocket removed while waiting for ownership",0)end
                local _,_,h=self.Context.Character();if not h or h.Health<=0 then error("Character unavailable",0)end
                local reason;root,reason=self:Validate(model)
                if root then
                    wedge=reason
                    -- Establish the game's claim once, even when a freshly
                    -- replicated stationary part reports ReceiveAge == 0.
                    if firstRequest then self:Request(root);firstRequest=false end
                    if self:HasControl(root)then break end
                    self:Request(root);self.Status="Waiting for server ownership acknowledgement"
                else self.Status=reason end
                self.Wait(.05)
            until self.Clock()>=deadline
            if not root or not self:HasControl(root)then error(self.Status..". Come within 30 studs and retry.",0)end
            if version~=self.Generation then return end
