    self:Isolate(s)
    local function new(class)local v=Instance.new(class);s.Created[#s.Created+1]=v;s.Own[v]=true;return v end
    local a=new("Attachment");a.Name="AstralRocketControl";a.Parent=root
    local velocity=new("LinearVelocity");velocity.Name="AstralRocketVelocity";velocity.Enabled=false;velocity.Attachment0=a
    velocity.RelativeTo=Enum.ActuatorRelativeTo.World;velocity.VelocityConstraintMode=Enum.VelocityConstraintMode.Vector
    velocity.ForceLimitsEnabled=true;velocity.ForceLimitMode=Enum.ForceLimitMode.Magnitude;velocity.VectorVelocity=Vector3.zero;velocity.Parent=root
    local orient=new("AlignOrientation");orient.Name="AstralRocketOrientation";orient.Enabled=false;orient.Attachment0=a;orient.Mode=Enum.OrientationAlignmentMode.OneAttachment
    orient.RigidityEnabled=false;orient.ReactionTorqueEnabled=false;orient.Responsiveness=20;orient.MaxAngularVelocity=6;orient.Parent=root
    local gravity=new("VectorForce");gravity.Name="AstralRocketGravity";gravity.Enabled=false;gravity.Attachment0=a
    gravity.RelativeTo=Enum.ActuatorRelativeTo.World;gravity.ApplyAtCenterOfMass=true;gravity.Force=Vector3.zero;gravity.Parent=root
    s.VelocityControl,s.Orientation,s.Gravity=velocity,orient,gravity
    s.BodyCorrection,s.NoseAxis=self:OrientationCorrection(model,root,wedge)
    root.AssemblyLinearVelocity=Vector3.zero;root.AssemblyAngularVelocity=Vector3.zero
    local controls=self.Context.Controls and self.Context.Controls()
    if controls then s.Controls=controls;s.ControlsEnabled=controls.controlsEnabled~=false;controls:Disable()end
    local character,hrp,hum=self.Context.Character()
    if self.Config.FollowAvatar and character and hrp and hum then
        local a={Character=character,Root=hrp,Hum=hum,Start=hrp.CFrame,PlatformStand=hum.PlatformStand,Collide={}}
        for _,p in ipairs(character:GetDescendants())do if p:IsA("BasePart")then a.Collide[p]=p.CanCollide;p.CanCollide=false end end
        hum.PlatformStand=true;s.Avatar=a
    end
    camera.CameraType=Enum.CameraType.Scriptable;camera.FieldOfView=self.Config.CameraFOV
    self.Context.Input.MouseBehavior=Enum.MouseBehavior.LockCenter;self.Context.Input.MouseIconEnabled=false
    local function connect(signal,callback)if signal then s.ActiveConnections[#s.ActiveConnections+1]=signal:Connect(callback)end end
    connect(root.Touched,function(other)
        if not self.Session or self.Clock()-s.Started<.5 or not other then return end
        local character=self.Context.Player.Character
        if other:IsDescendantOf(model)or character and other:IsDescendantOf(character)then return end
        if other:IsA("Terrain")or other:IsA("BasePart")and other.CanCollide then
            if root.AssemblyLinearVelocity.Magnitude>8 or s.Velocity.Magnitude>8 then self:Impact(root.Position)end
        end
    end)
    connect(self.Context.Workspace.DescendantAdded,function(v)
        if self.Session==s and v:IsA("Explosion")and (v.Position-root.Position).Magnitude<18 then self:Stop("Game explosion")end
    end)
    self.Status="Flying real rocket · WASD + mouse · Space/Ctrl · X exit"
    self:Step(1/60);self:CameraStep(1, true)
    if self.Config.Visual=="Drone"then self:LoadSkin(s)end
end
function Flight:OrientationCorrection(model,root,wedge)
    local function part(name)
        local value=model:FindFirstChild(name,true)
        return value and value:IsA("BasePart")and value or nil
    end
    -- Wedge may be a wide fin, so its largest dimension does not identify the
    -- rocket's nose. Prefer the actual fuselage and a named nose/top marker.
    local body=part("Body")or part("Hitbox")or wedge
    local nose=part("Nose")or part("Tip")or part("NoseCone")or part("Warhead")or part("HitboxBodyTop")
    local tail=part("Engine")or part("Exhaust")or part("Thruster")or part("Tail")or body
    local forward=nose and nose~=tail and nose.Position-tail.Position
    if not forward or forward.Magnitude<.1 then
        local size=body.Size
        if size.Y>=size.X and size.Y>=size.Z then forward=body.CFrame.UpVector
        elseif size.X>=size.Z then forward=body.CFrame.RightVector
        else forward=-body.CFrame.LookVector end
    end
    local localForward=root.CFrame:VectorToObjectSpace(forward.Unit)
    local up=root.CFrame:VectorToObjectSpace(body.CFrame.UpVector)
    if math.abs(localForward:Dot(up))>.95 then up=root.CFrame:VectorToObjectSpace(body.CFrame.LookVector)end
    if math.abs(localForward:Dot(up))>.95 then up=root.CFrame:VectorToObjectSpace(body.CFrame.RightVector)end
    return CFrame.lookAt(Vector3.zero,localForward,up):Inverse(),localForward
end
function Flight:Impact(position)
    local s=self.Session;if not s or s.Detonated or self.Clock()-s.Started<.5 then return end
    s.Detonated=true;local requested=false
    local claim=self.Context.Owned(s.Root)
    if claim and self.Context.Detonate then local ok,result=pcall(self.Context.Detonate,s.Model,position);requested=ok and result~=false end
    self:Stop(requested and "Collision: native explosion requested"or "Collision: explosion unavailable")
end
function Flight:Follow(s)
    local a=s.Avatar;if not a then return true end
    local character,root,hum=self.Context.Character()
    if character~=a.Character or root~=a.Root or hum~=a.Hum or not alive(a.Root)or not alive(s.Root)then return false end
    local look=s.Facing and s.Facing.LookVector or Vector3.new(0,0,-1)
    local flat=Vector3.new(look.X,0,look.Z);if flat.Magnitude<.01 then flat=Vector3.new(0,0,-1)end;flat=flat.Unit
    local pos=s.Root.Position-flat*self.Config.FollowBack+Vector3.yAxis*self.Config.FollowUp
    a.Root.CFrame=CFrame.lookAt(pos,pos+flat)
    a.Root.AssemblyLinearVelocity=Vector3.zero;a.Root.AssemblyAngularVelocity=Vector3.zero
    for p in pairs(a.Collide)do if p.Parent and p.CanCollide then p.CanCollide=false end end
    return true
end
function Flight:Step(dt)
    local s=self.Session;if not s then return end
    local root=self:Validate(s.Model)
    local _,_,h=self.Context.Character()
    if root~=s.Root or not h or h.Health<=0 then self:Stop("Rocket/character unavailable");return end
    if not self:Follow(s)then self:Stop("Character root changed during flight");return end
    if not self:HasControl(root)then
        -- constraints stay on: a brief ownership flap no longer drops the rocket
        s.LostAt=s.LostAt or self.Clock();self:Request(root)
        self.Status="Rocket ownership lost; recovering"
        if self.Clock()-s.LostAt>self.Config.LossGrace then self:Stop("Server did not return rocket ownership");return end
    elseif s.LostAt then
        s.LostAt=nil;self.Status="Flying real rocket · WASD + mouse · Space/Ctrl · X exit"
    end
    self:Isolate(s);dt=math.clamp(dt,0,.1)
    local input=self.Context.Input;local focused=input:GetFocusedTextBox()
    if not focused then s.Yaw-=s.Mouse.X*self.Config.TurnSensitivity;s.Pitch=math.clamp(s.Pitch-s.Mouse.Y*self.Config.TurnSensitivity,-math.rad(70),math.rad(70))end
    s.Mouse=Vector2.zero
    local facing=CFrame.Angles(0,s.Yaw,0)*CFrame.Angles(s.Pitch,0,0);s.Facing=facing
    local function key(k)return not focused and input:IsKeyDown(Enum.KeyCode[k])and 1 or 0 end
    local move=facing.LookVector*(key("W")-key("S"))+facing.RightVector*(key("D")-key("A"))+Vector3.yAxis*(key("Space")-math.max(key("LeftControl"),key("C")))
    if move.Magnitude>1 then move=move.Unit end
    local speed=key("LeftShift")>0 and self.Config.FastSpeed or self.Config.Speed
    local target=move*speed;s.Velocity=s.Velocity:Lerp(target,alpha(8,dt))
    local mass=root.AssemblyMass;local gravity=math.max(self.Context.Workspace.Gravity,0)
    -- Gravity gets its own center-of-mass force. Horizontal acceleration and
    -- boost no longer consume the force budget that was holding altitude.
    s.Gravity.Force=Vector3.yAxis*(mass*gravity);s.Gravity.Enabled=true
    s.VelocityControl.MaxForce=mass*1800
    s.VelocityControl.VectorVelocity=s.Velocity;s.Orientation.MaxTorque=mass*math.clamp(s.Wedge.Size:Dot(s.Wedge.Size),4,400)*160
    s.Orientation.CFrame=facing*s.BodyCorrection;s.VelocityControl.Enabled=true;s.Orientation.Enabled=true
    if self.Clock()-s.Started>.5 then
        local travel=root.Position-s.Previous
        if travel.Magnitude>.05 then local hit=self.Context.Workspace:Raycast(s.Previous,travel,self:RayParams(s));if hit then self:Impact(hit.Position);return end end
    end
    if target.Magnitude>15 and (root.Position-s.Previous).Magnitude<.01 then s.Stuck=(s.Stuck or 0)+dt else s.Stuck=0 end
    s.Previous=root.Position
    if s.Stuck>3 then self:Stop("Rocket physics did not respond; ownership may be refused");return end
end
function Flight:RayParams(s)
    local p=RaycastParams.new();p.FilterType=Enum.RaycastFilterType.Exclude;p.RespectCanCollide=true;p.IgnoreWater=false
    local skip={s.Model};if self.Context.Player.Character then skip[#skip+1]=self.Context.Player.Character end;if s.Skin then skip[#skip+1]=s.Skin end
    p.FilterDescendantsInstances=skip;return p
end
function Flight:CameraStep(dt,instant)
    local s=self.Session;if not s or not s.Facing then return end
    local cam=self.Context.Workspace.CurrentCamera;if not cam then return end
    local root=s.Root;local origin=root.Position+Vector3.yAxis*1.5
    local wanted=root.Position-s.Facing.LookVector*self.Config.CameraDistance+Vector3.yAxis*self.Config.CameraHeight
    local delta=wanted-origin;local hit=self.Context.Workspace:Raycast(origin,delta,self:RayParams(s))
    if hit and delta.Magnitude>.01 then wanted=origin+delta.Unit*math.max((hit.Position-origin).Magnitude-.6,.5)end
    local frame=CFrame.lookAt(wanted,root.Position+s.Facing.LookVector*4,Vector3.yAxis)
    cam.CameraType=Enum.CameraType.Scriptable;cam.FieldOfView=self.Config.CameraFOV
    cam.CFrame=instant and frame or cam.CFrame:Lerp(frame,alpha(12,dt));cam.Focus=CFrame.new(root.Position)
    self.Context.Input.MouseBehavior=Enum.MouseBehavior.LockCenter
    if s.Skin and s.Skin.Parent then
        local pose=CFrame.new(root.Position)*s.Facing*s.SkinCorrection
        if s.Skin:IsA("Model")then s.Skin:PivotTo(pose)else s.Skin.CFrame=pose end
    end
end
function Flight:RestoreSkin(s)
    if s.Skin then s.Skin:Destroy();s.Skin=nil end
    for part,value in pairs(s.Hidden)do if part.Parent then part.LocalTransparencyModifier=value end end;s.Hidden={}
end
function Flight:LoadSkin(s)
    if s.Skin or s.Loading or not self.Context.LoadVisual then return end
    s.Loading=true
    self.SpawnThread(function()
        local ok,visual=pcall(self.Context.LoadVisual)
        s.Loading=false
        if not ok or not visual then if self.Session==s then self.Status="Flying real rocket · drone model unavailable"end;return end
        if self.Session~=s or self.Config.Visual~="Drone"then visual:Destroy();return end
        local success,message=pcall(function()
            local function prepare(p)p.Anchored=true;p.CanCollide=false;p.CanTouch=false;p.CanQuery=false;p.CastShadow=false end
            if visual:IsA("BasePart")then prepare(visual)end
            for _,p in ipairs(visual:GetDescendants())do
                if p:IsA("BasePart")then prepare(p)elseif p:IsA("Script")or p:IsA("LocalScript")or p:IsA("ModuleScript")then p:Destroy()end
            end
            if visual:IsA("Model")then
                local size=visual:GetExtentsSize();local scale=4.5/math.max(size.X,size.Y,size.Z,.01)
                visual:ScaleTo(visual:GetScale()*math.clamp(scale,.01,100))
                local cf=visual:GetBoundingBox();s.SkinCorrection=visual:GetPivot():ToObjectSpace(cf):Inverse()
            else s.SkinCorrection=CFrame.new()end
            visual.Name="AstralLocalDroneSkin";visual.Parent=self.Context.Workspace;s.Skin=visual
            for _,p in ipairs(s.Model:GetDescendants())do if p:IsA("BasePart")then s.Hidden[p]=p.LocalTransparencyModifier;p.LocalTransparencyModifier=1 end end
            self.Status="Flying rocket with local drone skin"
        end)
        if not success then visual:Destroy();self:RestoreSkin(s);self.Status="Flying real rocket · model setup failed: "..tostring(message)end
    end)
end
function Flight:SetVisual(value)
    if value~="Rocket"and value~="Drone"then return false end
    self.Config.Visual=value;local s=self.Session
    if s then if value=="Drone"then self:LoadSkin(s)else self:RestoreSkin(s);self.Status="Flying real rocket"end end;return true
end
function Flight:SpawnControlled()
    if self.Spawning or self.Starting or self.Session or self.Closed then return end
    if not self.Config.Enabled then self:SetEnabled(true)end
    if not self.Context.SpawnRocket then self.Status="Spawn a rocket from the game menu";return end
    self.Spawning=true;local version=self.Generation
    self.SpawnThread(function()
        local ok,model,reason=pcall(function()
            self:PrepareMovement(version)
            if self.Closed or not self.Config.Enabled or version~=self.Generation then return nil,"Flight cancelled"end
            return self.Context.SpawnRocket()
        end);self.Spawning=false
        if self.Closed or not self.Config.Enabled or version~=self.Generation then
            if ok and model and self.Context.DestroyRocket then pcall(self.Context.DestroyRocket,model)end;return
        end
        if ok and model then
            if not self:Start(model)then self:Stop(self.Status)end
        else self:Stop(ok and(reason or "Rocket spawn unavailable")or tostring(model))end
    end)
end
function Flight:AttachUnderMouse()
    local target=self.Context.Mouse and self.Context.Mouse.Target
    if target then return self:Start(target)end;self.Status="Aim at your own rocket and press F"
end
function Flight:Stop(reason)
    self.Generation+=1;self.Starting=false;self.Status=reason or "Exited"
    local s=self.Session;self.Session=nil
    if s then self.Ignored[s.Model]=true end
    if self.StartingTarget then self.Ignored[self.StartingTarget]=true;self.StartingTarget=nil end
    if s then
        for _,c in ipairs(s.ActiveConnections)do c:Disconnect()end
        for _,v in ipairs(s.Created)do pcall(v.Destroy,v)end
        self:RestoreSkin(s)
        local root=self:Validate(s.Model)
        for _,saved in ipairs(s.Native)do
            if root and alive(saved.Parent)then pcall(function()saved.Object.Parent=saved.Parent end)else pcall(saved.Object.Destroy,saved.Object)end
        end
        if s.Avatar then local a=s.Avatar
            pcall(function()
                for p,v in pairs(a.Collide)do if p.Parent then p.CanCollide=v end end
                local character,root,hum=self.Context.Character()
                local same=character==a.Character and root==a.Root and hum==a.Hum
                if same and alive(a.Hum)then a.Hum.PlatformStand=a.PlatformStand end
                if same and alive(a.Root)and self.Config.ReturnAvatar then
                    a.Root.CFrame=a.Start;a.Root.AssemblyLinearVelocity=Vector3.zero;a.Root.AssemblyAngularVelocity=Vector3.zero
                end
            end)
        end
        if s.Controls and s.ControlsEnabled then pcall(s.Controls.Enable,s.Controls)end
        if reason and reason~="Exited" and self.Context.Notify then pcall(self.Context.Notify,reason)end
        local cam=self.Context.Workspace.CurrentCamera
        if cam then
            cam.CameraType=s.CameraType or Enum.CameraType.Custom
            local subject=alive(s.Subject)and s.Subject or select(3,self.Context.Character())
            if subject then cam.CameraSubject=subject end
            cam.FieldOfView=s.FOV;cam.CFrame=s.CameraFrame;cam.Focus=s.Focus
        end
        self.Context.Input.MouseBehavior=s.MouseBehavior;self.Context.Input.MouseIconEnabled=s.MouseIcon
    end
    if self.Requested then local root=self.Requested;self.Requested=nil;if root.Parent and self.Context.ReleaseOwner then pcall(self.Context.ReleaseOwner,root)end end
    self:RestorePreparation()
    self.Pending={}
end
function Flight:Shutdown()
    if self.Closed then return end;self:Stop("Unloaded");self.Closed=true;for _,c in ipairs(self.Connections)do c:Disconnect()end;self.Connections={};self.Pending={}
end
function Flight:GetStatus()return {Active=self.Session~=nil,Starting=self.Starting or self.Spawning,Reason=self.Status,Recovering=self.Session and self.Session.LostAt~=nil}end
return Flight

