sources.WalkerBuilds = [========[
-- Real-toy body accessories plus different walking stances. The original
-- spider remains the default; no decorative part is used as fake physics.
local requireModule=...;local Layouts=requireModule("FigureLayouts")
local Builds={}
Builds.Names={"Spider","Crab","Scorpion","Beetle","Mantis","Turtle","Centipede","Butterfly","Dragonfly","DNA Helix","Atom","Saturn","Ferris Wheel","Radar Dish","Trident","Bloom","Cube Cage","Shield","Turbine","Solar System"}
Builds.Profiles={Spider={Spread=1,Depth=1,Height=1,Pairs=2},Crab={Spread=1.45,Depth=.65,Height=.65,Pairs=2,SideGait=true},
    Scorpion={Spread=1.1,Depth=1.4,Height=.8,Pairs=3,Layout="Scorpion Tail"},Beetle={Spread=.9,Depth=1.2,Height=.8,Pairs=3},
    Mantis={Spread=.85,Depth=1.3,Height=1.1,Pairs=2},Turtle={Spread=.85,Depth=1.1,Height=.55,Pairs=2},Centipede={Spread=.8,Depth=2.2,Height=.65,Pairs=4}}
for _,name in ipairs(Builds.Names)do if not Builds.Profiles[name]then Builds.Profiles[name]={Spread=1,Depth=1,Height=1,Pairs=2,Layout=name}end end
function Builds.Plan(name,item,mixed)
    local p=Builds.Profiles[name];if not p or name=="Spider"then return {}end
    if p.Layout then return Layouts.Plan(p.Layout,item,mixed and "Workshop"or "Selected Item")end
    if name=="Crab"or name=="Mantis"then return {"NinjaKatana","NinjaKatana","NinjaKunai","NinjaKunai"}end
    if name=="Beetle"or name=="Turtle"then return {"PalletLightBrown","PalletLightBrown","PalletLightBrown"}end
    if name=="Centipede"then return {"PalletLightBrown","PalletLightBrown","ToolPencil","ToolPencil"}end
    return {}
end
local mixedPlan=Builds.Plan
function Builds.Plan(name,item,mixed)
    local plan=mixedPlan(name,item,mixed)
    if not mixed then for i=1,#plan do plan[i]=item end end
    return plan
end
function Builds.Frames(name,length,phase,flight,count)
    local p=Builds.Profiles[name];local result={}
    if not p then return result end
    if p.Layout then
        if name=="Scorpion"and count and count<10 then
            local tail=math.max(1,count-2);local point=Vector3.new(0,-.5,1)
            for i=1,tail do
                local angle=(i-1)*.8;local nextPoint=point+Vector3.new(math.sin(phase*.5)*.08,math.sin(angle),math.cos(angle)).Unit*length
                result[#result+1]={Frame=Layouts.Frame({A=point,B=nextPoint},2),Axis=2};point=nextPoint
            end
            for _,side in ipairs({-1,1})do
                local a=Vector3.new(side*.6,0,-1);local z=a+Vector3.new(side,.2,-.6).Unit*length
                result[#result+1]={Frame=Layouts.Frame({A=a,B=z},2),Axis=2}
            end
            return result
        end
        local segments=Layouts.Segments(p.Layout,length,phase,flight)
        for i,segment in ipairs(segments)do result[i]={Frame=Layouts.Frame(segment,2),Axis=2}end
        return result
    end
    if name=="Crab"or name=="Mantis"then
        local high=name=="Mantis";local base=Vector3.new(0,high and 2 or .2,-2.5)
        for i,side in ipairs({-1,1})do
            local cf=CFrame.new(base+Vector3.new(side*1.5,0,0))*CFrame.Angles(high and -.35 or .2,side*(.45+math.sin(phase*.8)*.15),side*(high and .7 or .3))
            result[i]={Frame=cf*CFrame.new(0,length*.4,0),Axis=2}
            result[i+2]={Frame=cf*CFrame.new(side*.6,length*.65,-.3)*CFrame.Angles(0,0,side*math.sin(phase*1.3)*.4),Axis=2}
        end
    elseif name=="Beetle"or name=="Turtle"then
        for i=1,3 do result[i]={Frame=CFrame.new((i-2)*1.7,1.5,0)*CFrame.Angles(0,0,(i-2)*-.38),Flat=true}end
    elseif name=="Centipede"then
        result[1]={Frame=CFrame.new(0,0,4.5)*CFrame.Angles(0,math.sin(phase*.7)*.08,0),Flat=true}
        result[2]={Frame=CFrame.new(0,0,-4.5)*CFrame.Angles(0,-math.sin(phase*.7)*.08,0),Flat=true}
        for i,side in ipairs({-1,1})do result[i+2]={Frame=CFrame.new(side*.9,1,-6)*CFrame.Angles(-.6,0,side*.5),Axis=2}end
    end
    return result
end
function Builds.Prepare(name,pairs,item,mixed,budget)
    local profile=Builds.Profiles[name];if not profile then return end
    budget=math.clamp(math.floor(budget or 13),9,13)
    pairs=math.clamp(math.floor(pairs or profile.Pairs),profile.Pairs,4)
    local accessories=Builds.Plan(name,item,mixed)
    local figure=profile.Layout~=nil and name~="Scorpion"
    local segments=not figure and 2 or 0
    if not figure and 1+pairs*2*segments+#accessories>budget then segments=1 end
    local core=figure and 1 or 1+pairs*2*segments
    local count=math.min(#accessories,budget-core)
    local plan={"PalletLightBrown"}
    for i=2,core do plan[i]="LadderLightBrown"end
    for i=1,count do plan[#plan+1]=accessories[i]end
    return {Plan=plan,Figure=figure,Pairs=pairs,Segments=segments,Core=core,AccessoryCount=count}
end
return Builds

]========]
sources.PalletRagdoll = [========[
-- Shared native pallet. Kick requests keep striking; Apply remains one-shot.
local requireModule=...
local Source=requireModule("Resonance29Ragdoll")
local Ownership=requireModule("PalletOwnership")
local Stroke=requireModule("PalletStroke")
local Cadence=requireModule("PalletCadence")
local Reaction=requireModule("PalletReaction")
local Pallet={};Pallet.__index=Pallet
local CANCELLED={}
local function alive(part)return part and part.Parent and part:IsA("BasePart")end
local function state(character)
    local h=character and character.Parent and character:FindFirstChildOfClass("Humanoid")
    local value=h and h.Health>0 and h:FindFirstChild("Ragdolled")
    return value and value:IsA("BoolValue")and value
end
function Pallet.Install(context)
    local self=setmetatable({Context=context,Queue={},Entries={},Passes=0,ClearPasses=0,StrikeAttempts=0,Contacts=0,Confirmed=0,Misses=0,
        MaximumSpeed=context.MaximumSpeed==true,IntervalSeconds=.1,Status="Pallet ragdoll idle",
        RateAt=context.Clock(),RatePasses=0,RateContacts=0,PassRate=0,TouchRate=0,Pauses={}},Pallet)
    self.States=context.States or {}
    local available,physics=pcall(function()return context.RunService.PreSimulation end)
    self.FrameSignal=available and physics or context.RunService.Heartbeat
    self.Ownership=Ownership.new({Clock=context.Clock,Signal=self.FrameSignal,
        MarkerOwned=context.MarkerOwned or context.Owned,PhysicsOwned=context.PhysicsOwned or context.Owned,
        Grab=context.Grab or function()end,Busy=context.OwnershipBusy,Approach=context.Acquire,
        NeedsApproach=context.NeedsApproach,PingSeconds=context.PingSeconds})
    local function valid()
        local entry=self.Active
        return self:EntryValid(entry)
    end
    self.Native=Source.new({Data={States=self.States},Inventory={FindFirstChild=function()return self.Model and self.Model.Parent and self.Model or context.Find()end},Clock=context.Clock,
        API={
            SpawnToy=function()
                if not valid()then return end
                local allowed,reason=context.CanSpawn();if not allowed then self.Status=reason or "Waiting to spawn native pallet";return end
                local model=context.Spawn(valid)
                if model and not valid()then context.Destroy(model);return end
                if model then self.Model=model;self:Bind(model)end
                return model
            end,
            SNO=function(part)
                if not valid()or not alive(part)then return false end
                self:Bind(part.Parent)
                if context.Owned(part)then return true end
                local acquired,reason=self.Ownership:Acquire(part,valid)
                if not acquired then self.Status=reason;self.OwnershipReason=reason end
                return acquired and valid()
            end,
            DestroyToy=function(model)
                if model and model.Parent then
                    if self.Model==model then self:ForgetModel()end
                    return context.Destroy(model)
                end
            end,
        },
        Valid=valid,
        ContinueContact=function()return self:ContinuousValid(self.Active)end,
        ContinueAttempt=function()return #self.Queue==0 and self:ContinuousValid(self.Active)and Cadence.Ready(self.Active,context.Clock())end,
        SliceSeconds=function()return .2 end,
        CanContact=function(part)return valid()and alive(part)and not part.Anchored and context.Owned(part)end,
        Stroke=function(sound,main,torso,character,current)
            self:EndContact()
            self.StrokeFailure=nil
            local entry=self.Active
            local receiver,kind,receiverError=Reaction.Resolve(character)
            if not receiver then self.Status=tostring(receiverError);return false,receiverError end
            entry.Receiver=receiver;entry.ReceiverKind=kind
            local attempt
            local plan=Cadence.Plan(entry,context.PingSeconds and context.PingSeconds()or .1)
