sources.LocalModels = [========[
-- Cosmetic local overlay only: never replaces Player.Character, changes
-- movement/physics, writes network ownership or invokes gameplay remotes.
local requireModule=...
local Models={};Models.__index=Models
local definitions={['Tung Tung Tung Sahur']='SahurModel',['Aqua (CS:GO)']='AquaModel'}
function Models.ResolveChoice(value)
    if type(value)~='string'then return nil end
    if definitions[value]then return value end
    local key=value:lower():gsub('<[^>]+>',''):gsub('[^%w]','')
    if key=='aqua'or key=='aquacsgo'then return 'Aqua (CS:GO)'end
    if key=='sahur'or key=='tungtungtungsahur'then return 'Tung Tung Tung Sahur'end
    return nil
end
local function finite(n)return type(n)=="number"and n==n and math.abs(n)<math.huge end
function Models.Install(context)
    local self=setmetatable({Context=context,Enabled=false,Closed=false,Generation=0,Scale=1,AnimationSpeed=1,AnimeWalk=true,CrouchInput=true,HideFirstPerson=true,
        Choice="Tung Tung Tung Sahur",Hidden={},Connections={},WalkPhase=0,IdlePhase=0,WalkBlend=0,Speed=0,RunBlend=0,CrouchBlend=0,SitBlend=0,AirBlend=0,LeanX=0,LeanZ=0,Turn=0,LookYaw=0,LookPitch=0,Status="Disabled"},Models)
    self.Connection=context.BindRender(function(dt)
        if self.Closed or not self.Enabled then return end
        local ok,err=pcall(self.Step,self,dt)
        if not ok then self:Restore();if self.Renderer then self.Renderer:SetVisible(false)end;self.LastError=tostring(err);self.Status=self.Choice.." · Model error: "..self.LastError:sub(1,220) end
    end)
    return self
end
function Models:Restore()
    if self.DescendantConnection then self.DescendantConnection:Disconnect();self.DescendantConnection=nil end
    for part,value in pairs(self.Hidden)do
        pcall(function()if part.LocalTransparencyModifier==1 then part.LocalTransparencyModifier=value end end)
    end
    table.clear(self.Hidden);self.Character=nil
end
function Models:HidePart(part)
    if not part:IsA("BasePart")then return end
    if self.Hidden[part]==nil then self.Hidden[part]=part.LocalTransparencyModifier end
    part.LocalTransparencyModifier=1
end
function Models:Attach(character)
    if self.Character==character then return end
    self:Restore();self.Character=character
    for _,part in ipairs(character:GetDescendants())do self:HidePart(part)end
    self.DescendantConnection=character.DescendantAdded:Connect(function(part)if self.Enabled and self.Character==character then self:HidePart(part)end end)
    self.WalkPhase=0;self.WalkBlend=0;self.Speed=0;self.RunBlend=0;self.CrouchBlend=0;self.SitBlend=0;self.AirBlend=0;self.PreviousVelocity=nil;self.PreviousLook=nil;self.LeanX=0;self.LeanZ=0;self.Turn=0
end
function Models:SetChoice(value)
    if self.Closed then return end
    local resolved=Models.ResolveChoice(value)
    if not resolved then self.LastError='Unknown model selection: '..tostring(value);self.Status=self.LastError;return false end
    value=resolved
    if self.Choice==value then return true end
    self.Choice=value
    if self.Enabled then self:Retry()else self.Status="Selected: "..value end
    return true
end
function Models:SetEnabled(value)
    if self.Closed then return end
    value=value==true
    if value==self.Enabled and(value==false or self.Loading or self.Renderer)then return end
    self.Enabled=value;self.Generation+=1;local generation=self.Generation
    self:Restore();if self.Renderer then self.Renderer:Dispose();self.Renderer=nil end
    self.Loading=false
    if not value then self.Status="Disabled";return end
    local choice=self.Choice;self.LastError=nil
    self.Status="Loading "..choice.."…";self.Loading=true
    local function valid()return not self.Closed and self.Enabled and self.Generation==generation end
    self.Context.Spawn(function()
        if not valid()then return end
        local built
        local ok,err=pcall(function()
            local build=self.Context.BuildRenderer
            if not build then build=requireModule(assert(definitions[choice],"Unknown model: "..tostring(choice))).Build end
            built=build(self.Context.RendererContext,valid,function(text)if valid()then self.Status=choice.." · "..text end end)
            if not valid()then if built then built:Dispose()end;return end
            assert(built and type(built.Render)=="function","Requested model renderer is unavailable")
            assert(not built.Name or built.Name==choice,'Renderer mismatch: requested '..choice..', received '..tostring(built.Name))
            self.Renderer=built;self.Status=choice.." · Ready — waiting for your character"
        end)
        if not valid()then if built then built:Dispose()end;return end
        self.Loading=false
        if not ok then if built then built:Dispose()end;self.Renderer=nil;self.LastError=tostring(err);self.Status=choice.." · Model unavailable: "..self.LastError:sub(1,220) end
    end)
end
function Models:Retry()
    if self.Closed then return end
    if self.Enabled then self.Enabled=false;self:SetEnabled(true)end
end
function Models:Step(dt)
    if not self.Renderer then return end
    if self.Renderer.IsReady and not self.Renderer:IsReady()then
        self:Restore();self.Renderer:Dispose();self.Renderer=nil
        self.Status="Model removed; use Reload Model";return
    end
    if not finite(dt)or dt<=0 then return end;dt=math.min(dt,.1)
    local character,root,humanoid=self.Context.Character()
    if not character or not root or not humanoid or humanoid.Health<=0 or not root.Parent then
        self:Restore();self.Renderer:SetVisible(false);self.Status="Waiting for respawn";return
    end
    local renderer=self.Renderer
    local leg=character:FindFirstChild("Left Leg")
    local footOffset=leg and root.Size.Y*.5+leg.Size.Y or math.max(1,humanoid.HipHeight+root.Size.Y*.5)
    local velocity=root.AssemblyLinearVelocity
    local speed=Vector3.new(velocity.X,0,velocity.Z).Magnitude
    if not finite(speed)then speed=0 end
    local move=humanoid.MoveDirection and humanoid.MoveDirection.Magnitude or 0
    if move>.05 and speed<.2 then speed=math.min(humanoid.WalkSpeed,16)*move end
    self.Speed+=(math.clamp(speed,0,60)-self.Speed)*(1-math.exp(-dt*12))
    local seated=humanoid.Sit or humanoid.SeatPart~=nil
    local state=humanoid:GetState()
    local airborne=state==Enum.HumanoidStateType.Jumping or state==Enum.HumanoidStateType.Freefall
    local crouching=self.CrouchInput and self.Context.Crouching and self.Context.Crouching()and not seated
    local moving=self.AnimeWalk and self.Speed>.45 and not seated and not airborne
    local function smooth(value,target,rate)return value+(target-value)*(1-math.exp(-dt*rate))end
    self.WalkBlend=smooth(self.WalkBlend,moving and 1 or 0,12)
    self.RunBlend=smooth(self.RunBlend,moving and not crouching and math.clamp((self.Speed-(renderer.RunStart or 15))/(renderer.RunRange or 11),0,1)or 0,9)
    self.CrouchBlend=smooth(self.CrouchBlend,crouching and 1 or 0,13)
    self.SitBlend=smooth(self.SitBlend,seated and 1 or 0,12)
    self.AirBlend=smooth(self.AirBlend,airborne and 1 or 0,12)
    self.IdlePhase=(self.IdlePhase+dt*self.AnimationSpeed/4)%1
    if moving then self.WalkPhase=(self.WalkPhase+dt*math.clamp(self.Speed/7.7,.55,3.4)*self.AnimationSpeed*(crouching and .75 or 1))%1 end
    local idle=renderer:Sample("idle",self.IdlePhase)
    local pose=renderer:Blend(idle,renderer:Sample("walk",self.WalkPhase),self.WalkBlend)
    pose.Idle=self.IdlePhase;pose.Phase=self.WalkPhase;pose.Run=self.RunBlend
    pose.Crouch=self.CrouchBlend;pose.SitAmount=self.SitBlend;pose.Sit=seated;pose.Air=self.AirBlend
    local localVelocity=root.CFrame:VectorToObjectSpace(Vector3.new(velocity.X,0,velocity.Z))
    local acceleration=self.PreviousVelocity and(localVelocity-self.PreviousVelocity)/dt or Vector3.new(0,0,0)
    self.PreviousVelocity=localVelocity
    self.LeanX=smooth(self.LeanX,math.clamp(-acceleration.Z/220,-.14,.2),8)
    self.LeanZ=smooth(self.LeanZ,math.clamp(-acceleration.X/260,-.16,.16),8)
    local look=root.CFrame.LookVector
    local turn=0
    if self.PreviousLook then turn=math.atan2(self.PreviousLook:Cross(look).Y,self.PreviousLook:Dot(look))/dt end
    self.PreviousLook=look;self.Turn=smooth(self.Turn,math.clamp(turn/5,-1,1),10)
    pose.LeanX=self.LeanX;pose.LeanZ=self.LeanZ;pose.Turn=self.Turn
    pose.Strafe=self.Speed>.5 and math.clamp(localVelocity.X/math.max(self.Speed,.5),-1,1)or 0
    local hidden=false;local camera=self.Context.Camera()
    local yaw,pitch=0,0
    if camera then
        local view=root.CFrame:VectorToObjectSpace(camera.CFrame.LookVector)
        yaw=math.clamp(math.atan2(-view.X,-view.Z),-.9,.9)
        pitch=math.clamp(math.asin(math.clamp(view.Y,-1,1)),-.6,.6)
    end
    self.LookYaw=smooth(self.LookYaw,yaw,9);self.LookPitch=smooth(self.LookPitch,pitch,9)
    pose.LookYaw=self.LookYaw;pose.LookPitch=self.LookPitch
    local head=character:FindFirstChild("Head")
    if self.HideFirstPerson and camera and head then hidden=(camera.CFrame.Position-head.Position).Magnitude<1 end
    renderer:SetScale(self.Scale)
    local anchor=root.CFrame
    if renderer.Upright then
        local flatLook=Vector3.new(anchor.LookVector.X,0,anchor.LookVector.Z)
        if flatLook.Magnitude>.001 then anchor=CFrame.lookAt(root.Position,root.Position+flatLook.Unit)end
    end
    local rendered=renderer:Render(pose,anchor*CFrame.new(0,-footOffset,0),hidden)
    if rendered==false then self:Restore();self.Status="Model unavailable; use Reload Model";return end
    -- Hide the real skin only after the replacement was built, loaded and put
    -- at the correct position. Failure and loading leave the avatar visible.
    self:Attach(character)
    for part,value in pairs(self.Hidden)do
        if part:IsDescendantOf(character)then part.LocalTransparencyModifier=1
        else
            pcall(function()if part.LocalTransparencyModifier==1 then part.LocalTransparencyModifier=value end end)
            self.Hidden[part]=nil
        end
    end
    local activity=seated and "sitting"or crouching and "crouching"or airborne and "airborne"or self.RunBlend>.5 and "running"or moving and "walking"or "idle"
    self.Status=(renderer.Name or self.Choice).." · "..activity
    if renderer.RigidOnly then self.Status..=" · rigid asset: a rigged mesh is required"
    elseif renderer.HasFaceRig==false then self.Status..=" · static face texture"end
end
function Models:Describe()
    local info={RequestedModel=self.Choice,Loading=self.Loading,Enabled=self.Enabled,Status=self.Status,Error=self.LastError}
    if self.Renderer and self.Renderer.DescribeRig then info.Loaded=self.Renderer:DescribeRig()end
    return info
end
function Models:Dispose()
    if self.Closed then return end
    self:SetEnabled(false);self.Closed=true;self.Connection:Disconnect();self:Restore()
end
return Models

]========]
sources.GucciDestroy = [========[
-- Selected-player Gucci watcher. Uses the real character and native requests;
-- never destroys a remote toy locally or substitutes a YouDecoy/camera proxy.
local Guard={};Guard.__index=Guard
local kinds={GucciRSC=true,CreatureBlobman=true,TractorGreen=true,TractorRed=true,TractorOrange=true,Train=true,SantaSleigh=true}
local function seat(part)return part:IsA("Seat")or part:IsA("VehicleSeat")end
local function finite(p)return p.X==p.X and p.Y==p.Y and p.Z==p.Z and p.Magnitude<10000000 end
local function disconnect(list)for _,c in ipairs(list or {})do c:Disconnect()end end
function Guard.Install(context)
    local self=setmetatable({Context=context,Enabled=false,Closed=false,Generation=0,Folders={},Records={},NextRefresh=0,NextTrip=0,Requests=0,Observed=0,Status="Disabled"},Guard)
    self.Connection=context.RunService.Heartbeat:Connect(function()
        if self.Closed then return end
        local ok,err=pcall(self.Step,self)
        if not ok then self.Status="Destroy Gucci error: "..tostring(err);self:CancelTrip()end
        if self.Label then self.Label:SetText(self.Status..string.format("\nRequests: %d · removals observed: %d",self.Requests,self.Observed))end
    end)
    return self
end
function Guard:Allowed(player)return player and player.Parent and self.Context.Selected(player)and not self.Context.Protected(player)end
function Guard:Exists(record)
    return record.Model.Parent~=nil and record.Seat.Parent~=nil and record.Seat:IsDescendantOf(record.Model)
end
function Guard:ValidRecord(record)
    return self:Allowed(record.Player)and record.Folder.Parent and(record.Model==record.Folder or record.Model:IsDescendantOf(record.Folder))and self:Exists(record)
end
function Guard:Changed(record)
    record.Version+=1;record.Next=0;record.Failures=0
end
function Guard:Discover(model,folder,player)
    if not model:IsA("Model")or not kinds[model.Name]then return end
    local existing=self.Records[model]
    if existing then if self:Exists(existing)then return end;disconnect(existing.Connections);self.Records[model]=nil end
    local targetSeat=model:FindFirstChildWhichIsA("VehicleSeat",true)or model:FindFirstChildWhichIsA("Seat",true)
    if not targetSeat then return end
    local record={Model=model,Seat=targetSeat,Folder=folder,Player=player,Next=0,Version=0,Failures=0,Connections={}}
    self.Records[model]=record
    local function changed()if self.Enabled then self:Changed(record)end end
    record.Connections[#record.Connections+1]=targetSeat:GetPropertyChangedSignal("Occupant"):Connect(changed)
    record.Connections[#record.Connections+1]=targetSeat.ChildAdded:Connect(changed)
    record.Connections[#record.Connections+1]=targetSeat.ChildRemoved:Connect(changed)
    local function inspect(item)
        if item:IsA("RigidConstraint")then
            for _,prop in ipairs({"Attachment0","Attachment1","Enabled"})do record.Connections[#record.Connections+1]=item:GetPropertyChangedSignal(prop):Connect(changed)end
        elseif item.Name=="PartOwner"and item:IsA("StringValue")then record.Connections[#record.Connections+1]=item:GetPropertyChangedSignal("Value"):Connect(changed)end
    end
    for _,item in ipairs(model:GetDescendants())do inspect(item)end
    record.Connections[#record.Connections+1]=model.DescendantAdded:Connect(function(item)inspect(item);changed()end)
end
function Guard:Refresh()
    local wanted={}
    for _,player in ipairs(self.Context.Targets())do if self:Allowed(player)then
        local a,b=self.Context.Inventory(player)
        for _,folder in pairs({a,b})do if folder and folder.Parent then
            wanted[folder]=player
            if not self.Folders[folder]then
                local c=folder.DescendantAdded:Connect(function(item)
                    if not self.Enabled then return end
                    local node=item
                    while node and node~=folder do if node:IsA("Model")and kinds[node.Name]then self:Discover(node,folder,player);break end;node=node.Parent end
                end)
                self.Folders[folder]=c
            end
            for _,model in ipairs(folder:GetChildren())do self:Discover(model,folder,player)end
        end end
        local train=self.Context.SharedTrain and self.Context.SharedTrain()
        local _,_,h=self.Context.TargetCharacter(player);local current=h and h.SeatPart
        if train and current and current:IsDescendantOf(train)then self:Discover(train,train,player);wanted[train]=player end
    end end
    for folder,c in pairs(self.Folders)do if not wanted[folder]then c:Disconnect();self.Folders[folder]=nil end end
    for model,record in pairs(self.Records)do
        if not wanted[record.Folder]or not self:ValidRecord(record)then disconnect(record.Connections);self.Records[model]=nil end
    end
end
function Guard:KickHeld(record)
    return self.Context.KickHeld and self.Context.KickHeld(record.Player)==true
end
function Guard:Qualifies(record)
    if not self:ValidRecord(record)or self:KickHeld(record)then return false end
    local c,r,h=self.Context.TargetCharacter(record.Player)
    if not c or not r or not h or h.Health<=0 then return false end
    local s=record.Seat
    if record.PhysicsSent and s.Position.Y<-5000 then return false end
    local bound=h.SeatPart==s or s.Occupant==h
    for _,weld in ipairs(s:GetChildren())do if weld.Name=="SeatWeld"and(weld:IsA("Weld")or weld:IsA("WeldConstraint"))then
        local a,b=weld.Part0,weld.Part1
        if a and a:IsDescendantOf(c)or b and b:IsDescendantOf(c)then bound=true end
    end end
    -- Discover remote Gucci without interrupting a successfully held kick.
    -- Close ordinary shop vehicles are not candidates.
    if record.Model.Name=="GucciRSC"or bound and h.Sit==false or(record.Seat.Position-r.Position).Magnitude>1000 then record.Qualified=true end
    return record.Qualified==true and finite(s.Position)
end
function Guard:TripAllowed(trip)
    if self.Closed or not self.Enabled or trip.Restored or self.Generation~=trip.Generation or not self:Allowed(trip.Record.Player)then return false end
    if self:KickHeld(trip.Record)then trip.BlockedByKick=true;return false end
    return self:ValidRecord(trip.Record)
end
function Guard:TripValid(trip)
    if not self:TripAllowed(trip)then return false end
    local c,r,h=self.Context.Character()
    return c==trip.Character and r==trip.Root and h and h.Health>0 and r.Parent~=nil
end
function Guard:Restore(trip)
    if not trip or trip.Restored then return end
    trip.Restored=true
    local ok,c,r,h=pcall(self.Context.Character)
    if ok and trip.Return and c==trip.Character and r==trip.Root and h and h.Health>0 and r.Parent then
        pcall(self.Context.Teleport,r,trip.Return)
    end
    if trip.Borrowed then pcall(self.Context.ReleaseKick,trip)end
    if trip.RestoreMovement then pcall(trip.RestoreMovement)end
end
function Guard:CancelTrip()if self.Trip then self:Restore(self.Trip)end end
function Guard:SetEnabled(value)
    if self.Closed then return end;value=value==true
    if self.Enabled==value then return end
    if value and self.Context.BeforeEnable then self.Context.BeforeEnable()end
    self.Enabled=value;self.Generation+=1
    if not value then
        self:CancelTrip();for _,c in pairs(self.Folders)do c:Disconnect()end;self.Folders={}
        for _,r in pairs(self.Records)do disconnect(r.Connections)end;self.Records={};self.Status="Disabled"
    else self.NextRefresh=0;self.Status="Watching selected players' Gucci"end
end
function Guard:Start(record)
    if self.Closed or not self.Enabled or self.Busy or not self:Qualifies(record)then return false end
    self.Busy=true
    local trip={Record=record,Generation=self.Generation,Version=record.Version};self.Trip=trip
    self.Context.Spawn(function()
        local ok,err=pcall(function()
            if not self:TripAllowed(trip)then return end
            trip.Borrowed=self.Context.BorrowKick(trip)
            if not trip.Borrowed then self.Status="Waiting for current kick acquisition";return end
            if not self:TripAllowed(trip)then return end
            local restore,needsSettle=self.Context.PrepareMovement(trip)
            trip.RestoreMovement=restore
            if needsSettle then self.Context.Wait()end
            if not self:TripAllowed(trip)then return end
            local c,r,h=self.Context.Character();if not c or not r or not h or h.Health<=0 then return end
            trip.Character,trip.Root,trip.Humanoid,trip.Return=c,r,h,r.CFrame
            if not self:Qualifies(record)then return end
            self.Status="TP to "..record.Player.Name.."'s Gucci"
            if self.Context.Teleport(r,record.Seat.CFrame*CFrame.new(0,4,-4))==false then return end
            -- Give the engine a physical/rendered frame at the actual position
            -- before sending the request; no camera/clone teleport illusion.
            self.Context.Wait()
            if not self:TripValid(trip)or not self:ValidRecord(record)then return end
            if(record.Seat.Position-r.Position).Magnitude>=28 then self.Status="Character did not reach Gucci; retrying";return end
            if self.Context.RequestDelete(record.Model,function()return self:TripValid(trip)end)~=false then self.Requests+=1 end
            self.Status="Deletion requested; waiting for replication"
            local deadline=self.Context.Clock()+math.clamp(self.Context.PingSeconds()*.25,1/60,.05)
            repeat self.Context.Wait()until not self:TripValid(trip)or not self:Exists(record)or self.Context.Clock()>=deadline
            if not self:TripValid(trip)or not self:Exists(record)then return end
            if self.Context.DetachHeld and not self.Context.Detached(record.Model)then
                self.Context.DetachHeld(record.Model,function()return self:TripValid(trip)and self:ValidRecord(record)end)
            end
            if not self:TripValid(trip)or not self:ValidRecord(record)then return end
            if not self.Context.Detached(record.Model)or record.Seat.Anchored then
                self.Status="Request sent; waiting for the Gucci to detach";return
            end
            -- Acquire only from the real nearby position. The native far-SNO
            -- path (which hides avatar movement) is never used here.
            self.Context.Teleport(r,record.Seat.CFrame*CFrame.new(0,4,-4));self.Context.Wait()
            local function valid()return self:TripValid(trip)and self:ValidRecord(record)and(record.Seat.Position-r.Position).Magnitude<28 end
            if not valid()or not self.Context.Acquire(record.Seat,valid)then self.Status="Gucci ownership not acknowledged; retrying";return end
            if not valid()or not self.Context.Detached(record.Model)then return end
            self.Context.PhysicalDelete(record.Model,record.Seat,valid)
            record.PhysicsSent=true
            if self.Context.RequestDelete(record.Model,function()return self:TripValid(trip)end)~=false then self.Requests+=1 end
            local untilTime=self.Context.Clock()+math.clamp(self.Context.PingSeconds()*.5,.03,.1)
            repeat self.Context.Wait()until not self:TripValid(trip)or not self:Exists(record)or self.Context.Clock()>=untilTime
            self.Status=self:Exists(record)and "Removal requested; no server acknowledgement available"or "Gucci removal observed"
        end)
        local gone=not self:Exists(record)
        if gone then self.Observed+=1 end
        self:Restore(trip)
        if not ok and self.Enabled and trip.Generation==self.Generation then self.Status="Destroy Gucci: "..tostring(err)end
        if trip.BlockedByKick then
            record.Next=0;self.Status="Gucci paused: target is held by Kick"
        elseif not gone then
            record.Failures+=1
            if record.Version==trip.Version then record.Next=self.Context.Clock()+math.min(.25,.05*2^math.min(record.Failures-1,3))end
        end
        self.NextTrip=self.Context.Clock()
        if self.Trip==trip then self.Trip=nil end;self.Busy=false
    end)
end
function Guard:Step()
    if not self.Enabled or self.Busy then return end
    local now=self.Context.Clock();if now>=self.NextRefresh then self:Refresh();self.NextRefresh=now+.05 end
    if now<self.NextTrip then return end
    if self.Context.OperationBusy()then self.Status="Waiting for current ownership/spawn action";return end
    local best,held
    for _,r in pairs(self.Records)do
        if self:ValidRecord(r)and self:KickHeld(r)then held=true
        elseif now>=r.Next and self:Qualifies(r)and(not best or r.Next<best.Next)then best=r end
    end
    if best then self:Start(best)
    else self.Status=held and "Gucci paused: target is held by Kick"or "Watching for selected players' Gucci"end
end
function Guard:Dispose()
    if self.Closed then return end;self:SetEnabled(false);self.Closed=true;self.Connection:Disconnect()
end
return Guard

