sources.CharacterRoot = [========[
-- Resolve the current character every time. A surviving old model/root is not
-- evidence that it is still Player.Character, and roots can change in-place.
local Root={}
local function part(value,character)
    return typeof(value)=="Instance"and value:IsA("BasePart")and value.Parent and value:IsDescendantOf(character)
end
function Root.Get(player)
    local character=player and player.Character
    if not character or not character.Parent then return end
    local humanoid=character:FindFirstChildOfClass("Humanoid")
    for _,name in ipairs({"realHrp","saviHRP"})do
        local root=character:FindFirstChild(name)
        if part(root,character)then return character,root,humanoid end
    end
    local root=humanoid and humanoid.RootPart
    if not part(root,character)then root=character:FindFirstChild("HumanoidRootPart")end
    if not part(root,character)then root=nil end
    return character,root,humanoid
end
return Root

]========]
sources.DestroyDesync = [========[
-- A selected-target native ownership/ragdoll recovery attempt. This cannot
-- stop code on an opponent's client. Hidden-property readback is local proof
-- only, never a server acknowledgement that their desync was disabled.
local Destroy={};Destroy.__index=Destroy
local function finite(n)return type(n)=="number"and n==n and math.abs(n)<math.huge end
function Destroy.Install(context)
    local self=setmetatable({Context=context,States={},Cleanup={},Enabled=false,Supported=context.Supported~=false,
        Status=context.Supported==false and "Verified replication reset unavailable"or "Disabled",Elapsed=0,Applied=0,Verified=0},Destroy)
    self.Connection=context.RunService.Heartbeat:Connect(function(dt)
        if self.Closed or not self.Enabled and not next(self.Cleanup)then return end
        self.Elapsed+=dt;if self.Elapsed<.05 then return end;self.Elapsed=0
        self:FlushCleanup()
        if not self.Enabled then return end
        local ok,err=pcall(self.Step,self)
        if not ok then self:SetEnabled(false);self.LastError=tostring(err);self.Status="Destroy Desync stopped: "..self.LastError end
    end)
    return self
end
function Destroy:IsTarget(player)
    return not self.Closed and self.Enabled and self.Context.Selected(player)==true
end
function Destroy:Shared(state)
    local session=self.Context.KickSession(state.Player)
    return session and session.Character==state.Character and session.Root==state.Root
end
function Destroy:Valid(state)
    if not self:IsTarget(state.Player)or self.States[state.Player]~=state then return false end
    local c,r,h=self.Context.Character(state.Player)
    local actor,actorRoot,actorHum=self.Context.LocalCharacter()
    return c==state.Character and r==state.Root and h==state.Humanoid and h.Health>0
        and r.Parent~=nil and not r.Anchored and actor==state.Actor and actorRoot==state.ActorRoot
        and actorHum==state.ActorHumanoid and actorHum and actorHum.Health>0
end
function Destroy:Release(state)
    if not state.Requested then return true end
    if not state.Root.Parent or self:Shared(state)then state.Requested=false;self.Cleanup[state.Root]=nil;return true end
    local ok,err=pcall(self.Context.Release,state.Root)
    if ok then state.Requested=false;self.Cleanup[state.Root]=nil;return true end
    self.Cleanup[state.Root]=state;self.CleanupError=tostring(err)
    return false
end
function Destroy:FlushCleanup()
    local now=self.Context.Clock()
    for root,state in pairs(self.Cleanup)do
        local replacement=self.States[state.Player]
        if not root.Parent or self:Shared(state)then state.Requested=false;self.Cleanup[root]=nil
        elseif replacement and replacement~=state and replacement.Root==root then
            replacement.Requested=true;state.Requested=false;self.Cleanup[root]=nil
        elseif now>=(state.CleanupAt or 0)then
            state.CleanupAt=now+.2
            self:Release(state)
        end
    end
    if not next(self.Cleanup)then
        self.CleanupError=nil
        if not self.Enabled and self.Status=="Stopping; waiting to release native grab"then
            self.Status=self.LastError and("Destroy Desync stopped: "..self.LastError)or "Disabled"
        end
    elseif not self.Enabled then self.Status="Stopping; waiting to release native grab"end
end
function Destroy:Clear(player)
    local state=self.States[player];if not state then return end
    self.States[player]=nil -- cancel a yielding native acquisition first
    self:Release(state)
    if not self:Shared(state)then
        local ok,err=pcall(self.Context.CancelRagdoll,state.Character)
        if not ok then self.CancelError=tostring(err)end
    end
end
function Destroy:SetEnabled(value)
    local enabled=value==true and not self.Closed and self.Supported
    if enabled==self.Enabled then return self.Enabled end
    self.Enabled=enabled;self.Elapsed=0;self.LastError=nil
    if not self.Enabled then
        local players={};for p in pairs(self.States)do players[#players+1]=p end
        for _,p in ipairs(players)do self:Clear(p)end
        self.Status=self.Supported and "Disabled"or "Verified replication reset unavailable"
        if next(self.Cleanup)then self.Status="Stopping; waiting to release native grab"end
    end
    return self.Enabled
end
function Destroy:Acquire(state,now,ping)
    if self.Acquiring or state.Acquiring or now<(state.NextGrab or 0)then return end
    state.Requested=true;state.Acquiring=true;self.Acquiring=state
    state.NextGrab=now+math.clamp(ping,.1,.3)
    self.Context.Spawn(function()
        local ok,err=pcall(self.Context.Acquire,state.Root,function()
            return self:Valid(state)and not self:Shared(state)and not self.Context.Paused()
        end)
        state.Acquiring=false;if self.Acquiring==state then self.Acquiring=nil end
        if not ok then state.Message="Native acquisition failed: "..tostring(err)end
        if not self:Valid(state)and not self:Shared(state)then
            local replacement=self.States[state.Player]
            if not replacement or replacement.Root~=state.Root then
                if state.Root.Parent then state.Requested=true;self:Release(state)end
            end
        end
    end)
end
function Destroy:Update(state,localRoot,now,ping)
    local ctx=self.Context;local root=state.Root
    local shared=self:Shared(state)
    if shared then state.Requested=false end -- the existing kick owns cleanup
    if not self:Valid(state)then return end
    if self.Cleanup[root]then state.Message="Waiting to release the previous native grab";return end
    local position=root.Position
    if not finite(position.X)or not finite(position.Y)or not finite(position.Z)or position.Magnitude>1e7 then
        state.Message="Waiting for a valid replicated target position";return
    end
    local owned=ctx.Owned(root)
    local ragdoll=state.Humanoid:FindFirstChild("Ragdolled")
    local ragdolled=ragdoll and ragdoll.Value==true
    if not ragdolled and(owned or(position-localRoot.Position).Magnitude<=33)then
        ctx.RequestRagdoll(state.Character,function()return self:Valid(state)end)
    end
    if state.Acquiring then state.Message="Waiting for native ownership";return end
    if state.HoldUntil then
        if shared then state.HoldUntil=nil
        elseif now>=state.HoldUntil then
            self:Release(state);state.HoldUntil=nil;state.OwnedFrames=0;state.NextGrab=now+.2
            state.Message="Native attempt finished; opponent/server state unverified";return
        else return end
    end
    if owned then
        state.Deadline=nil
        state.ControlDeadline=state.ControlDeadline or now+math.clamp(.4+2*ping,.5,2)
        state.OwnedFrames=(state.OwnedFrames or 0)+1
        if not ragdolled then
            if not shared and state.Requested and now>=state.ControlDeadline then
                self:Release(state);state.ControlDeadline=nil;state.OwnedFrames=0;state.NextGrab=now+.2
                state.Message="Game ragdoll not acknowledged; retrying";return
            end
            state.Message="Ownership confirmed; waiting for game ragdoll";return
        end
        if state.OwnedFrames<2 then state.Message="Ownership confirmed; waiting for a physics frame";return end
        if now>=(state.NextReset or 0)then
            -- Recheck identity/ownership immediately before the only mutation.
            if not self:Valid(state)or ctx.Paused()or not ctx.Owned(root)then return end
            local ok,message,changed=ctx.Reset(root,function()return self:Valid(state)and not ctx.Paused()and ctx.Owned(root)end)
            state.NextReset=now+math.clamp(.25+ping,.3,.75)
            if ok then
                self.Verified+=1
                if changed==true then self.Applied+=1;state.Message="Local replication root changed; opponent/server state unverified"
                else state.Message="Replication root already clear locally; opponent/server state unverified"end
            else state.Message=message or "Replication reset unavailable"end
            if not shared and state.Requested then state.HoldUntil=now+math.clamp(ping,.05,.3)end
        end
        return
    end
    state.OwnedFrames=0;state.ControlDeadline=nil
    if shared then state.Message="Waiting for the existing kick's ownership";return end
    if state.Deadline and now>=state.Deadline then
        self:Release(state);state.Deadline=nil;state.NextGrab=now+.1
        state.Message="Ownership not acknowledged; retrying";return
    end
    if now<(state.NextGrab or 0)then return end
    state.Deadline=state.Deadline or now+math.clamp(.2+2*ping,.35,1.5)
    if(position-localRoot.Position).Magnitude>33 then self:Acquire(state,now,ping)
    else state.Requested=true;ctx.Grab(root);state.NextGrab=now+math.clamp(ping*.5,.05,.2)end
    state.Message="Waiting for native ownership"
end
function Destroy:Step()
    if not self.Enabled or self.Closed then return end
    local ctx=self.Context;local actor,localRoot,hum=ctx.LocalCharacter()
    if not actor or not localRoot or not hum or hum.Health<=0 then
        local players={};for p in pairs(self.States)do players[#players+1]=p end
        for _,p in ipairs(players)do self:Clear(p)end
        self.Status="Waiting for your character";return
    end
    local targets=ctx.Targets();local used={}
    for _,player in ipairs(targets)do if self:IsTarget(player)then used[player]=true end end
    local remove={};for p,state in pairs(self.States)do if not used[p]or not self:Valid(state)then remove[#remove+1]=p end end
    for _,p in ipairs(remove)do self:Clear(p)end
    if ctx.Paused()or ctx.Busy()then self.Status="Waiting for the active movement/ownership operation";return end
    local now=ctx.Clock();local ping=ctx.PingSeconds();ping=finite(ping)and math.clamp(ping,0,.5)or .1
    local count,last=0,nil
    for _,player in ipairs(targets)do if used[player]then
        local c,r,h=ctx.Character(player)
        if c and r and h and h.Health>0 and r.Parent and not r.Anchored then
            local state=self.States[player]
            if not state then state={Player=player,Character=c,Root=r,Humanoid=h,Actor=actor,ActorRoot=localRoot,ActorHumanoid=hum,NextGrab=0};self.States[player]=state end
            self:Update(state,localRoot,now,ping);count+=1;last=state.Message
        end
    end end
    self.Status=count==0 and "Select a living target"or(count==1 and(last or "Waiting for target")or("Targets: "..count.." | local resets: "..self.Applied))
end
function Destroy:Dispose()
    if self.Closed then return end
    self:SetEnabled(false);self:FlushCleanup();self.Closed=true;self.Connection:Disconnect()
end
return Destroy

